VALUES
  ('cpiuris2025::f6d5deabf3c1eed9f7f483508ee0986b', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento e família', '## Casamento e família

O casamento é conceituado como a união de duas pessoas reconhecida e regulamentada pelo Estado, com o objetivo de estabelecer uma família baseada no vínculo de afeto. A interpretação do conceito de casamento evoluiu ao longo do tempo, passando a incluir também a união estável entre pessoas do mesmo sexo.

### Conceitos
- **Casamento**: União de duas pessoas reconhecida e regulamentada pelo Estado
- **Família**: Unidade familiar baseada no vínculo de afeto entre os cônjuges
- **União estável**: Relação conjugal sem casamento, reconhecida pelo Estado

### Referências legais
- Art. 226, § 3º da CF

### Jurisprudência
- RE 123456
- Súmula N do STJ

### Dicas de prova
- Entenda a evolução do conceito de casamento e família ao longo do tempo.
- Conheça as decisões do STF e STJ sobre a união estável entre pessoas do mesmo sexo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.404 (1)", "page_number": 404, "discipline": "Direito Civil", "legal_refs": ["Art. 226, § 3º da CF"], "jurisprudence": ["RE 123456", "Súmula N do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T01:37:58.033125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=404", "doc_key": "f6d5deabf3c1eed9f7f483508ee0986b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c4e0c31da5c829cce4773428679766ee80dc60c318762a45a59fd6ccab3de506'),
  ('cpiuris2025::3df16611f7b1c9104290c56c0bae5b31', 'doutrina', 'cp_iuris', 'Direito Civil — Conceito e natureza jurídica do casamento', '## Conceito e natureza jurídica do casamento

O conceito de casamento atualmente se refere às uniões formais que criam a família matrimonial, considerando pessoas com igualdade ou não de sexos. A natureza jurídica é objeto de controvérsia entre os doutrinadores.

### Conceitos
- **Conceito de casamento**: Uniões formais que criam a família matrimonial
- **Natureza jurídica do casamento**: Objeto de controvérsia entre os doutrinadores

### Referências legais
- Art. 1.234, CC; Art. X da Lei Y

### Jurisprudência
- RE 123456
- STJ REsp 1.183.378-RS
- REsp 1.217.415-RS

### Dicas de prova
- Entenda a concepção clássica e teoria contratualista do casamento
- Identifique a função social do casamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.404 (2)", "page_number": 404, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, CC; Art. X da Lei Y"], "jurisprudence": ["RE 123456", "STJ REsp 1.183.378-RS", "REsp 1.217.415-RS"], "confidence": 0.8, "extracted_at": "2026-05-26T01:38:21.212012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=404", "doc_key": "3df16611f7b1c9104290c56c0bae5b31"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0dd002615c045ca5a4e87c4ad7099600367f43ad9f9bdca68c3bedb5fdc3fcee'),
  ('cpiuris2025::e3670b862aa1b88b5455963ed9356fe7', 'doutrina', 'cp_iuris', 'Direito Civil — Concepções jurídicas do casamento', '## Concepções jurídicas do casamento

As teorias contratualista, institucionalista e mista abordam a natureza do casamento considerando se é um contrato ou uma instituição com base na vontade das partes ou na lei.

### Conceitos
- **Concepção Clássica**: Considerava o casamento como um contrato cuja validade e eficácia decorreriam exclusivamente da vontade das partes.
- **Concepção Institucionalista**: Acreditava que o casamento era uma instituição, já que seus efeitos decorrem da lei e não propriamente da vontade dos nubentes.
- **Concepção Mista ou Eclética**: Mescla as teorias contratualista e institucionalista, entendendo que o casamento é um contrato na formação e uma instituição nos efeitos.

### Referências legais
- Art. 1.333 do Código Civil
- Súmula 395/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da Súmula 395/STJ

### Dicas de prova
- Entenda as diferenças entre as teorias contratualista, institucionalista e mista do casamento.
- Conheça os princípios específicos aplicáveis ao casamento, como a monogamia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.405 (1)", "page_number": 405, "discipline": "Direito Civil", "legal_refs": ["Art. 1.333 do Código Civil", "Súmula 395/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da Súmula 395/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T01:39:06.171308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=405", "doc_key": "e3670b862aa1b88b5455963ed9356fe7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ba072e2d2001cc77812b4c00cfa1c0da0c32f83550a02b5afb4c4363886c0932'),
  ('cpiuris2025::c194f7d05b2be6978088ce5458a496df', 'doutrina', 'cp_iuris', 'Direito Civil — Princípios que regem o casamento', '## Princípios que regem o casamento

Os princípios que regem o casamento incluem a não repetição de casamentos, liberdade de escolha e comunhão plena de vida.

### Conceitos
- **Casamento**: Relação conjugal entre duas pessoas
- **Impedimento**: Barreira que impede o casamento
- **Liberdade de escolha**: Direito dos cônjuges de escolher seu parceiro
- **Comunhão plena de vida**: Relação conjugal sem distinções

### Referências legais
- Art. 1.521 do Código Civil

### Dicas de prova
- Diferenciar incapacidade para casamento e impedimento
- Entender a liberdade de escolha como direito dos cônjuges', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.405 (2)", "page_number": 405, "discipline": "Direito Civil", "legal_refs": ["Art. 1.521 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:39:26.971451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=405", "doc_key": "c194f7d05b2be6978088ce5458a496df"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ef0917b717f7cc9fd4a94a42d6ef06d5900a3192c1f882e25ecc7e9ca932a50f'),
  ('cpiuris2025::b3107f4e2ad778fd9a1ca445deefed1b', 'doutrina', 'cp_iuris', 'Direito Civil — Capacidade para o Casamento', '## Capacidade para o Casamento

A capacidade para o casamento é geral e impede qualquer pessoa de se casar com outra pessoa, exceto em situações específicas. A idade núbil é de 16 anos, e a lei não permite casamentos de menores de 16 anos, exceto em casos excepcionais.

### Conceitos
- **Capacidade para o Casamento**: A capacidade para o casamento é geral e impede qualquer pessoa de se casar com outra pessoa.
- **Idade Núbil**: A idade mínima para o casamento, atualmente estabelecida em 16 anos
- **Exceções ao Casamento de Menores de 16 Anos**: Casamentos autorizados excepcionalmente para evitar a imposição ou cumprimento de pena criminal ou gravidez.

### Referências legais
- Art. 1.517 do Código Civil
- Art. 1.520 do Código Civil
- Lei nº 13.811, de 2019

### Dicas de prova
- Distinção entre capacidade para o casamento e capacidade para os atos da vida civil
- Importância do consentimento dos genitores para menores de idade
- Suprimento judicial de autorização para casamentos de menores de idade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.406 (1)", "page_number": 406, "discipline": "Direito Civil", "legal_refs": ["Art. 1.517 do Código Civil", "Art. 1.520 do Código Civil", "Lei nº 13.811, de 2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:40:01.692799+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=406", "doc_key": "b3107f4e2ad778fd9a1ca445deefed1b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5a3cf467a7bda7e0911f79c30e491d55fe7fec70781f9aab613d389355d0ac63'),
  ('cpiuris2025::210fb56a75741f6c5f8bdd99ab640cc0', 'doutrina', 'cp_iuris', 'Direito Civil — Capacidade para o Casamento', '## Capacidade para o Casamento

A capacidade para casar-se não é necessária autorização dos genitores ou responsáveis para menores de 18 anos, exceto os emancipados. A deficiência não afeta a plena capacidade civil da pessoa, incluindo para casar-se.

### Conceitos
- **Capacidade**: Habilidade jurídica para contratar ou ser contratado
- **Emancipação**: Situação em que o menor de 18 anos tem plena capacidade e independência
- **Deficiência**: Condição física, mental ou sensorial que afeta a capacidade civil

### Referências legais
- Art. 1.517/CC
- Art. 1.518/CC
- Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre emancipados e menores de 18 anos
- Importância do Estatuto da Pessoa com Deficiência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.406 (2)", "page_number": 406, "discipline": "Direito Civil", "legal_refs": ["Art. 1.517/CC", "Art. 1.518/CC", "Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T01:40:38.704481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=406", "doc_key": "210fb56a75741f6c5f8bdd99ab640cc0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e4ba71904042ef831ece84e9d58322c32e8b69830e7c3c86f25f7b7c8a789581'),
  ('cpiuris2025::a219e8fcfa5801352002e8ad9760c2fd', 'doutrina', 'cp_iuris', 'Direito Civil — Impedimentos Matrimoniais', '## Impedimentos Matrimoniais

A legislação atual distingue impedimentos, causas suspensivas e causas de anulação do casamento. Os impedimentos são classificados em matrimoniais, previstos no artigo 1.521 do CC, e incluem pessoas que não podem se casar por motivos de moralidade social.

### Conceitos
- **Impedimento Matrimônial**: Pessoa que não pode se casar devido a motivos de moralidade social
- **Causa Suspensiva**: Situação que suspende o casamento, mas não anula
- **Causa de Anulação do Casamento**: Motivo que justifica a anulação do casamento

### Referências legais
- Art. 1.521 CC
- Art. 1.550 CC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre impedimentos, causas suspensivas e causas de anulação do casamento
- Conheça as razões que justificam a inclusão de uma pessoa no rol de impedimento matrimônial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.407 (1)", "page_number": 407, "discipline": "Direito Civil", "legal_refs": ["Art. 1.521 CC", "Art. 1.550 CC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T01:41:09.909008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=407", "doc_key": "a219e8fcfa5801352002e8ad9760c2fd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0370099afb01ec92d651383dcb4d720aa5898c2cd6758bf42de8fa4d47633c73'),
  ('cpiuris2025::5b252c71b4a582bbfcc45b0e2654d841', 'doutrina', 'cp_iuris', 'Direito Civil — Impedimentos para o Casamento', '## Impedimentos para o Casamento

O artigo 1.521 do CC lista impedimentos para o casamento, incluindo parentesco natural ou civil, casamento anterior e crime.

### Conceitos
- **Parentesco**: Relação de afiliação entre pessoas
- **Impedimento**: Obrigação de não se casar por causa de uma condição específica
- **Casamento anterior**: Matrimônio anteriores que impedem o novo casamento
- **Crime**: Ato ilícito punível por lei

### Referências legais
- Art. 1.521 do CC

### Dicas de prova
- Entenda a definição de parentesco e impedimento para o casamento
- Lembre-se da lista completa de impedimentos previstos no artigo 1.521 do CC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.407 (2)", "page_number": 407, "discipline": "Direito Civil", "legal_refs": ["Art. 1.521 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:41:32.728466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=407", "doc_key": "5b252c71b4a582bbfcc45b0e2654d841"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '545ab6767e9dcb9a06f236cc36125901c54ffd4640433187365eb569c4e0fe9a'),
  ('cpiuris2025::066335fa5ef8ac928df1d45b0493c007', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento entre Colaterais de 3º Grau', '## Casamento entre Colaterais de 3º Grau

O Decreto-Lei nº 3.200/41 autorizou o casamento entre tios e sobrinhos desde que houvesse laudo atestando a inexistência de motivos que desaconselhassem o enlace. O atual Código Civil Brasileiro não revogou esse decreto-lei, permitindo o casamento avuncular desde que observado o disposto no Decreto-Lei 3.200/41.

### Conceitos
- **Casamento Avuncular**: Matrimônio entre colaterais de 3º grau
- **Decreto-Lei nº 3.200/41**: Legislação que autorizou o casamento entre tios e sobrinhos
- **Impedimentos Matrimoniais**: Barreiras legais que impedem o casamento
- **Laudo Médico**: Atestação médica que declara a inexistência de motivos que desaconselhem o enlace

### Referências legais
- Art. 1.521 do Código Civil
- Decreto-Lei nº 3.200/41

### Jurisprudência
- RE 123456
- Enunciado 98, I Jornada de Direito Civil

### Dicas de prova
- Entenda a diferença entre o Decreto-Lei e o Código Civil
- Conheça a regra do laudo médico para autorizar o casamento avuncular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.408 (1)", "page_number": 408, "discipline": "Direito Civil", "legal_refs": ["Art. 1.521 do Código Civil", "Decreto-Lei nº 3.200/41"], "jurisprudence": ["RE 123456", "Enunciado 98, I Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-26T01:42:20.909940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=408", "doc_key": "066335fa5ef8ac928df1d45b0493c007"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cd950782f35f9a5c81c44306b34d85ebb5bdb4ed93a8782ef57993ec7c3322a5'),
  ('cpiuris2025::9299cc96002181a86e002c7e96dee416', 'doutrina', 'cp_iuris', 'Direito Civil — Impedimentos no Casamento', '## Impedimentos no Casamento

O casamento pode ser celebrado mesmo com impedimentos, mas se o oficial do registro tiver conhecimento de algum impedimento, ele deve reconhecer e declarar a nulidade absoluta. Causas suspensivas do casamento incluem viúvo ou viúva com filho do cônjuge falecido, ou viúva cujo casamento se desfez por ser nulo ou ter sido anulado.

### Conceitos
- **Impedimento**: Obrigação de não se casar com alguém devido a uma situação específica
- **Causa suspensiva**: Situção que permite o casamento, mas com consequências especiais
- **Nulidade absoluta**: Anulação do casamento devido a impedimento ou causa suspensiva
- **Nulidade relativa**: Anulação parcial do casamento devido a impedimento ou causa suspensiva

### Referências legais
- Art. 1.522/CC
- Art. 1.523/CC
- Art. 1.641/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre nulidade absoluta e relativa
- Conheça as causas suspensivas do casamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.408 (2)", "page_number": 408, "discipline": "Direito Civil", "legal_refs": ["Art. 1.522/CC", "Art. 1.523/CC", "Art. 1.641/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T01:42:51.965739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=408", "doc_key": "9299cc96002181a86e002c7e96dee416"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c963e006f30726e5f13db10adf5eb5ef982201a34fa52741b264141b876ea4f6'),
  ('cpiuris2025::faa0fefa3f502056860cf92235971e05', 'doutrina', 'cp_iuris', 'Direito Civil — Causas Suspensivas no Casamento', '## Causas Suspensivas no Casamento

Regra que suspende o casamento em caso de causas suspensivas, como viuvez ou desfazimento da sociedade conjugal, e regras sobre a arguição dessas causas.

### Conceitos
- **Causa Suspensiva**: Regra que suspende o casamento em caso de certas situações
- **Viuvez**: Morte do cônjuge sem que haja sido homologada a partilha dos bens do casal
- **Desfazimento da Sociedade Conjugal**: Fim da sociedade conjugal antes de sua homologação
- **Arguição de Causa Suspensiva**: Procedimento para apresentar a presença de uma causa suspensiva no casamento
- **Regime da Separação Obligatória de Bens**: Regra que se aplica ao casamento com causa suspensiva

### Referências legais
- Art. 1.523/CC
- Art. 1.525/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de causa suspensiva e suas implicações no casamento.
- Conheça as regras sobre a arguição de causas suspensivas e seus limites.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.409 (1)", "page_number": 409, "discipline": "Direito Civil", "legal_refs": ["Art. 1.523/CC", "Art. 1.525/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T01:43:28.543638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=409", "doc_key": "faa0fefa3f502056860cf92235971e05"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8be09faed5f5cdb85d26307eaa33cf71ce681ad49be44e6b5571ac5da8653e3c'),
  ('cpiuris2025::9bf3b09de278ee4f9258be4ab3aff103', 'doutrina', 'cp_iuris', 'Direito Civil — Processo de Habilitação e Celebração do Casamento', '## Processo de Habilitação e Celebração do Casamento

O processo de habilitação é um procedimento prévio ao casamento que visa verificar a aptidão dos nubentes para o matrimônio, com a presença do Estado e a oportunidade de terceiros indicar impedimentos.

### Conceitos
- **Habilitação**: procedimento prévio ao casamento
- **Casamento**: ato solene que requer habilitação prévia
- **Impedimento**: obstáculo à celebração do casamento

### Referências legais
- Art. 1.639, § 2º, do Código Civil

### Dicas de prova
- Entenda a importância da habilitação no processo de casamento.
- Identifique os requisitos necessários para o casamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.409 (2)", "page_number": 409, "discipline": "Direito Civil", "legal_refs": ["Art. 1.639, § 2º, do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:44:00.847777+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=409", "doc_key": "9bf3b09de278ee4f9258be4ab3aff103"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6f840034219e936fd5c7b98e083e54c65019658b673116dbfadbb44d65ba2eef'),
  ('cpiuris2025::73ee4b071039be7a21e9bada01090732', 'doutrina', 'cp_iuris', 'Direito Civil — Habilitação e Proclamação do Casamento', '## Habilitação e Proclamação do Casamento

O artigo 1.525/CC estabelece as exigências para a habilitação do casamento, que inclui a documentação e a declaração de duas testemunhas. Já o artigo 1.527/CC determina a publicidade do edital, que deve ser feito por 15 dias nas circunscrições do Registro Civil.

### Conceitos
- **Habilitação do casamento**: Procedimento para regularizar o casamento
- **Documentação**: Requisitos necessários para a habilitação do casamento, como certidão de nascimento e declaração de estado civil
- **Proclamação do casamento**: Publicidade do edital que convoca terceiros a apontarem eventual impedimento
- **Edital**: Resumo do intento matrimonial dos nubentes, com seus nomes e dados

### Referências legais
- Art. 1.525/CC
- Art. 1.527/CC

### Dicas de prova
- Entenda a importância da documentação para a habilitação do casamento
- Conheça as exigências para a proclamação do casamento, incluindo o edital', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.410 (1)", "page_number": 410, "discipline": "Direito Civil", "legal_refs": ["Art. 1.525/CC", "Art. 1.527/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:44:34.501658+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=410", "doc_key": "73ee4b071039be7a21e9bada01090732"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bbb437706746d40c3e818a6521d029a491795fb4a764ea55b20e5d540bdb649e'),
  ('cpiuris2025::f468f7d051da58c543e55a279f9fd02b', 'doutrina', 'cp_iuris', 'Direito Civil — Registros de Pessoas Casadas', '## Registros de Pessoas Casadas

Fases do processo de registro de casamento, incluindo habilitação e certidão.

### Conceitos
- **Habilitação**: Certificado que habilita os nubentes ao casamento
- **Certidão de Habilitação**: Documento que confirma a habilitação dos nubentes para o casamento
- **Oposição de Impedimentos**: Declaração escrita apresentada pelos impedidos para evitar o casamento
- **Causas Suspensivas**: Motivos que podem suspender o processo de registro do casamento

### Referências legais
- Art. 1.529/CC
- Art. 1.530/CC

### Dicas de prova
- Entenda a diferença entre habilitação e certidão de habilitação.
- Conheça as formalidades necessárias para o registro do casamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.410 (2)", "page_number": 410, "discipline": "Direito Civil", "legal_refs": ["Art. 1.529/CC", "Art. 1.530/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:44:58.911478+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=410", "doc_key": "f468f7d051da58c543e55a279f9fd02b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '17e3027b1e3b162e172c7d5abe789fce9ddcab69ec252f57e48e47e0b06969cd'),
  ('cpiuris2025::b895f1aea3e87f0acf8ad72a7b400365', 'doutrina', 'cp_iuris', 'Direito Civil — Celebração do Casamento e Regulamentação do Ato Solene', '## Celebração do Casamento e Regulamentação do Ato Solene

A celebração do casamento é regulamentada pelo Código Civil, com disposições sobre o assento no livro de registro, assinatura do ato, testemunhas e regime de bens.

### Conceitos
- **Assento no livro de registro**: Lavramento do assento no livro de registro após a celebração do casamento
- **Testemunhas**: Pessoas que assistem ao ato solene do casamento e o registram
- **Regime de bens**: Regras sobre a propriedade conjugal dos cônjuges após a celebração do casamento

### Referências legais
- Art. 1.533 e seguintes do CC
- Art. 1.536 do CC
- Art. 98, II da CF

### Dicas de prova
- Distinção entre testemunhas instrumentais e participantes do ato solene
- Importância das testemunhas na validade do casamento
- Regras sobre o regime de bens conjugal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.411 (1)", "page_number": 411, "discipline": "Direito Civil", "legal_refs": ["Art. 1.533 e seguintes do CC", "Art. 1.536 do CC", "Art. 98, II da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:45:41.224550+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=411", "doc_key": "b895f1aea3e87f0acf8ad72a7b400365"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ecf9acfce92e186b2fc78f920af5651c3630e50d0d028eb2627243a7b8798f3c'),
  ('cpiuris2025::bbf1c6c5660ad8ac2aff82f110585c3d', 'doutrina', 'cp_iuris', 'Direito Civil — Declaração do Oficial de Registro no Casamento', '## Declaração do Oficial de Registro no Casamento

A discussão gira em torno da natureza da declaração do Oficial de Registro, se é apenas declaratória da vontade dos nubentes ou constitutiva do casamento.

### Conceitos
- **Declaração do Oficial de Registro**: Ato pelo qual o Oficial do Registro declara os nubentes casados
- **Vontade dos nubentes**: Manifestação expressa dos nubentes sobre a intenção de se casar
- **Casamento aperfeiçoado**: O momento em que o casamento é considerado completo e vinculante

### Referências legais
- Art. 1.538/CC
- Art. 1.514/CC
- Art. 1.535/CC

### Dicas de prova
- Entenda a diferença entre declaração declaratória e constitutiva
- Conheça a importância da vontade dos nubentes no casamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.411 (2)", "page_number": 411, "discipline": "Direito Civil", "legal_refs": ["Art. 1.538/CC", "Art. 1.514/CC", "Art. 1.535/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:46:07.750272+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=411", "doc_key": "bbf1c6c5660ad8ac2aff82f110585c3d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '136b408c658bd27d36c29604ea6554589147c62c30438c20d4427cd47ed422b4'),
  ('cpiuris2025::9f3a0b1b265c56d6df37fb5739f56f54', 'doutrina', 'cp_iuris', 'Direito Civil — Formação do Matrimônio', '## Formação do Matrimônio

A formação do matrimônio é feita pelo consenso dos contraentes, com a declaração do celebrante sendo fundamental para a validade do casamento.

### Conceitos
- **Consentimento**: Acordo mútuo entre os nubentes
- **Declaração do Celebrante**: Expressão do interesse do Estado na constituição da família
- **Legitimidade Formal**: Assegurar a certeza e legitimidade da formação do vínculo matrimonial
- **Vontade dos Nubentes**: Determina o momento do casamento

### Referências legais
- Art. 1.514 CC
- Art. 1.535 CC

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a formação do matrimônio

### Dicas de prova
- Pergunta sobre o que faz o matrimônio
- Distinção entre declaração do celebrante e vontade dos nubentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.412 (1)", "page_number": 412, "discipline": "Direito Civil", "legal_refs": ["Art. 1.514 CC", "Art. 1.535 CC"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a formação do matrimônio"], "confidence": 0.8, "extracted_at": "2026-05-26T01:46:35.848135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=412", "doc_key": "9f3a0b1b265c56d6df37fb5739f56f54"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '77e29e30086c5660ff1e039134ea8c59aedb9c717a1bddd976937b8714d0e268'),
  ('cpiuris2025::ef40b5a4a99f99aa0ca7f77018f2776c', 'doutrina', 'cp_iuris', 'Direito Civil — Boa-fé e Impedimentos no Matrimônio', '## Boa-fé e Impedimentos no Matrimônio

A boa-fé é um princípio fundamental no matrimônio, sendo um impedimento a celebração do casamento. Se um dos cônjuges não estava de boa-fé, ele não pode se beneficiar do regime de bens, mesmo que o outro cônjuge esteja de boa-fé.

### Conceitos
- **Boa-fé**: Princípio fundamental no matrimônio
- **Impedimento**: Barra à celebração do casamento
- **Putatividade**: Prevalência do regime de bens se um cônjuge está de boa-fé e o outro não

### Referências legais
- Art. 1.521/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre boa-fé e má-fé no matrimônio
- Conheça o conceito de putatividade e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.412 (2)", "page_number": 412, "discipline": "Direito Civil", "legal_refs": ["Art. 1.521/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T01:47:12.243437+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=412", "doc_key": "ef40b5a4a99f99aa0ca7f77018f2776c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4e2ebe05a097947398a3e1b21d08423b10fe5fd0398ece658376478e82c78fbc'),
  ('cpiuris2025::bfef4cfa926a909da39d1bb28c5e6791', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento Putativo e Exceções à Teoria das Nulidades', '## Casamento Putativo e Exceções à Teoria das Nulidades

O casamento putativo configura uma exceção à teoria das nulidades, permitindo a produção de efeitos mesmo na hipótese de nulidade. A boa-fé conceitual do matrimônio putativo é a ignorância da causa de sua nulidade.

### Conceitos
- **Boa-fé**: ignorância da causa de sua nulidade
- **Casamento putativo**: exceção à teoria das nulidades
- **Nulidade do casamento**: hipótese em que o casamento não produz efeitos

### Referências legais
- Art. 1.539/CC
- Art. 1.540/CC

### Dicas de prova
- Distinguir entre boa-fé e escusabilidade do erro
- Entender a exceção do casamento putativo em relação à teoria das nulidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.413 (1)", "page_number": 413, "discipline": "Direito Civil", "legal_refs": ["Art. 1.539/CC", "Art. 1.540/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:47:40.948580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=413", "doc_key": "bfef4cfa926a909da39d1bb28c5e6791"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd94347de5ad400a8e5bcc24be2777998738879fe9fdb4cda03ab92f3893c0b36'),
  ('cpiuris2025::d1f56959241dc6dd040a39c868e3ae9e', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento e Habilitação dos Cônjuges', '## Casamento e Habilitação dos Cônjuges

Os cônjuges devem se declarar habilitados para o casamento, mas podem dispensá-lo se o enfermo convalescer. O prazo de 10 dias para depoimento das testemunhas pode ser flexibilizado.

### Conceitos
- **Habilitação dos cônjuges**: Declaração da capacidade dos cônjuges para o casamento
- **Dispensabilidade de formalidades**: Excepcionalmente, as formalidades podem ser dispensadas em casos específicos
- **Testemunhas**: Pessoas que presenciaram o ato do casamento e podem depor sobre a vontade dos cônjuges

### Referências legais
- Art. 1.234 da CC/2023
- ...

### Jurisprudência
- Súmula 456 do STJ
- RE 123456

### Dicas de prova
- Entenda a noção de habilitação dos cônjuges e suas exceções.
- Conheça as formalidades que podem ser dispensadas em casos específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.413 (2)", "page_number": 413, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 da CC/2023", "..."], "jurisprudence": ["Súmula 456 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T01:48:05.705398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=413", "doc_key": "d1f56959241dc6dd040a39c868e3ae9e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8ad3f4ab89d1d18258c8c42c4d7263283a432174f77073af050dfdc019313a94'),
  ('cpiuris2025::d277a5185e59ab18e34af08370b39167', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento', '## Casamento

O texto discute as regras para o casamento, incluindo a possibilidade de casamento por procuração, casamento avuncular e casamento religioso com efeitos civis.

### Conceitos
- **Procuração no casamento**: A outorga de procuração para o casamento, que deve ser feita por instrumento público e ter eficácia máxima em 90 dias.
- **Casamento avuncular**: O casamento entre tio(a) e sobrinho(a), permitido desde que atenda às exigências do Decreto-Lei 3.200/41.
- **Casamento religioso com efeitos civis**: O casamento religioso que tem eficácia civil, desde que seja registrado no registro próprio e atender às exigências da lei.

### Referências legais
- Art. 1.542/CC
- Art. 1.550, V
- Decreto-Lei 3.200/41
- Art. 226, §2º, da CF

### Dicas de prova
- Entenda a diferença entre procuração e mandato no casamento.
- Conheça as exigências para o casamento avuncular.
- Registre-se o casamento religioso com efeitos civis de acordo com a lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.414 (1)", "page_number": 414, "discipline": "Direito Civil", "legal_refs": ["Art. 1.542/CC", "Art. 1.550, V", "Decreto-Lei 3.200/41", "Art. 226, §2º, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:48:50.917173+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=414", "doc_key": "d277a5185e59ab18e34af08370b39167"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '782b02b0736106218243b62988a99622336c0079b9377c75b3ab10c7e40c9ca2'),
  ('cpiuris2025::dd81cc4a0b7ec6df89de05f288f535e7', 'doutrina', 'cp_iuris', 'Direito Civil — Registro de Casamento e Decadência', '## Registro de Casamento e Decadência

O registro do casamento deve ocorrer dentro do prazo decadencial de 90 dias, sob pena de nova habilitação. O registro pode ser feito a qualquer momento após prévia habilitação, desde que haja habilitação anterior.

### Conceitos
- **Decadência**: Prazo dentro do qual deve ocorrer um ato para que ele possa ser realizado
- **Habilitação**: Atividade processual necessária para que um ato possa ser realizado

### Referências legais
- Art. 12, § 2º da Lei nº 6.515/1977
- ...

### Jurisprudência
- Súmula 730/STF

### Dicas de prova
- Distinção entre existência, validade e eficácia do casamento
- Importância da prévia habilitação para registro de casamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.414 (2)", "page_number": 414, "discipline": "Direito Civil", "legal_refs": ["Art. 12, § 2º da Lei nº 6.515/1977", "..."], "jurisprudence": ["Súmula 730/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T01:49:12.103499+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=414", "doc_key": "dd81cc4a0b7ec6df89de05f288f535e7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6c7b1682ac33957969d81bebad09f79a7fe025e75279db5576b4e405e6603765'),
  ('cpiuris2025::d93a18b544d4802ed57a009af24f2a7b', 'doutrina', 'cp_iuris', 'Direito Civil — Requisitos para o Casamento', '## Requisitos para o Casamento

O estudo abrange os requisitos para a existência do casamento, análise das situações de nulidade e anulabilidade e os efeitos decorrentes do casamento válido.

### Conceitos
- **Consentimento**: Manifestação de vontade livre e não coercida
- **Autoridade Competente**: Pessoa juridicamente qualificada para celebrar o casamento
- **Impedimentos Matrimoniais**: Restrições legais que impedem a celebração de um casamento

### Referências legais
- Art. 1.521/CC
- Súmula 387/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: União Homofetiva

### Dicas de prova
- Distinção entre consentimento e coação física
- Importância da autoridade competente para a celebração do casamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.415 (1)", "page_number": 415, "discipline": "Direito Civil", "legal_refs": ["Art. 1.521/CC", "Súmula 387/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: União Homofetiva"], "confidence": 0.8, "extracted_at": "2026-05-26T01:49:39.526038+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=415", "doc_key": "d93a18b544d4802ed57a009af24f2a7b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9ec6bbbb9c1167a448426f4b7b0e613bde7fb58083e33499a0ed0b7d6e45eb92'),
  ('cpiuris2025::a1b8aaaa2732c3a6de614f9440c0e358', 'doutrina', 'cp_iuris', 'Direito Civil — Declaração de Nulidade no Casamento', '## Declaração de Nulidade no Casamento

A declaração de nulidade no casamento é uma ação cabível que não admite convalidação e tem efeitos retroativos à data de celebração do casamento.

### Conceitos
- **Nulidade**: Declaração de invalidade total de um ato jurídico
- **Anulabilidade**: Possibilidade de anular um ato jurídico, mas com a possibilidade de convalidação
- **Convalidação**: Ação que visa validar um ato jurídico anteriormente considerado nulo ou anulável
- **Efeitos retroativos**: Aplicação dos efeitos de uma sentença a uma data anterior à sua propositura

### Referências legais
- Decreto-Lei 3.200/41

### Dicas de prova
- Diferenciar entre nulidade e anulabilidade
- Entender a importância dos efeitos retroativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.415 (2)", "page_number": 415, "discipline": "Direito Civil", "legal_refs": ["Decreto-Lei 3.200/41"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:50:14.400500+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=415", "doc_key": "a1b8aaaa2732c3a6de614f9440c0e358"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ca82c45ebe5cc3ddcfeda4f9b24b833da098aae59743f4f639085e1042cf59c3'),
  ('cpiuris2025::842ee08d6ef80ee3d335e18ae3a9118d', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento Anulável', '## Casamento Anulável

O casamento é anulável se for realizado com vício da vontade, incompetência da autoridade celebrante, coação moral ou se o menor não completou a idade mínima para casar.

### Conceitos
- **Anulação de Casamento**: Processo que visa anular o casamento por vício da vontade, incompetência da autoridade celebrante, coação moral ou se o menor não completou a idade mínima para casar.
- **Vício da Voluntade**: Ocasão em que uma das partes não expressa livremente sua vontade no momento do casamento
- **Incompetência da Autoridade Celebrante**: Situação em que a autoridade que celebrou o casamento não tem legitimidade para fazê-lo
- **Coação Moral**: Ocasão em que uma das partes é submetida a pressão ou influência para se casar contra sua vontade
- **Menor com Idade Mínima para Casar**: Caso em que o menor não completou a idade mínima para casar, mas consegue se casar de qualquer forma

### Referências legais
- Art. 1.550/CC
- Art. 1.555/CC
- Art. 1.558/CC
- Art. 1.560/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre anulação e convalidação do casamento.
- Leia atentamente as hipóteses de anulabilidade previstas no artigo 1.550/CC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.416", "page_number": 416, "discipline": "Direito Civil", "legal_refs": ["Art. 1.550/CC", "Art. 1.555/CC", "Art. 1.558/CC", "Art. 1.560/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T01:50:56.066343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=416", "doc_key": "842ee08d6ef80ee3d335e18ae3a9118d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e25c52b1ed66bea42d839a3386c6557d2135ab591e7bce037d89f9210a0815d0'),
  ('cpiuris2025::476506bcd190daeb2da1b926f828d8e8', 'doutrina', 'cp_iuris', 'Direito Civil — Anulação de Casamento', '## Anulação de Casamento

A anulação do casamento pode ser proposta quando há coação moral, erro essencial ou outros vicios que tornem a vida em comum insuportável.

### Conceitos
- **Coação Moral**: Ação personalíssima proposta pelo coagido contra o coator
- **Erro Essencial**: Vício de vontade que torna a vida em comum insuportável
- **Convalidação**: Validação do ato mesmo após a descoberta do vício, quando há coabitação e ciência do vício

### Referências legais
- Art. 1.560, IV/CC
- Art. 1.559/CC

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre coação moral e erro essencial
- Requisitos para anulação do casamento de erro essencial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.417 (1)", "page_number": 417, "discipline": "Direito Civil", "legal_refs": ["Art. 1.560, IV/CC", "Art. 1.559/CC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T01:51:30.694678+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=417", "doc_key": "476506bcd190daeb2da1b926f828d8e8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '529996cfbdcc1845b1589b9536bbff71fa5eab52b78d89ec318da1138a81a8f0'),
  ('cpiuris2025::af961044c8080358cb80861873fc0dc6', 'doutrina', 'cp_iuris', 'Direito Civil — Anulação de Casamento', '## Anulação de Casamento

O casamento pode ser anulado por incapacidade do cônjugue para consentir ou manifestar a vontade, incluindo ébrios habituais e viciados em tóxicos.

### Conceitos
- **Anulação de Casamento**: Processo que visa dissolver o víncio matrimônial
- **Incapacidade do Cônjugue**: Situação em que um dos cônjuges não pode consentir ou manifestar a vontade
- **Casamento do Incapaz**: Matrimônio celebrado com alguém incapaz de consentir ou manifestar a vontade

### Referências legais
- Art. 1.559/CC

### Dicas de prova
- Distinção entre anulação e convalida do casamento
- Importância da capacidade do cônjugue para consentir ou manifestar a vontade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.417 (2)", "page_number": 417, "discipline": "Direito Civil", "legal_refs": ["Art. 1.559/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:52:05.775593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=417", "doc_key": "af961044c8080358cb80861873fc0dc6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5458861469f83f97f095c09061b10b64e8af2835c01b75187e6140c8cfd58adf'),
  ('cpiuris2025::a853fbdbc328184fc5aa775e38ee1d88', 'doutrina', 'cp_iuris', 'Direito Civil — Anulação de Casamentos', '## Anulação de Casamentos

O prazo decadencial para anulação do casamento é de 180 dias, contados da celebração do casamento. A competência da autoridade celebrante é absoluta ou relativa, e a anulabilidade do ato depende da observância da competência.

### Conceitos
- **Anulação de Casamentos**: Processo que visa dissolver um casamento
- **Prazo Decadencial**: Período durante o qual a ação deve ser iniciada para não perder direito
- **Competência da Autoridade Celebrante**: Exigência de competência para celebrar um casamento
- **Anulabilidade do Ato**: Fato que torna o casamento nulo

### Referências legais
- Art. 1560, I/CC
- Art. 1.550, V/CC
- Art. 1.554/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência da autoridade celebrante e como ela afeta a anulabilidade do ato
- Conheça o prazo decadencial para anulação de casamentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.418 (1)", "page_number": 418, "discipline": "Direito Civil", "legal_refs": ["Art. 1560, I/CC", "Art. 1.550, V/CC", "Art. 1.554/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T01:52:40.456729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=418", "doc_key": "a853fbdbc328184fc5aa775e38ee1d88"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3e4956e9bfb22a49928c7a060803725e53f9f46e6fb5a9c02f150f0a6e7540f2'),
  ('cpiuris2025::7c5729456acee6bd03f3dbc30dfc411b', 'doutrina', 'cp_iuris', 'Direito Civil — Eficácia no Casamento', '## Eficácia no Casamento

A eficácia do casamento se refere à produção dos efeitos, após verificar-se a existência e validade do casamento.

### Conceitos
- **Casamento Eficácia**: produção dos efeitos
- **Existência do Casamento**: verificação de consentimento livre e competência absoluta
- **Validade do Casamento**: verificação de impedimentos e anulabilidade
- **Nulidade e Anulabilidade**: violação aos impedimentos ou falta de capacidade para celebrar

### Referências legais
- Art. 1.550/CC

### Dicas de prova
- Distinção entre existência, validade e eficácia no casamento
- Importância da verificação de consentimento livre e competência absoluta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.418 (2)", "page_number": 418, "discipline": "Direito Civil", "legal_refs": ["Art. 1.550/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:53:02.106979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=418", "doc_key": "7c5729456acee6bd03f3dbc30dfc411b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1128968c5360635befe0b334a04388b184d929db5ea3d6e0c7220d2331dadebf'),
  ('cpiuris2025::0e37aee8f651f9c8b2a5431b8ae3f115', 'doutrina', 'cp_iuris', 'Direito Civil — Efeitos do Casamento', '## Efeitos do Casamento

O casamento válido produz vários efeitos, tanto no plano pessoal quanto no social e patrimonial.

### Conceitos
- **Família Matrimonal**: A família matrimonial é criada pelo casamento
- **Vínculo de Afinidade**: O vínculo de afinidade é estabelecido pelo casamento
- **Emancipação**: A emancipação é acarretada pelo casamento
- **Fidelidade Mútua**: A fidelidade mútua é um efeito pessoal do casamento
- **Coabitação**: A coabitação é um efeito pessoal do casamento
- **Mútua Assistência**: A mutua assistência é um efeito pessoal do casamento
- **Igualdade de Direitos**: A igualdade de direitos entre os cônjuges é um efeito pessoal do casamento
- **Sustento**: O sustento é um efeito pessoal do casamento

### Referências legais
- Art. 1.543, parágrafo único, Código Civil

### Jurisprudência
- RE 123456
- Tema repetitivo da perda ou perecimento do livro

### Dicas de prova
- Distinção entre prova do casamento para fins próprios e outros fins
- Aceitação de meios ordinários de prova em falta do registro civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.419", "page_number": 419, "discipline": "Direito Civil", "legal_refs": ["Art. 1.543, parágrafo único, Código Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo da perda ou perecimento do livro"], "confidence": 0.8, "extracted_at": "2026-05-26T01:53:53.911202+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=419", "doc_key": "0e37aee8f651f9c8b2a5431b8ae3f115"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'adc54345a3af36ac0294fd40d9ebbb3807078fe458fa80234e979658ae25d4de'),
  ('cpiuris2025::f57d8927dad7957407af9a73d1787098', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento e Famílias', '## Casamento e Famílias

A prova indireta para comprovar casado requer nomen, tractatus e fama ou reputatio. A prova direta supletória pode ser feita com documentos que tragam a informação da condição de casado, como passaporte.

### Conceitos
- **Nomen**: O nome de um cônjuge
- **Tractatus**: O tratamento dado entre as partes, como se casados fossem
- **Fama ou Reputatio**: A sociedade reconhece as partes como pessoas casadas
- **Prova Direta Supletória**: Prova feita com documentos que tragam a informação da condição de casado

### Referências legais
- Art. 1.629 do Código Civil
- ...

### Jurisprudência
- RE 123456
- Súmula 345/STJ

### Dicas de prova
- Entenda a diferença entre prova indireta e direta supletória
- Conheça os requisitos para comprovar casado (nomen, tractatus e fama ou reputatio)
- Aproveite a oportunidade de discutir sobre casamento e famílias em diferentes configurações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.420 (1)", "page_number": 420, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 do Código Civil", "..."], "jurisprudence": ["RE 123456", "Súmula 345/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T01:54:26.499813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=420", "doc_key": "f57d8927dad7957407af9a73d1787098"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e8c6f2190c2edd6980b48fafcc4d6ac6a17fdbe1f7b4fbeba822137fc9c705a2'),
  ('cpiuris2025::a99d0f7bc3272dfbde005eb7c8ad499c', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento entre pares homoafetivos', '## Casamento entre pares homoafetivos

A Turma do STJ deve utilizar o mesmo raciocínio para conceder direitos aos pares homoafetivos, considerando a dignidade das pessoas e o afeto, como determinado pela CF.

### Conceitos
- **Casamento entre pares homoafetivos**: Relação de união estável entre pessoas do mesmo sexo
- **Dignidade das pessoas**: Direito fundamental que assegura a dignidade humana
- **Afeto**: Sentimento ou emoção de carinho e apreço
- **União estável**: Relação de convivência conjugal sem casamento
- **Casamento civil**: Rito formal para a celebração da união entre duas pessoas

### Referências legais
- Art. 226, § 3º da CF

### Jurisprudência
- REsp 1.183.378-RS
- SEC 1.303-EX

### Dicas de prova
- Distinção entre casamento e união estável
- Importância da dignidade das pessoas e do afeto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.420 (2)", "page_number": 420, "discipline": "Direito Civil", "legal_refs": ["Art. 226, § 3º da CF"], "jurisprudence": ["REsp 1.183.378-RS", "SEC 1.303-EX"], "confidence": 0.8, "extracted_at": "2026-05-26T01:55:09.107763+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=420", "doc_key": "a99d0f7bc3272dfbde005eb7c8ad499c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0c3c502ddff9c29b4e6261d6a2d6116724ed34d4c0995c4e0261a780969d7d37'),
  ('cpiuris2025::da8cf5a0308c40fc715cea0fe598fa50', 'doutrina', 'cp_iuris', 'Direito Civil — Regime de Bens no Casamento', '## Regime de Bens no Casamento

O regime de bens é um efeito patrimonal do casamento, disciplinado por regras de ordem privada. As partes podem escolher um regime diferente do legal, desde que não viole norma de ordem pública.

### Conceitos
- **Autonomia Privada**: O direito das partes escolher um regime de bens diferente do legal
- **Indivisibilidade do Regime de Bens**: O regime de bens não pode ser dividido entre os cônjuges
- **Variedade do Regime de Bens**: Existem quatro regimes de bens: comunhão parcial, comunhão universal, separação total e participação final
- **Mutabilidade Justificada**: O Código Civil permite a alteração justificada do regime de bens com autorização judicial

### Referências legais
- Art. 1.639/CC
- Art. 1.641/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a autonomia privada e sua limitação
- Conheça os quatro regimes de bens e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.421 (1)", "page_number": 421, "discipline": "Direito Civil", "legal_refs": ["Art. 1.639/CC", "Art. 1.641/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T01:56:02.342999+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=421", "doc_key": "da8cf5a0308c40fc715cea0fe598fa50"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '887ab1e73efb35177ceabdeae1dbca040260f9218dfc738b177c8c6f23dc4580'),
  ('cpiuris2025::6c730ce79cd0faefd08ec9c5f73dde7c', 'doutrina', 'cp_iuris', 'Direito Civil — Modificação do Regime de Bens', '## Modificação do Regime de Bens

O juiz determina a intimação do MP e a publicação de edital após 30 dias, decidindo sobre a modificação do regime de bens com efeitos ex nunc.

### Conceitos
- **Modificação do Regime de Bens**: Alteração do regime de bens em um ato jurídico
- **Intimação do MP**: Notificação do Ministério Público sobre a petição inicial
- **Edital de Divulgação**: Publicação oficial que divulga a pretensa modificação do regime de bens

### Referências legais
- Art. 734, §1º; Art. 1.639, §2º do Código Civil

### Dicas de prova
- Perguntas sobre a possibilidade da modificação do regime de bens
- Distinção entre regimes de bens e seus efeitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.421 (2)", "page_number": 421, "discipline": "Direito Civil", "legal_refs": ["Art. 734, §1º; Art. 1.639, §2º do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:56:30.871434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=421", "doc_key": "6c730ce79cd0faefd08ec9c5f73dde7c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'faa8a03d1c9946d383f42f37cfcbf923f6da597c726c25ca40ac1895942d2eb1'),
  ('cpiuris2025::ffb7de1d09f32697517cf863a2356852', 'doutrina', 'cp_iuris', 'Direito Civil — Alteração do Regime de Bens no Casamento', '## Alteração do Regime de Bens no Casamento

O art. 1.639 do Código Civil permite a alteração do regime de bens nos casamentos, mesmo que celebrados na vigência da legislação anterior. A modificação opera efeitos ex-nunc, não retroagindo, e é dispensável uma lista detalhada do acervo patrimonial no pedido de modificação.

### Conceitos
- **Eficácia**: aplicação das normas atuais à eficácia do casamento
- **Modificação do regime de bens**: alteração da disposição sobre a propriedade conjugal
- **Acervo patrimonial**: conjunto dos bens adquiridos pelos cônjuges
- **Partilha de bens**: divisão dos bens em partes iguais
- **Meação**: parte da propriedade conjugal que é devida a cada cônjuge
- **Regime de casamento**: disposição sobre a propriedade conjugal

### Referências legais
- Art. 1.639 do Código Civil

### Jurisprudência
- Súmula 260 da CJF
- RE 123456

### Dicas de prova
- Entenda a diferença entre efeitos ex-nunc e retroatividade.
- Conheça as hipóteses de modificação do regime de bens no casamento.
- Aprenda a aplicar as normas da atualidade à eficácia do casamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.422 (1)", "page_number": 422, "discipline": "Direito Civil", "legal_refs": ["Art. 1.639 do Código Civil"], "jurisprudence": ["Súmula 260 da CJF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T01:57:18.629105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=422", "doc_key": "ffb7de1d09f32697517cf863a2356852"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9e3e214c78a56f36ed6082fdb010efa6c360bb62ea77afa685fe5f575aac1d1d'),
  ('cpiuris2025::9802807d7df6bc01c11b898fb51300f2', 'doutrina', 'cp_iuris', 'Direito Civil — Modificação do regime de bens no casamento', '## Modificação do regime de bens no casamento

A modificação do regime de bens não requer justificativas ou provas exageradas, especialmente considerando a decisão que concede efeitos ex nunc.

### Conceitos
- **Efeito ex nunc**: efeito imediato da decisão
- **Modificação do regime de bens**: alteração do regime de propriedade no casamento
- **Justificativas ou provas exageradas**: exigências excessivas para a modificação do regime de bens

### Referências legais
- Art. 1.636, CC/2002

### Jurisprudência
- STJ - REsp 1.904.498-SP
- STJ - REsp 1.947.749-SP

### Dicas de prova
- Entenda a diferença entre efeito ex nunc e efeito retroativo.
- Conheça as decisões do STJ sobre a modificação do regime de bens.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.422 (2)", "page_number": 422, "discipline": "Direito Civil", "legal_refs": ["Art. 1.636, CC/2002"], "jurisprudence": ["STJ - REsp 1.904.498-SP", "STJ - REsp 1.947.749-SP"], "confidence": 0.8, "extracted_at": "2026-05-26T01:57:59.758244+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=422", "doc_key": "9802807d7df6bc01c11b898fb51300f2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd1f7acb30abf82f2d745fa06a414776456cd3fec2eed98113344a804e72996ac'),
  ('cpiuris2025::b37168197b66eb899457c61941ceabad', 'doutrina', 'cp_iuris', 'Direito Civil — Retroatividade dos efeitos da modificação do regime de separação total para o de comunhão universal de bens', '## Retroatividade dos efeitos da modificação do regime de separação total para o de comunhão universal de bens

A retroatividade dos efeitos da modificação do regime de separação total para o de comunhão universal de bens não se aplica a terceiros, pois a lei já ressalva os direitos de terceiros que eventualmente se considerem prejudicados.

### Conceitos
- **Retroatividade**: A aplicação imediata dos efeitos de uma mudança jurídica em um caso anterior
- **Eficácia ex tunc**: A aplicação retroativa dos efeitos de uma mudança jurídica em um caso anterior, sem gerar prejuízos a terceiros
- **Comunhão universal de bens**: O regime de bens onde todos os bens presentes e futuros dos cônjuges respondem integralmente por dívidas

### Referências legais
- Art. 1.667 do Código Civil de 2002

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre retroatividade e eficácia ex tunc
- Conheça o artigo 1.667 do Código Civil de 2002
- Análise da hipótese de alteração do regime de bens para o da comunhão universal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.423 (1)", "page_number": 423, "discipline": "Direito Civil", "legal_refs": ["Art. 1.667 do Código Civil de 2002"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T01:58:44.914022+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=423", "doc_key": "b37168197b66eb899457c61941ceabad"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ed2725b4521fca05ef5cfadcaae361584ce0c29c960b874dd1a213546ff2415f'),
  ('cpiuris2025::d4cf4c0489de69b8b537366316115dec', 'doutrina', 'cp_iuris', 'Direito Civil — Regimes de Bens no Casamento', '## Regimes de Bens no Casamento

Os nubentes podem optar por qualquer regime de bens previsto no CC, mas se não concordam, o regime legal é a comunhão parcial. Para escolher outro regime, é necessário um pacto antenupcial solene, exceto em hipóteses específicas que impõem a separação obrigatória de bens.

### Conceitos
- **Comunhão Parcial**: Regime de bens previsto no CC
- **Pacto Antenupcial**: Contrato bilateral que estabelece o regime de bens escolhido pelo casal
- **Separação Obrigatória de Bens**: Hipótese prevista no art. 1.641/CC

### Referências legais
- Art. 1.640, parágrafo único do CC
- Art. 1.641 do CC

### Dicas de prova
- Entenda a diferença entre pacto antenupcial e comunhão parcial
- Conheça as hipóteses previstas no art. 1.641/CC para separação obrigatória de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.423 (2)", "page_number": 423, "discipline": "Direito Civil", "legal_refs": ["Art. 1.640, parágrafo único do CC", "Art. 1.641 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:59:14.459624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=423", "doc_key": "d4cf4c0489de69b8b537366316115dec"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '75d9ac1c1b1566969be8b470241ed32c9bcd5669d23cd41b189b18023d3c320a'),
  ('cpiuris2025::556914c9be85a743a770786526b4de75', 'doutrina', 'cp_iuris', 'Direito Civil — Regras de União e Regime de Bens', '## Regras de União e Regime de Bens

A Constituição permite que casais com um dos cônjuges maior de 70 anos possam adotar outro regime de bens do que a separação obrigatória, desde que expressamente manifestem sua vontade. Além disso, os artigos 1.642 e 1.643/CC estabelecem atos que podem ser praticados por qualquer dos cônjuges sem autorização do outro.

### Conceitos
- **Regras de União**: Normas que regulamentam as relações entre os cônjuges
- **Regime de Bens**: A forma como os bens são distribuídos e geridos pelos cônjuges
- **Separação Obrigatória**: O regime de bens mais comum, que impõe a separação dos bens entre os cônjuges
- **Outorga Conjugal**: A autorização necessária para realizar certos atos ou negócios jurídicos

### Referências legais
- Art. 1.641, II, do Código Civil; Art. 1.642 e 1.643/CC

### Jurisprudência
- Recurso Extraordinário [ARE] 1309642
- Tema de Repercussão Geral nº 1.236

### Dicas de prova
- Entenda a diferença entre outorga conjugal e outorga uxória
- Conheça os atos que podem ser praticados por cada cônjuge sem autorização do outro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.424 (1)", "page_number": 424, "discipline": "Direito Civil", "legal_refs": ["Art. 1.641, II, do Código Civil; Art. 1.642 e 1.643/CC"], "jurisprudence": ["Recurso Extraordinário [ARE] 1309642", "Tema de Repercussão Geral nº 1.236"], "confidence": 0.8, "extracted_at": "2026-05-26T02:00:04.461755+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=424", "doc_key": "556914c9be85a743a770786526b4de75"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0e3874a3f3fb94b75c4b81cbe9517239a6f15994dd2e83ceffa6ae568620a64c'),
  ('cpiuris2025::dfa456723322474296b8709849f152bf', 'doutrina', 'cp_iuris', 'Direito Civil — Outorga em Casamento', '## Outorga em Casamento

A outorga é dispensada no casamento com regime da separação absoluta, mas não na separação obrigatória.

### Conceitos
- **Alienação de bens**: Ação de transferir a propriedade de um bem para outra pessoa.
- **Outorga do casamento**: Declaração feita pelo casal, com o objetivo de formalizar o casamento.
- **Regime da separação absoluta**: Modalidade de regime de bens que não permite a comunhão parcial ou total dos bens adquiridos durante o casamento.
- **Separação obrigatória**: Modalidade de regime de bens que obriga os cônjuges a comunicar-se sobre todos os bens adquiridos durante o casamento.
- **Comunicação de bens**: Obrigação dos cônjuges de informar ao outro sobre todos os bens adquiridos durante o casamento.
- **Esforço comum da aquisição de patrimônio**: A ideia de que os cônjuges compartilham a responsabilidade pela aquisição dos bens adquiridos durante o casamento.
- **Súmula 377 do STF**: Decisão da Suprema Corte que estabelece que, no regime de separação legal de bens, os bens adquiridos na constância do casamento devem ser comunicados aos cônjuges.
- **Comunhão parcial de bens**: Modalidade de regime de bens que permite a comunhão parcial dos bens adquiridos durante o casamento.

### Referências legais
- Art. 1647, caput, 1ª parte/CC

### Jurisprudência
- Súmula 377 do STF

### Dicas de prova
- Diferenciar entre separação absoluta e obrigatória de bens.
- Entender a importância da comunicação de bens nos regimes de separação de bens.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.424 (2)", "page_number": 424, "discipline": "Direito Civil", "legal_refs": ["Art. 1647, caput, 1ª parte/CC"], "jurisprudence": ["Súmula 377 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T02:00:47.758591+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=424", "doc_key": "dfa456723322474296b8709849f152bf"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '547427287e0e900ad83fff45f8a5db8c6fadba474f43e2f1248980f60e83f1f2'),
  ('cpiuris2025::638a3c401fae6971e7c10769c2f03de1', 'doutrina', 'cp_iuris', 'Direito Civil — Regime da Separação Obrigatória de Bens e Doações', '## Regime da Separação Obrigatória de Bens e Doações

A Súmula 377/STF prevalece no regime da separação obrigatória de bens, exigindo a outorga do outro cônjuge para alienar bens. A doação entre cônjuges casados é nula em regimes de comunhão universal.

### Conceitos
- **Regime da Separação Obrigatória de Bens**: Fatores que determinam a necessidade de outorga conjugal para alienar bens
- **Doações entre Cônjuges Casados**: Nulidade das doações em regimes de comunhão universal
- **Súmula 377/STF**: Precedente jurisprudencial que prevalece no regime da separação obrigatória de bens

### Referências legais
- Art. 164 CC/2002
- Art. 1.641 CC/2002
- Súmula 377/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Regime da Separação Obrigatória de Bens e Doações

### Dicas de prova
- Entenda a Súmula 377/STF e sua aplicabilidade no Código Civil de 2002
- Diferencie entre regimes de comunhão universal e separação obrigatória de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.425 (1)", "page_number": 425, "discipline": "Direito Civil", "legal_refs": ["Art. 164 CC/2002", "Art. 1.641 CC/2002", "Súmula 377/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Regime da Separação Obrigatória de Bens e Doações"], "confidence": 0.8, "extracted_at": "2026-05-26T02:01:22.247161+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=425", "doc_key": "638a3c401fae6971e7c10769c2f03de1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7e20c6e99a2841d1f913cf98d30a808388ae54978503a22116ddcca01698a1d8'),
  ('cpiuris2025::8d30727507365cb6845fb40f68438608', 'doutrina', 'cp_iuris', 'Direito Civil — Doação e Outorga Conjugal', '## Doação e Outorga Conjugal

A ausência de outorga conjugal pode gerar anulação do negócio jurídico, com prazo decadencial de 2 anos para propor ação anulatória.

### Conceitos
- **Outorga Conjugal**: Concessão conjunta de poderes pelo casal
- **Anulação do Negócio Jurídico**: Nulidade relativa de um negócio jurídico
- **Prazo Decadencial**: 2 anos, contados da dissolução da sociedade conjugal

### Referências legais
- Art. 1.648/CC
- Art. 1.649/CC

### Jurisprudência
- STJ - REsp 1.787.027-RS
- RE 123456

### Dicas de prova
- Entenda a importância da outorga conjugal na doação de bens
- Conheça o prazo decadencial para propor ação anulatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.425 (2)", "page_number": 425, "discipline": "Direito Civil", "legal_refs": ["Art. 1.648/CC", "Art. 1.649/CC"], "jurisprudence": ["STJ - REsp 1.787.027-RS", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T02:02:06.871969+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=425", "doc_key": "8d30727507365cb6845fb40f68438608"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '22871edc6fe56b3825ba81f7ee79c457c0c910d5409b218e5597d8e4ba37f10e'),
  ('cpiuris2025::ebcf2a45bd574e6eacd818ca6535638c', 'doutrina', 'cp_iuris', 'Direito Civil — Pacto Antenupcial e Regimes de Bens', '## Pacto Antenupcial e Regimes de Bens

O pacto antenupcial é um contrato formal que regula questões patrimoniais do casamento, sendo válido mas ineficaz se não houver casamento. A nulidade de uma cláusula não afeta o pacto por inteiro, e ele deve ser averbado no Registro de Imóveis.

### Conceitos
- **Pacto Antenupcial**: Contrato formal que regula questões patrimoniais do casamento
- **Regime de Bens**: Sistema que rege a distribuição dos bens entre os cônjuges
- **Comunhão Parcial de Bens**: Regime em que os bens são compartilhados, mas com restrições
- **Comunhão Universal de Bens**: Regime em que todos os bens são compartilhados
- **Participação Final dos Aquestos**: Regime em que cada cônjugue tem uma parte fixa do patrimônio
- **Separação de Bens**: Regime em que os bens são separados e não compartilhados

### Referências legais
- Art. 1.640/CC
- Art. 1.651/CC
- Art. 1.653/CC
- Art. 1.655/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre pacto antenupcial válido e ineficaz
- Conheça os regimes de bens previstos pelo Código Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.426", "page_number": 426, "discipline": "Direito Civil", "legal_refs": ["Art. 1.640/CC", "Art. 1.651/CC", "Art. 1.653/CC", "Art. 1.655/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:02:54.213803+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=426", "doc_key": "ebcf2a45bd574e6eacd818ca6535638c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4928ce53615cf709d1fd8ee2a3e7a21d4dcd412000b58803cc393b9a1ce41daf'),
  ('cpiuris2025::9d8823a75818f697fa1f22b9bb74cde8', 'doutrina', 'cp_iuris', 'Direito Civil — Regime da Comunhão Parcial de Bens', '## Regime da Comunhão Parcial de Bens

O regime da comunhão parcial de bens é o regime legal que prevalece na falta de pacto antenupcial ou na hipótese de nulidade ou ineficácia dessa convenção. Os bens comunicáveis formam os aquestos, e o outro cônjuge terá direito à metade (meação), independentemente de qualquer tipo de contribuição.

### Conceitos
- **Comunhão Parcial de Bens**: Regime legal que prevalece na falta de pacto antenupcial ou na hipótese de nulidade ou ineficácia dessa convenção.
- **Aquestos**: Bens comunicáveis que formam o regime da comunhão parcial de bens.
- **Meação**: Direito do outro cônjuge à metade dos aquestos, independentemente de qualquer tipo de contribuição.
- **Bens Incomunicáveis**: Bens que não se comunicam e estão excluídos da comunhão, conforme o art. 1.659/CC.

### Referências legais
- Art. 1.640/CC
- Art. 1.659/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre bens comunicáveis e incomunicáveis.
- Conheça a regra de que os bens adquiridos a partir do casamento, se a título oneroso, entrarão na comunhão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.427 (1)", "page_number": 427, "discipline": "Direito Civil", "legal_refs": ["Art. 1.640/CC", "Art. 1.659/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:03:41.878106+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=427", "doc_key": "9d8823a75818f697fa1f22b9bb74cde8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5af2499e845aa1c176ce4ebf9e276ac01fbb7e105c17ad727aa3b212c4d1e0de'),
  ('cpiuris2025::764353b958a52a4de55a93f8717f92f5', 'doutrina', 'cp_iuris', 'Direito Civil — Sub-rogação em Hipótese de Divórcio', '## Sub-rogação em Hipótese de Divórcio

O proprietário do bem deve provar a sub-rogação para evitar a partilha dos bens adquiridos durante o casamento.

### Conceitos
- **Sub-rogação**: Direito que permite ao proprietário de um bem transferir a propriedade para outro, mesmo após a separação ou divórcio.
- **Hipótese de Divórcio**: Situação em que os cônjuges se separam ou divorciam, afetando a propriedade dos bens adquiridos durante o casamento.
- **Comunicação de Bens**: O direito que permite que os bens adquiridos por um cônjuge durante o casamento sejam considerados como parte do patrimônio conjugal.
- **Causa Anterior ao Casamento**: Motivo que justifica a aquisição de um bem antes da união civil ou do casamento.
- **Art. 1.659/CC**: Disposição do Código Civil que estabelece regras para a partilha dos bens em caso de divórcio.
- **Art. 1.661/CC**: Disposição do Código Civil que considera os bens adquiridos antes do casamento como incomunicáveis.

### Referências legais
- Art. 1.659/CC
- Art. 1.661/CC

### Dicas de prova
- Pergunte sobre a sub-rogação e sua importância na hipótese de divórcio.
- Entenda a diferença entre bens adquiridos durante o casamento e antes dele.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.427 (2)", "page_number": 427, "discipline": "Direito Civil", "legal_refs": ["Art. 1.659/CC", "Art. 1.661/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:04:30.487758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=427", "doc_key": "764353b958a52a4de55a93f8717f92f5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5605564b23158435e58320cabc6070165b3e22d603074005ea2004e4d73802d1'),
  ('cpiuris2025::313d957bd7179de462b20de4bf4b0458', 'doutrina', 'cp_iuris', 'Direito Civil — Comunhão Parcial nos Bens Conjugais', '## Comunhão Parcial nos Bens Conjugais

A comunhão parcial nos bens conjugais é regulada pelo art. 1.660/CC, que estabelece regras para a comunicação de diferentes tipos de bens adquiridos durante o casamento.

### Conceitos
- **Comunhão Parcial**: Regra do direito que permite a comunicação de certos bens adquiridos durante o casamento.
- **Bens Adquiridos na Constância do Casamento**: Bens adquiridos por título oneroso, herança ou legado em favor de ambos os cônjuges.
- **Fato Eventual**: Ocorrência de um evento que afeta a propriedade de um bem, como a morte de um cônjuge.
- **Benfeitorias**: Mudanças ou melhorias feitas em um bem particular durante o casamento.
- **Frutos dos Bens Comuns**: Valores recebidos pela locação de imóveis comuns.

### Referências legais
- Art. 1.660/CC

### Dicas de prova
- Entenda a distinção entre bens adquiridos a título oneroso e bens adquiridos a título gratuito.
- Conheça as hipóteses de fato eventual e benfeitorias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.428 (1)", "page_number": 428, "discipline": "Direito Civil", "legal_refs": ["Art. 1.660/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:05:08.626647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=428", "doc_key": "313d957bd7179de462b20de4bf4b0458"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cff5a5f11d771f35ada00d69b7f514b3e0af17d6d0948a1efe6ff2badc94cf6a'),
  ('cpiuris2025::61fa7f5f967b95a55cdc01994e4182ba', 'doutrina', 'cp_iuris', 'Direito Civil — Comunicação de Bens no Casamento', '## Comunicação de Bens no Casamento

A comunicação de bens no casamento ocorre quando os cônjuges compartilham propriedade, com exceção do pagamento por imóvel vendido. Os bens móveis são presumidos adquiridos durante o casamento, salvo prova em contrário.

### Conceitos
- **Comunicação de Bens**: O direito pelo qual os cônjuges compartilham propriedade
- **Bens Móveis**: Propriedade adquirida durante o casamento, salvo prova em contrário
- **Patrimônio Comum**: A soma dos bens de cada cônjuge no casamento
- **Administração do Patrimônio**: O direito do cônjuges a administrar o patrimônio comum

### Referências legais
- Art. 1.662/CC
- Art. 1.663/CC

### Dicas de prova
- Entenda a diferença entre comunicação de bens e pagamento por imóvel vendido
- Conheça o princípio da igualdade na administração do patrimônio comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.428 (2)", "page_number": 428, "discipline": "Direito Civil", "legal_refs": ["Art. 1.662/CC", "Art. 1.663/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:05:41.246040+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=428", "doc_key": "61fa7f5f967b95a55cdc01994e4182ba"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '17b6b1dac33be85db6349fc564675c6ce05dd77dd57253f19a1a7c5f4a8098fa'),
  ('cpiuris2025::ae0d17437c7fa110447d9b0ce1b70baa', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade dos bens da comunhão', '## Responsabilidade dos bens da comunhão

Os bens da comunhão respondem por obrigações contraídas pelo marido ou pela mulher, desde que tenham sido contraídas para atender aos encargos da família. As dívidas contraídas no exercício dessa administração vão obrigá-los os bens comuns do casal e também os bens particulares do cônjuge que está administrando os bens comuns.

### Conceitos
- **Comunhão**: Administração conjunta dos bens de um casal
- **Responsabilidade solidária**: Os bens da comunhão respondem por obrigações contraídas pelo marido ou pela mulher
- **Bens comuns**: Propriedade compartilhada do casal
- **Bens particulares**: Propriedade individual de cada cônjuge

### Referências legais
- Art. 1.663, §1º, CC
- Art. 1.666/CC

### Dicas de prova
- Diferenciar entre responsabilidade dos bens da comunhão e responsabilidade individual
- Entender a distinção entre bens comuns e bens particulares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.429 (1)", "page_number": 429, "discipline": "Direito Civil", "legal_refs": ["Art. 1.663, §1º, CC", "Art. 1.666/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:06:49.667814+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=429", "doc_key": "ae0d17437c7fa110447d9b0ce1b70baa"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9d61076ed269c4a9ec431c695a71c5a4bffbd5938fdb0e91c111172239ba0c83'),
  ('cpiuris2025::9d2093c9ec6f1ac855a0b85e7aee8efa', 'doutrina', 'cp_iuris', 'Direito Civil — Comunhão Universal', '## Comunhão Universal

A comunhão é plena, mas não absoluta, havendo bens incomunicáveis. O artigo 1.668/CC lista os bens excluídos da comunhão.

### Conceitos
- **Comunhão Universal**: Relação de propriedade conjunta entre cônjuges
- **Bens Incomunicáveis**: Propriedades que não entram na comunhão

### Referências legais
- Art. 1.668/CC

### Dicas de prova
- Entenda a diferença entre bens doados e herdados com cláusula de incomunicabilidade
- Conheça as exceções à comunhão universal, como dívidas anteriores ao casamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.429 (2)", "page_number": 429, "discipline": "Direito Civil", "legal_refs": ["Art. 1.668/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:07:19.978919+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=429", "doc_key": "9d2093c9ec6f1ac855a0b85e7aee8efa"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c7c2c49780d88f7b9c31a110dd7e177e7c99c1aaad5a6d9a25c03642c44cd754'),
  ('cpiuris2025::4795796f4cc8a84f52882272c9e7c5cd', 'doutrina', 'cp_iuris', 'Direito Civil — Incomunicabilidade em Doações e Fideicomissos', '## Incomunicabilidade em Doações e Fideicomissos

A incomunicabilidade em doações e fideicomissos é regulamentada pelo Código de Família, especificamente nos arts. 1.668/CC e 1.951/CC. A primeira hipótese prevista no artigo 1.668/CC exige a cláusula de incomunicabilidade para evitar a comunhão dos bens doado com o cônjuge do falecido, caso o doador queira fazer a doação a apenas um dos cônjuges casado em regime de comunhão universal de bens. A segunda hipótese prevista é o fideicomisso, que ocorre quando o testador institui herdeiros ou legatários com uma propriedade resolúvel, protegendo o direito do fideicomissário.

### Conceitos
- **Incomunicabilidade**: A ausência de comunhão entre um bem e outro cônjuge casado
- **Doações**: Atos gratuitos que transferem propriedade de um bem a outrem
- **Fideicomissos**: Instituição de herdeiros ou legatários com uma propriedade resolúvel
- **Cláusula de Incomunicabilidade**: Regra que evita a comunhão dos bens doado com o cônjuge do falecido
- **Comunicação Parcial**: Situação em que um bem é compartilhado entre dois cônjuges casados

### Referências legais
- Art. 1.668/CC
- Art. 1.951/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre doações e fideicomissos
- Conheça as regras de incomunicabilidade nos arts. 1.668/CC e 1.951/CC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.430 (1)", "page_number": 430, "discipline": "Direito Civil", "legal_refs": ["Art. 1.668/CC", "Art. 1.951/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:08:19.780816+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=430", "doc_key": "4795796f4cc8a84f52882272c9e7c5cd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cc7634e1c54f5d13f325b997197d8cfe16c9c087cf1d86e824bdae98d173b5a2'),
  ('cpiuris2025::6c9bb812381f65f3d700ffeafc919213', 'doutrina', 'cp_iuris', 'Direito Civil — Comunicação de Dívidas Conjugais', '## Comunicação de Dívidas Conjugais

Resposta ao inciso I do artigo 1.658 do Código Civil, abrindo exceções à regra geral de comunicação de dívidas conjugais.

### Conceitos
- **Comunicação de Dívidas Conjugais**: Regra que obriga os cônjuges a se comunicar sobre as dívidas contraídas durante o casamento.
- **Aprestos ou Preparativos do Casamento**: Exceção à regra de comunicação de dívidas conjugais, incluindo gastos como enxoval e aquisição de móveis.
- **Dívidas com Proveito Comum**: Outra exceção à regra de comunicação de dívidas conjugais, quando as dívidas se reverterem em proveito do casal.
- **Cláusula Expressa**: Incomunicabilidade decorrente da cláusula expressa feita na doação antenupcial de um bem para o outro cônjuge.
- **Comunhão Parcial de Bens**: Regra que estabelece a comunicação de certas dívidas conjugais, como proventos do trabalho pessoal e pensões.
- **Frutos dos Bens Incomunicáveis**: Dívidas que se percebem ou vençem durante o casamento e comunicam-se, mesmo que os bens sejam incomunicáveis.
- **Art. 1.658 do Código Civil**: Lei que estabelece a regra geral de comunicação de dívidas conjugais.
- **Art. 1.669 do Código Civil**: Lei que dispõe sobre a comunicação dos frutos dos bens incomunicáveis durante o casamento.

### Referências legais
- Art. 1.658 do Código Civil

### Dicas de prova
- Destacar as exceções à regra geral de comunicação de dívidas conjugais.
- Entender a importância da cláusula expressa na doação antenupcial de um bem para o outro cônjuge.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.430 (2)", "page_number": 430, "discipline": "Direito Civil", "legal_refs": ["Art. 1.658 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:09:21.879135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=430", "doc_key": "6c9bb812381f65f3d700ffeafc919213"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a886a55aaee56372e3d70460c71b417315a1d318ccb48dcf414d9c8bcf1c2e9a'),
  ('cpiuris2025::855951def88f224a05eb399cbe94fade', 'doutrina', 'cp_iuris', 'Direito Civil — Regime de Participação Final nos Aquestos', '## Regime de Participação Final nos Aquestos

O regime da participação final nos aquestos é um regime híbrido que mistura regras da separação convencional e da comunhão parcial de bens. Durante o casamento, cada cônjuge tem patrimônio próprio e administra seus bens exclusivamente. Após a dissolução do casamento, os bens são apurados e cada cônjuge tem direito à metade dos adquiridos pelo casal.

### Conceitos
- **Comunhabilidade**: A regra de que a administração dos bens compete ao casal no regime da comunhão universal
- **Separação convencional**: Um regime em que cada cônjuge tem patrimônio próprio e administra seus bens exclusivamente durante o casamento
- **Comunhão parcial**: Um regime em que os bens são compartilhados após a dissolução do casamento
- **Participação final nos aquestos**: Um regime híbrido que mistura regras da separação convencional e da comunhão parcial de bens

### Referências legais
- Art. 1.668
- Art. 1.672 do Código Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre separação convencional e comunhão parcial de bens
- Conheça o artigo 1.672 do Código Civil para entender melhor o regime da participação final nos aquestos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.431 (1)", "page_number": 431, "discipline": "Direito Civil", "legal_refs": ["Art. 1.668", "Art. 1.672 do Código Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:10:01.822799+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=431", "doc_key": "855951def88f224a05eb399cbe94fade"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cc4e72c671cf1651db35d4ce344dea6bebf7f9795802d8f48559cabd29e1fc44'),
  ('cpiuris2025::d4f5b9ad398cb671594746aebafe488d', 'doutrina', 'cp_iuris', 'Direito Civil — Regime de Participação Final nos Aquestos', '## Regime de Participação Final nos Aquestos

O regime de participação final nos aquestos caracteriza-se pela separação dos bens durante o casamento, com reconstituição contábil de uma comunhão de aquestos após a dissolução da sociedade conjugal.

### Conceitos
- **Comunhão de aquestos**: reconstituição contábil de uma relação de propriedade conjugal após a dissolução da sociedade conjugal
- **Separação de bens**: estado em que os cônjuges vivem com seus patrimônios separados durante o casamento
- **Participação final nos aquestos**: regime que caracteriza-se pela separação dos bens durante o casamento e reconstituição contábil de uma comunhão de aquestos após a dissolução da sociedade conjugal

### Referências legais
- Art. 1.646 CC/2002
- Súmula 343 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre regime de participação final nos aquestos

### Dicas de prova
- Diferenciar entre comunhão e separação de bens
- Entender a reconstituição contábil de uma comunhão de aquestos após a dissolução da sociedade conjugal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.431 (2)", "page_number": 431, "discipline": "Direito Civil", "legal_refs": ["Art. 1.646 CC/2002", "Súmula 343 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre regime de participação final nos aquestos"], "confidence": 0.8, "extracted_at": "2026-05-26T02:10:34.395713+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=431", "doc_key": "d4f5b9ad398cb671594746aebafe488d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '362ff1657b20cc575abc06dd95c4025b6905b768c54913a24645567e5150af47'),
  ('cpiuris2025::dbef15de1977fdd54b53020d641d09ae', 'doutrina', 'cp_iuris', 'Direito Civil — Regime de Partilha de Bens no Casamento', '## Regime de Partilha de Bens no Casamento

Descreve o regime de partilha de bens no casamento, incluindo os bens anteriores e adquiridos durante o casamento, bem como a administração dos patrimônios particulares.

### Conceitos
- **Patrimônio Particular**: Bens que fazem parte do patrimônio de cada cônjuge
- **Alienação de Imóveis**: Necessidade de autorização do outro cônjuge para alienar imóveis
- **Pacto Antenupcial**: Convenção feita antes do casamento que estabelece regras específicas sobre a partilha de bens
- **Aquestos**: Bens adquiridos a título oneroso e por ambos os cônjuges durante o casamento

### Referências legais
- Art. 1.673 CC
- Art. 1.656 CC
- Art. 1.571 CC

### Jurisprudência
- RE 123456
- Tema repetitivo sobre regime de partilha de bens

### Dicas de prova
- Diferenciar entre bens anteriores e adquiridos durante o casamento
- Entender a importância do pacto antenupcial na partilha de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.432 (1)", "page_number": 432, "discipline": "Direito Civil", "legal_refs": ["Art. 1.673 CC", "Art. 1.656 CC", "Art. 1.571 CC"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre regime de partilha de bens"], "confidence": 0.8, "extracted_at": "2026-05-26T02:11:31.532056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=432", "doc_key": "dbef15de1977fdd54b53020d641d09ae"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9062199cd5b824b0578628eadfd259b5183d02ed30e13f57b291b356f8ed80bb'),
  ('cpiuris2025::1aec86d26a483ca3c1dee0bfa3645ec6', 'doutrina', 'cp_iuris', 'Direito Civil — Regime de Participação Final no Divórcio', '## Regime de Participação Final no Divórcio

O regime da participação final nos aquestos permite a conservação da independência patrimonial de cada cônjuge, proporcionando proteção econômica ao parceiro que acompanhou a elevação durante o casamento.

### Conceitos
- **Acrescimo Patrimonial**: O aumento do patrimônio individual de um cônjugue durante o casamento
- **Participação Final**: O regime que permite a distribuição dos bens de acordo com a participação de cada cônjugue no acréscimo patrimonial
- **Dissolução do Casamento**: O processo pelo qual os cônjugues se separam e encerram sua sociedade conjugal

### Referências legais
- Art. 1.661, Código de Processo Civil
- Súmula 343 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da Dissolução do Casamento

### Dicas de prova
- Entenda a diferença entre acréscimo patrimonial e participação final
- Conheça as fases da apuração contábil nos aquestos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.432 (2)", "page_number": 432, "discipline": "Direito Civil", "legal_refs": ["Art. 1.661, Código de Processo Civil", "Súmula 343 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da Dissolução do Casamento"], "confidence": 0.8, "extracted_at": "2026-05-26T02:12:06.748816+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=432", "doc_key": "1aec86d26a483ca3c1dee0bfa3645ec6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ba3d5694ad1de7ed43692791cc811af0cec4a8ea716604b8c94b041909566c4b'),
  ('cpiuris2025::24b1e8960b82a8cc930f0c153965881f', 'doutrina', 'cp_iuris', 'Direito Civil — Regime da Separação de Bens', '## Regime da Separação de Bens

O regime da separação de bens é convencional ou obrigatório, estabelecendo uma distinção dos patrimônios dos cônjuges. A regra básica é que não haverá comunicação de qualquer bem, e cada proprietário exclusivo administra o bem, podendo aliená-lo ou gravá-lo com ônus real.

### Conceitos
- **Convencional**: Regime da separação de bens estipulado no pacto antenupcial
- **Obrigatório**: Regime da separação de bens determinado por lei
- **Comunicação de bens**: Não ocorre na separação convencional, mas é necessária na obrigatória
- **Outorga do outro cônjuge**: Necessária para venda de bens imóveis e gravá-los com ônus real no regime da separação obrigatória

### Referências legais
- Art. 1.641/CC
- Súmula 377/STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a necessidade de prova do esforço comum na partilha dos bens adquiridos na constância do casamento

### Dicas de prova
- Distinção entre convencional e obrigatório
- Comunicação de bens: separação convencional vs. obrigatória
- Outorga do outro cônjuge: necessidade em regime da separação obrigatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.433 (1)", "page_number": 433, "discipline": "Direito Civil", "legal_refs": ["Art. 1.641/CC", "Súmula 377/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a necessidade de prova do esforço comum na partilha dos bens adquiridos na constância do casamento"], "confidence": 0.8, "extracted_at": "2026-05-26T02:12:47.179495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=433", "doc_key": "24b1e8960b82a8cc930f0c153965881f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '892705918d94594404af4002260b1bd264e464dbe853ec8e3f7aa9651dec6c0b'),
  ('cpiuris2025::f4d8367c529bf220ef52d61a3b994a8e', 'doutrina', 'cp_iuris', 'Direito Civil — Direito à Partilha no Regime de Separação Obrigatória de Bens', '## Direito à Partilha no Regime de Separação Obrigatória de Bens

O ônus da prova passa ao cônjuge virago, que deve provar sua contribuição para aquisição do bem. Se provada, terá direito apenas à proporção da sua contribuição.

### Conceitos
- **Cônjuge Virago**: Cônjuge que não tem patrimônio próprio e depende do outro cônjuge para sustento
- **Contribuição para aquisição do bem**: Valor ou quantidade que o cônjuge contribuiu para a compra de um bem
- **Direito à Partilha**: Direito do cônjuge virago a receber uma parte do patrimônio conjugal após a separação obrigatória

### Referências legais
- Art. 1.629 CC/2002
- Súmula 377/STF

### Jurisprudência
- REsp 1637695/MG
- AgInt no REsp 1637695/MG

### Dicas de prova
- Entenda a diferença entre o ônus da prova e a contribuição para aquisição do bem
- Conheça a súmula 377/STF e sua aplicação no regime de separação obrigatória de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.433 (2)", "page_number": 433, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 CC/2002", "Súmula 377/STF"], "jurisprudence": ["REsp 1637695/MG", "AgInt no REsp 1637695/MG"], "confidence": 0.8, "extracted_at": "2026-05-26T02:13:29.482057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=433", "doc_key": "f4d8367c529bf220ef52d61a3b994a8e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a0b781005999289dd017b36149d1697cb50bc4d27a4196a6761b1ebd5a83285f'),
  ('cpiuris2025::658ff8da935fa0ed5cf66647449bb2ee', 'doutrina', 'cp_iuris', 'Direito Civil — Pacto antenupcial e contrato de convivência', '## Pacto antenupcial e contrato de convivência

Regras econômicas para o patrimônio da unidade familiar, definindo o estatuto patrimonial - regime de bens - do casamento ou união estável.

### Conceitos
- **Pacto antenupcial**: Acordo feito antes do casamento que define as regras econômicas para o patrimônio da unidade familiar.
- **Contrato de convivência**: Acordo feito após o casamento que define as regras econômicas para o patrimônio da unidade familiar.
- **Estatuto patrimonial - regime de bens**: Definição das regras econômicas que regerão o patrimônio da unidade familiar.
- **União estável**: Relação conjugal não casada, com estatuto patrimonial definido por acordo ou contrato.
- **FGTS**: Fundo de Garantia do Tempo de Serviço, destinado a proteger os direitos dos trabalhadores.

### Referências legais
- Art. 1.723 do Código Civil

### Jurisprudência
- Súmula n. 377 do STF
- RE 123456

### Dicas de prova
- Entenda a diferença entre pacto antenupcial e contrato de convivência.
- Conheça as regras para definir o estatuto patrimonial - regime de bens - do casamento ou união estável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.434 (1)", "page_number": 434, "discipline": "Direito Civil", "legal_refs": ["Art. 1.723 do Código Civil"], "jurisprudence": ["Súmula n. 377 do STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T02:14:09.047880+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=434", "doc_key": "658ff8da935fa0ed5cf66647449bb2ee"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0ef712476f65420d8c211a602441ab2d1aa3c289eb0445c89b0a960ae91db3c5'),
  ('cpiuris2025::ff0a316e092843dcd6ce18634fd52f6a', 'doutrina', 'cp_iuris', 'Direito Civil — Natureza jurídica do FGTS', '## Natureza jurídica do FGTS

O FGTS é considerado um direito dos trabalhadores brasileiros, consubstanciado na criação de um ''pecúlio permanente'' que pode ser sacado em circunstâncias legalmente definidas.

### Conceitos
- **FGTS**: Fundo de Garantia do Tempo de Serviço
- **direito dos trabalhadores**: Direito conferido aos trabalhadores brasileiros
- **pecúlio permanente**: Bens que pertencem ao trabalhador e podem ser sacados em circunstâncias legais

### Referências legais
- Art. 7º, III da CF
- Art. 20 da Lei 8.036/1990

### Jurisprudência
- ARE 709.212-DF (STF, 2015)
- REsp 758.548-MG (STJ, 2006)
- REsp 848.660-RS (STJ, 2011)

### Dicas de prova
- Entenda a natureza jurídica do FGTS e sua relação com o direito dos trabalhadores
- Conheça as diferentes visões da doutrina civilista sobre o FGTS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.434 (2)", "page_number": 434, "discipline": "Direito Civil", "legal_refs": ["Art. 7º, III da CF", "Art. 20 da Lei 8.036/1990"], "jurisprudence": ["ARE 709.212-DF (STF, 2015)", "REsp 758.548-MG (STJ, 2006)", "REsp 848.660-RS (STJ, 2011)"], "confidence": 0.8, "extracted_at": "2026-05-26T02:14:41.092736+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=434", "doc_key": "ff0a316e092843dcd6ce18634fd52f6a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c06e152eb381b0fcdb07ff90fec300cc1adf6ad996b50fbcac3f469e097441a1'),
  ('cpiuris2025::670c6c6e9d1c4d7810cb223ba0c94a38', 'doutrina', 'cp_iuris', 'Direito Civil — Proventos do Trabalho e Incomunicabilidade no Regime de Comunhão Parcial', '## Proventos do Trabalho e Incomunicabilidade no Regime de Comunhão Parcial

O artigo 1.659, VI do Código Civil estabelece que os proventos do trabalho pessoal de cada cônjuge não se comunicam no regime da comunhão parcial de bens, mas o Superior Tribunal de Justiça reconheceu que não há excluir da universalidade dos bens comuns esses proventos.

### Conceitos
- **Provento do Trabalho**: Valor recebido pelo trabalhador como compensação pela sua atividade laboral
- **Comunhão Parcial de Bens**: Regime de patrimônio compartilhado apenas entre os bens adquiridos ou originados anteriormente ao casamento
- **Incomunicabilidade**: Exclusão da comunicação dos proventos do trabalho pessoal de cada cônjuge no regime da comunhão parcial

### Referências legais
- Art. 1.659, VI do CC/02

### Jurisprudência
- REsp 848.660-RS
- ...

### Dicas de prova
- Entenda a diferença entre o regime de comunhão parcial e incomunicabilidade dos proventos do trabalho
- Conheça a posição atual do Superior Tribunal de Justiça sobre a questão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.435 (1)", "page_number": 435, "discipline": "Direito Civil", "legal_refs": ["Art. 1.659, VI do CC/02"], "jurisprudence": ["REsp 848.660-RS", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:15:26.630350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=435", "doc_key": "670c6c6e9d1c4d7810cb223ba0c94a38"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1507ab2fccd3b8041df22a326133518014d086ba505c82aacb59c22f35263c9f'),
  ('cpiuris2025::803630273eb4b31518f8e214b0aed786', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento de Proventos no Casamento', '## Reconhecimento de Proventos no Casamento

O reconhecimento de proventos recebidos durante o casamento reforça o patrimônio comum, que deve ser dividido em eventual partilha de bens. A comunicação das verbas trabalhistas ocorre quando adquiridas durante o casamento.

### Conceitos
- **Patrimônio Comum**: A soma dos bens e direitos adquiridos por ambos os cônjuges durante o casamento.
- **Proventos no Casamento**: Receitas ou benefícios recebidos durante o casamento que reforçam o patrimônio comum.
- **Comunicação de Verbas Trabalhistas**: A transmissão das verbas trabalhistas recebidas durante o casamento ao patrimônio comum.

### Referências legais
- Art. 1.629, Código Civil
- Súmula 342 do STJ

### Jurisprudência
- REsp 421.801-RS (Quarta Turma, DJ 15/12/2003)
- REsp 355.581-PR (Terceira Turma, DJ 23/6/2003)

### Dicas de prova
- Distinção entre proventos recebidos durante e fora do casamento.
- Reconhecimento da comunicação de verbas trabalhistas no patrimônio comum.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.435 (2)", "page_number": 435, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629, Código Civil", "Súmula 342 do STJ"], "jurisprudence": ["REsp 421.801-RS (Quarta Turma, DJ 15/12/2003)", "REsp 355.581-PR (Terceira Turma, DJ 23/6/2003)"], "confidence": 0.8, "extracted_at": "2026-05-26T02:16:05.037298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=435", "doc_key": "803630273eb4b31518f8e214b0aed786"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '00d6bbe5d1e5faf2c952a268f7af15b851ae21c23f33ff10c4e72a7032b819c5'),
  ('cpiuris2025::ca6ac18c55d0f6d6ae621ad28b729eec', 'doutrina', 'cp_iuris', 'Direito Civil — Meação no Divórcio', '## Meação no Divórcio

O direito de meação pode ser exercido mesmo após o saque dos valores durante a constância do casamento. A CEF deve ser comunicada para reservar a meação.

### Conceitos
- **Meação**: direito ao valor da meação no divórcio
- **Constância do casamento**: pelo tempo em que o casal está juntamente
- **Saque de valores**: saque dos valores durante a constância do casamento
- **CEF**: Comissão Especializada em Valores Mobiliários

### Referências legais
- Art. 1.629 CC/2002

### Dicas de prova
- Diferenciar entre saque e meação
- Entender o papel da CEF no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.435 (3)", "page_number": 435, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:16:26.776709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=435", "doc_key": "ca6ac18c55d0f6d6ae621ad28b729eec"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd119d993b448dc3be1aa0e8bed87e6d7ebab79f323f6ff2901eb650cde13a4a0'),
  ('cpiuris2025::9498b6e534c4538ad586265b7e9e3abd', 'doutrina', 'cp_iuris', 'Direito Civil — Saque em Dissolução de União Estável', '## Saque em Dissolução de União Estável

Revisão da necessidade de comprovação de esforço comum e comunicação de bens adquiridos na constância da união estável, bem como a comunicabilidade do prêmio de loteria.

### Conceitos
- **Esforço Comum**: Demonstração necessária para legitimar a divisão dos bens adquiridos durante a união estável
- **Comunicação de Bens**: Ocorre apenas mediante o esforço comum entre os cônjuges
- **Premio de Loteria**: Bem comum, sua comunicabilidade ocorre em favor do casal

### Referências legais
- Art. 258, parágrafo único, inciso II, do Código Civil de 1916
- Súmula 377 do STF

### Jurisprudência
- RE 1.399.199-RS

### Dicas de prova
- Distinção entre esforço comum e comunicação de bens
- Comunicação de bens adquiridos na constância da união estável
- Conhecimento do prêmio de loteria como bem comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.436 (1)", "page_number": 436, "discipline": "Direito Civil", "legal_refs": ["Art. 258, parágrafo único, inciso II, do Código Civil de 1916", "Súmula 377 do STF"], "jurisprudence": ["RE 1.399.199-RS"], "confidence": 0.8, "extracted_at": "2026-05-26T02:17:11.238246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=436", "doc_key": "9498b6e534c4538ad586265b7e9e3abd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3be7ebc2221270796d35184bbecdaf825d24e3824458864c6cbf2c762ccbc7b4'),
  ('cpiuris2025::69f90167b2385d33e020dd0307719df8', 'doutrina', 'cp_iuris', 'Direito Civil — Comunhabilidade de bens adquiridos por fato eventual', '## Comunhabilidade de bens adquiridos por fato eventual

A loteria pode ingressar na comunhão sob a rubrica de ''bens adquiridos por fato eventual'', com ou sem o concurso de trabalho ou despesa anterior. Isso significa que o prêmio de loteria pode ser objeto de partilha com a ex-companheira, independentemente da aferição do esforço de cada um.

### Conceitos
- **Comunhabilidade**: A regra segundo a qual os bens adquiridos durante o casamento ou união estão sob a comunidade patrimonial dos cônjuges.
- **Fato eventual**: Um evento que não está relacionado ao esforço de trabalho ou à despesa anterior, mas pode afetar a propriedade de um bem.
- **Sociedade conjugal**: Um conjunto de direitos e obrigações que ligam os cônjuges, estando contida no vínculo matrimonial.
- **Vínculo matrimonial**: O casamento ou união estável entre duas pessoas.
- **Comunicação de bens**: A partilha dos bens adquiridos durante o casamento ou união, independentemente da aferição do esforço de cada um.
- **Despesa anterior**: Uma despesa que foi realizada antes da aquisição de um bem.
- **Esforço de trabalho**: A contribuição de cada cônjuges para o sustento do casal.

### Referências legais
- CC/1916, art. 271, II; CC/02, art. 1.660, II

### Jurisprudência
- REsp 1.689.152-SC
- Tema repetitivo ...

### Dicas de prova
- Pergunte se a loteria pode ser objeto de partilha com a ex-companheira.
- Entenda a diferença entre sociedade conjugal e vínculo matrimonial.
- Conheça as regras da comunicação de bens adquiridos por fato eventual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.436 (2)", "page_number": 436, "discipline": "Direito Civil", "legal_refs": ["CC/1916, art. 271, II; CC/02, art. 1.660, II"], "jurisprudence": ["REsp 1.689.152-SC", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:18:00.588950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=436", "doc_key": "69f90167b2385d33e020dd0307719df8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8941ff7c60926dfd22b9da6c87d41e1e63a56c79c5e36859c591c699ae66f7ec'),
  ('cpiuris2025::e2a9d1abaefdfd01fab89dcaceecbeff', 'doutrina', 'cp_iuris', 'Direito Civil — Extinção da Sociedade Conjugal e Dissolução do Vínculo Matrimonial', '## Extinção da Sociedade Conjugal e Dissolução do Vínculo Matrimonial

A extinção da sociedade conjugal não necessariamente significa a dissolução do vínculo matrimonial, que só ocorre em casos específicos como morte de um dos cônjuges, anulação do casamento ou divórcio. A Emenda Constitucional n. 66/2010 permitiu o divórcio independentemente de lapso temporal de separação.

### Conceitos
- **Vínculo Matrimonial**: Relação jurídica entre os cônjuges
- **Sociedade Conjugal**: Unidade econômica e familiar dos cônjuges
- **Divórcio**: Dissolução do vínculo matrimonial por meio de um processo judicial

### Referências legais
- Art. 226 da CF/88
- Emenda Constitucional n. 66/2010
- Lei nº 6.515/1977

### Jurisprudência
- RE 123456
- Tema repetitivo do divórcio

### Dicas de prova
- Entenda a distinção entre extinção da sociedade conjugal e dissolução do vínculo matrimonial
- Conheça as hipóteses em que o vínculo matrimonial se dissolve', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.437 (1)", "page_number": 437, "discipline": "Direito Civil", "legal_refs": ["Art. 226 da CF/88", "Emenda Constitucional n. 66/2010", "Lei nº 6.515/1977"], "jurisprudence": ["RE 123456", "Tema repetitivo do divórcio"], "confidence": 0.8, "extracted_at": "2026-05-26T02:18:44.805363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=437", "doc_key": "e2a9d1abaefdfd01fab89dcaceecbeff"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5fa6fcf50ce0a6aa70b4859a539b9edcdef6911d1dcf57121a69ef6c22c3034e'),
  ('cpiuris2025::678c9ab44ddc55f6ca5e06d9b01e7d94', 'doutrina', 'cp_iuris', 'Direito Civil — Comprovação de lapso temporal de separação de fato ou judicial para deferimento do divórcio', '## Comprovação de lapso temporal de separação de fato ou judicial para deferimento do divórcio

A emenda discute se revogou os artigos do Código Civil que tratam da separação judicial, argumentando que não há interesse para a separação quando o divórcio é possível.

### Conceitos
- **Separação Judicial**: Divisão de bens conjugalmente adquiridos
- **Lapso Temporal**: Prazo para se propor o Divórcio, seja ele judicial ou não
- **Divórcio**: Dissolução do vínculo matrimonial

### Referências legais
- Art. 226 da Constituição Federal
- Código Civil

### Dicas de prova
- Entenda a diferença entre separação judicial e divórcio.
- Conheça os prazos para se propor o Divórcio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.437 (2)", "page_number": 437, "discipline": "Direito Civil", "legal_refs": ["Art. 226 da Constituição Federal", "Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:19:28.612290+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=437", "doc_key": "678c9ab44ddc55f6ca5e06d9b01e7d94"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4fd9427d40da6a84432e99144bd05f8789ede3122cb9a69d349bb356709017bb'),
  ('cpiuris2025::d03c3e9035cc118a08468e5e1a22a32f', 'doutrina', 'cp_iuris', 'Direito Civil — Divórcio e Separação de Direito', '## Divórcio e Separação de Direito

O Divórcio não mais exige indicação da causa de pedir, e as controvérsias referentes a motivos, culpa ou prazos deixam de integrar o objeto da demanda. A separação de direito foi banida do sistema jurídico.

### Conceitos
- **Divórcio**: Fim do casamento sem necessidade de indicação da causa de pedir
- **Separação de Direito**: Instituto banido do sistema jurídico
- **EC 66/10**: Emenda Constitucional que revogou a legislação ordinária sobre separação judicial
- **Competência da Ação de Separação**: Forno do domicílio do guardião do filho incapaz, último domicílio do casal ou foro do réu

### Referências legais
- Art. 1.574 do CC
- Art. 5º da Lei de Introdução
- Art. 8º do CPC/2015

### Jurisprudência
- RE 123456
- Tema repetitivo: separação jurídica

### Dicas de prova
- Entenda a diferença entre Divórcio e Separação de Direito
- Conheça as competências da Ação de Separação
- Análise do impacto da EC 66/10 na legislação ordinária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.438 (1)", "page_number": 438, "discipline": "Direito Civil", "legal_refs": ["Art. 1.574 do CC", "Art. 5º da Lei de Introdução", "Art. 8º do CPC/2015"], "jurisprudence": ["RE 123456", "Tema repetitivo: separação jurídica"], "confidence": 0.8, "extracted_at": "2026-05-26T02:20:13.839610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=438", "doc_key": "d03c3e9035cc118a08468e5e1a22a32f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '67d53aca1db7286520cf7fe40e3b2774cc114a3aa50e5bf3704d0129e33e44ad'),
  ('cpiuris2025::1d60fa844d6d90b03ff021d652ce8994', 'doutrina', 'cp_iuris', 'Direito Civil — Separação Judicial', '## Separação Judicial

O tema da separação judicial é objeto de análise pelo STF, com a Repercussão Geral de questão constitucional reconhecida em 2019. O Supremo Tribunal Federal deve examinar se o instituto da separação permanece no ordenamento jurídico brasileiro.

### Conceitos
- **Separação Judicial**: Instituto que permite a divisão de bens e direitos entre cônjuge, após divórcio.
- **Repercussão Geral**: Questão constitucional que tem impacto em várias decisões judiciais.
- **Instituto da Separação Judicial**: Divisão de bens e direitos entre cônjuge, após divórcio.

### Referências legais
- Art. 1.609, CC/2002; Art. 1.608, CC/2002

### Jurisprudência
- REsp 1.431.370-SP
- RE 1.167.478/RJ

### Dicas de prova
- Entenda a noção de Repercussão Geral e seu impacto nas decisões judiciais.
- Conheça os doutrinadores favoráveis à manutenção da separação judicial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.438 (2)", "page_number": 438, "discipline": "Direito Civil", "legal_refs": ["Art. 1.609, CC/2002; Art. 1.608, CC/2002"], "jurisprudence": ["REsp 1.431.370-SP", "RE 1.167.478/RJ"], "confidence": 0.8, "extracted_at": "2026-05-26T02:20:51.277840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=438", "doc_key": "1d60fa844d6d90b03ff021d652ce8994"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '250b4918b74e0a9efa3abb9f058ee23e376eb379919e6af9147ed2d2830efc32'),
  ('cpiuris2025::cd2beb50a0d4e4ec9288979c3caa46c6', 'doutrina', 'cp_iuris', 'Direito Civil — Separação Judicial e Discussão de Culpa', '## Separação Judicial e Discussão de Culpa

A separação judicial é uma opção para as partes que não pretendem o divórcio direto, com base na possibilidade de discussão de culpa. A discussão de culpa é prevista apenas na separação no Código Civil.

### Conceitos
- **Separação Judicial**: Opção para as partes que não pretendem o divórcio direto
- **Discussão de Culpa**: Possibilidade de apreciação do judiciário em separação judicial, mas não no divórcio
- **Dignidade da Pessoa Humana**: Princípio que pode ser violado pela discussão de culpa
- **Alimentos**: Obrigação do outro cônjuge de prestá-los se um dos cônjuges separados judicialmente precisar
- **Constitucionalidade**: Questão relevante para a discussão de culpa na separação judicial

### Referências legais
- Art. 1.572/CC
- Art. 1.573/CC

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Entenda a diferença entre separação judicial e divórcio direto
- Conheça o princípio da dignidade da pessoa humana e sua relação com a discussão de culpa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.439 (1)", "page_number": 439, "discipline": "Direito Civil", "legal_refs": ["Art. 1.572/CC", "Art. 1.573/CC"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T02:21:53.267996+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=439", "doc_key": "cd2beb50a0d4e4ec9288979c3caa46c6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '18074500f50d369ed12deb367bac7adbc0039c580d540f9fa775c213582dfb9f'),
  ('cpiuris2025::936d43e592a2a8afade478d8c999f32d', 'doutrina', 'cp_iuris', 'Direito Civil — Pensões alimentares após separação judicial', '## Pensões alimentares após separação judicial

O artigo 1.578/CC estabelece a possibilidade de perda do nome de casado(a) em razão do reconhecimento da culpa, além de determinar as regras para pensões alimentares após separação judicial.

### Conceitos
- **Pensão alimentar**: ajuda financeira prestada por um cônjuge à outra após separação judicial
- **Separação Judicial**: processo que visa a dissolução da união conjugal sem necessidade de divórcio
- **Culpa**: reconhecimento do erro ou negligência de um cônjuge na separação judicial

### Referências legais
- Art. 1.578/CC
- Parágrafo único do Art. 1.577/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre o nome de família e os filhos
- Evidente prejuízo para a identificação
- Manifesta distinção entre o nome de casado(a) e o dos filhos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.439 (2)", "page_number": 439, "discipline": "Direito Civil", "legal_refs": ["Art. 1.578/CC", "Parágrafo único do Art. 1.577/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:22:35.571465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=439", "doc_key": "936d43e592a2a8afade478d8c999f32d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b05d10c8383e305922bbe4ba69725afceb2fed066dc85770fe34960a5453467a'),
  ('cpiuris2025::644f6c6843fa307ab64615c68d2fc9a0', 'doutrina', 'cp_iuris', 'Direito Civil — Indenização por dano moral em separação de cônjuge', '## Indenização por dano moral em separação de cônjuge

O autor argumenta que a discussão da culpa na separação não é necessária para determinar os alimentos, pois eles são fundamentados na solidariedade familiar. Além disso, o sobrenome não pode ser perdido após a adoção do casamento.

### Conceitos
- **Culpa na separação**: Discussão sobre a responsabilidade de um cônjuge pela separação
- **Alimentos**: Sustento financeiro concedido a uma pessoa por outro em regime de separação de convívio conjugal ou por morte do cônjuge
- **Solidariedade familiar**: Princípio que fundamenta os alimentos, sendo um direito fundamental da personalidade

### Referências legais
- Art. 1.572 CC
- Art. 1573 CC
- Art. 1.578 CC

### Jurisprudência
- RE 123456
- Enunciado n. 254 da Jornada de Direito

### Dicas de prova
- Entenda a relação entre culpa na separação e alimentos
- Conheça o conceito de solidariedade familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.440 (1)", "page_number": 440, "discipline": "Direito Civil", "legal_refs": ["Art. 1.572 CC", "Art. 1573 CC", "Art. 1.578 CC"], "jurisprudence": ["RE 123456", "Enunciado n. 254 da Jornada de Direito"], "confidence": 0.8, "extracted_at": "2026-05-26T02:23:28.984436+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=440", "doc_key": "644f6c6843fa307ab64615c68d2fc9a0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5ac9d6e14b20a5d603bf2cdb286d4da4f7144f86da3a0457e99834abc669d7d3'),
  ('cpiuris2025::fe44882dc37d2fd61f3a0a34aa829cef', 'doutrina', 'cp_iuris', 'Direito Civil — Separação Judicial', '## Separação Judicial

A separação judicial pode ser consensual ou litigiosa, e tem base na culpa de um dos cônjuges, impossibilidade da vida em comum ou doença mental grave de um dos cônjuges.

### Conceitos
- **Separação Judicial**: Processo que visa a terminação da sociedade conjugal
- **Culpa**: Obrigação de reparar danos causados a outrem
- **Impossibilidade da vida em comum**: Condição que torna impossível a continuidade da relação conjugal
- **Doença mental grave**: Condição que afeta a capacidade de um cônjuge para viver em sociedade

### Referências legais
- Art. 1.572 e/ou art. 1.573 CC

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Entenda a distinção entre separação jurídica consensual e litigiosa
- Conheça as hipóteses de culpa, impossibilidade da vida em comum e doença mental grave', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.440 (2)", "page_number": 440, "discipline": "Direito Civil", "legal_refs": ["Art. 1.572 e/ou art. 1.573 CC"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T02:24:25.914572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=440", "doc_key": "fe44882dc37d2fd61f3a0a34aa829cef"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7b83616ffb8347b23717453e2572ec716c72eb0f4a3d73bc040d2f8170a53888'),
  ('cpiuris2025::e50b8277d9b0f07b70bba24b11809c5d', 'doutrina', 'cp_iuris', 'Direito Civil — Separação Jurídica Litigiosa e Consensual', '## Separação Jurídica Litigiosa e Consensual

A separação jurídica litigiosa é um procedimento que tramita em segredo de justiça, com acesso apenas às partes e advogados. A ação de separação consensual pode ser requerida após homologação de acordo assinado por ambos os cônjuges.

### Conceitos
- **Separação Jurídica Litigiosa**: Procedimento que tramita em segredo de justiça, com acesso apenas às partes e advogados.
- **Ação de Separação Consensual**: Requerida após homologação de acordo assinado por ambos os cônjuges
- **Homologação de Acordo**: Processo em que um acordo entre as partes é homologado pelo juiz.
- **Partilha de Bens Comuns**: Divisão dos bens comuns do casal, de acordo com o acordo assinado.

### Referências legais
- Art. 731 do NCPC
- Art. 1.581/CC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre separação jurídica litigiosa e consensual
- Entender a importância da homologação de acordo em ações de separação consensual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.441 (1)", "page_number": 441, "discipline": "Direito Civil", "legal_refs": ["Art. 731 do NCPC", "Art. 1.581/CC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T02:25:24.453700+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=441", "doc_key": "e50b8277d9b0f07b70bba24b11809c5d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd10652c338d17b3595ad68ad5ab0ec579425ca1985b2c24097c42e668c422456'),
  ('cpiuris2025::fcaeee84413946e2d566dcf175ea2091', 'doutrina', 'cp_iuris', 'Direito Civil — Procedimento Extrajudicial de Divórcio e Dissolução de União Estável', '## Procedimento Extrajudicial de Divórcio e Dissolução de União Estável

O procedimento extrajudicial para divórcio, separação consensual e dissolução de união estável pode ser realizado por escritura pública, desde que os requisitos legais sejam observados.

### Conceitos
- **Divórcio Consensual**: Procedimento extrajudicial para divórcio, com acordo entre as partes.
- **Separação Consensual**: Procedimento extrajudicial para separação de casamento, com acordo entre as partes.
- **Dissolução de União Estável**: Procedimento extrajudicial para dissolução de união estável, com acordo entre as partes.

### Referências legais
- Art. 733 do Código de Processo Civil

### Dicas de prova
- Requisitos legais devem ser observados para procedimento extrajudicial.
- Acordo entre as partes é fundamental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.441 (2)", "page_number": 441, "discipline": "Direito Civil", "legal_refs": ["Art. 733 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:26:02.549944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=441", "doc_key": "fcaeee84413946e2d566dcf175ea2091"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '56681d655808c4c27e4d669bcb150c0feeb4cbcf10b74dfb2ff4da7d8b30fc19'),
  ('cpiuris2025::a0f8ec84dacb7c01014176f22f437b6c', 'doutrina', 'cp_iuris', 'Direito Civil — Dissolução do Vínculo Matrimonial', '## Dissolução do Vínculo Matrimonial

A dissolução do vínculo matrimonial pode ocorrer por meio de divórcio judicial ou extrajudicial, com o objetivo de desafogar o judiciário e permitir soluções extrajudiciais para certas questões.

### Conceitos
- **Divórcio Judicial**: Procedimento que coloca fim ao casamento por meio do Poder Judiciário
- **Divórcio Extrajudicial**: Procedimento que permite soluções extrajudiciais para certas questões de dissolução do vínculo matrimonial
- **Desjudicialização**: Movimento que busca desafogar o judiciário permitindo soluções extrajudiciais

### Referências legais
- Art. 1.629 CC/2002
- Súmula 245 STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: Dissolução do Vínculo Matrimonial

### Dicas de prova
- Entenda a diferença entre divórcio judicial e extrajudicial
- Conheça o conceito de desjudicialização e seu impacto no sistema judiciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.442 (1)", "page_number": 442, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 CC/2002", "Súmula 245 STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Dissolução do Vínculo Matrimonial"], "confidence": 0.8, "extracted_at": "2026-05-26T02:26:58.566350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=442", "doc_key": "a0f8ec84dacb7c01014176f22f437b6c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a46397af8032add594c4d6d5738eb5f5c1e2f22adaa56605a1922123ad1bdc8e'),
  ('cpiuris2025::6a0e13694624b89dff2d82ad0575cc32', 'doutrina', 'cp_iuris', 'Direito Civil — Divórcio e Regime Matrimonial', '## Divórcio e Regime Matrimonial

O art. 1.581 do CC estabelece que o divórcio pode ser concedido sem prévia partilha de bens, mas com imposição do regime da separação obrigatória de bens em caso de novo enlace matrimonial.

### Conceitos
- **Divórcio**: Processo que visa a dissolução da união conjugal
- **Regime Matrimonial**: Condição jurídica que regula a propriedade e os bens dos cônjuges
- **Partilha de Bens**: Divisão obrigatória dos bens entre os cônjuges no momento do divórcio
- **Separação Obrigatória de Bens**: Regime jurídico que impõe a separação dos bens dos cônjuges

### Referências legais
- Art. 1.581 do CC
- Art. 1.641, I do CC
- Art. 1.523, III do CC

### Dicas de prova
- Destacar a importância da partilha de bens no divórcio
- Entender a relação entre o divórcio e o regime matrimonial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.442 (2)", "page_number": 442, "discipline": "Direito Civil", "legal_refs": ["Art. 1.581 do CC", "Art. 1.641, I do CC", "Art. 1.523, III do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:27:27.987049+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=442", "doc_key": "6a0e13694624b89dff2d82ad0575cc32"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9a51c8d407ae091011514c437a04c241c030c3185f8560beb15839ad5014a18a'),
  ('cpiuris2025::fc6791404600402f210daa1fba6799a6', 'doutrina', 'cp_iuris', 'Direito Civil — Divórcio', '## Divórcio

O divórcio é um direito potestativo sem prazo, permitindo que uma parte se divorcie do outro sem impedimento. A discussão sobre a possibilidade de pleitear pedido de tutela de urgência no contexto do divórcio é relevante, considerando o artigo 300 e seguintes do Código de Processo Civil.

### Conceitos
- **Direito Potestativo**: A possibilidade que tem a parte de interferir na esfera jurídica do outrem sem que ele se oponha.
- **Tutela de Urgência**: Um pedido urgente que pode ser pleiteado em ação de divórcio, submetendo-se aos requisitos do art. 300 e seguintes do Código de Processo Civil.
- **Divórcio Direto**: O tipo de divórcio que não envolve litigiosidade, sendo o mais comum atualmente.
- **Conversão**: O tipo de divórcio que pode ocorrer após a separação jurídica entre os cônjuges.

### Referências legais
- Art. 300 e seguintes do Código de Processo Civil

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre divórcio direto e conversão.
- Conheça os requisitos para o pedido de tutela de urgência no contexto do divórcio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.443 (1)", "page_number": 443, "discipline": "Direito Civil", "legal_refs": ["Art. 300 e seguintes do Código de Processo Civil"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T02:28:09.036107+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=443", "doc_key": "fc6791404600402f210daa1fba6799a6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '54ab3e32d74fff433c832576965ddd5685f633c296294a1fb36e9d9eac79e79d'),
  ('cpiuris2025::77f30bae3a7ffb29ac35fbc1fcff95ee', 'doutrina', 'cp_iuris', 'Direito Civil — Partilha de Bens em Divórcio e União Estável', '## Partilha de Bens em Divórcio e União Estável

A partilha de bens em divórcio pode ser afetada pela existência de uma união estável, necessitando-se da prova de que a relação estava estabelecida antes do casamento.

### Conceitos
- **União Estável**: Relação conjugal não casada, com características semelhantes às de um casamento
- **Partilha de Bens**: Divisão dos bens adquiridos por casal durante o casamento
- **Divórcio**: Fim do casamento por meio de decreto judicial
- **Má-fé**: Dolo ou fraude na aquisição de bens

### Referências legais
- Art. 150, § 2º, da CC/2002

### Jurisprudência
- STJ. REsp 1.739.042-SP
- Súmula 679 do STJ

### Dicas de prova
- Distinção entre união estável e casamento
- Importância da prova de união estável antes do casamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.443 (2)", "page_number": 443, "discipline": "Direito Civil", "legal_refs": ["Art. 150, § 2º, da CC/2002"], "jurisprudence": ["STJ. REsp 1.739.042-SP", "Súmula 679 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T02:28:47.688235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=443", "doc_key": "77f30bae3a7ffb29ac35fbc1fcff95ee"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '507942a62ea978a0126463238a630f14010bd12a478f67e59bd1025144bb9437'),
  ('cpiuris2025::17c7ab4ff87b554f58e64b355957e55e', 'doutrina', 'cp_iuris', 'Direito Civil — Discussão de culpa no divórcio', '## Discussão de culpa no divórcio

O STJ decidiu que não se comunicam os bens adquiridos por uma das partes antes do casamento durante o divórcio. A discussão de culpa no divórcio é questionada, com alguns doutrinadores argumentando que não pode ser discutida.

### Conceitos
- **Divórcio**: Processo de separação legal dos cônjuges
- **Culpa**: Obrigação de reparar os danos causados a outrem
- **Discussão de culpa**: A discussão da culpa entre as partes no divórcio é questionada
- **Separação diante do ordenamento jurídico pátrio**: O divórcio comportaria a discussão de culpa, de acordo com alguns doutrinadores
- **Mitigação da culpa**: A redução da culpa em situações específicas, como culpa recíproca ou deterioração do casamento

### Referências legais
- Art. 1.566 do CC
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a noção de culpa e sua aplicação no divórcio
- Conheça os doutrinadores que questionam a discussão de culpa no divórcio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.444 (1)", "page_number": 444, "discipline": "Direito Civil", "legal_refs": ["Art. 1.566 do CC", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:29:25.199272+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=444", "doc_key": "17c7ab4ff87b554f58e64b355957e55e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2b6068249d5def0e6eaf16a82b532957c9780a49180fa5c1d3a9a5e78972a530'),
  ('cpiuris2025::1ee7fb9b9dc6d88b7f3af8efda15c417', 'doutrina', 'cp_iuris', 'Direito Civil — Uso do Sobrenome no Casamento', '## Uso do Sobrenome no Casamento

O uso do sobrenome do cônjuge é regulamentado pelo artigo 1.578/CC, que estabelece regras para a manutenção ou alteração do sobrenome após o fim do casamento.

### Conceitos
- **sobrenome**: nome completo de uma pessoa
- **cônjuge**: spose
- **união**: matrimônio

### Referências legais
- Art. 1.578/CC

### Jurisprudência
- REsp 1.841.128-MG

### Dicas de prova
- Entenda a regra de manutenção ou alteração do sobrenome após o fim do casamento.
- Conheça as exceções previstas no artigo 1.578/CC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.444 (2)", "page_number": 444, "discipline": "Direito Civil", "legal_refs": ["Art. 1.578/CC"], "jurisprudence": ["REsp 1.841.128-MG"], "confidence": 0.8, "extracted_at": "2026-05-26T02:29:47.245600+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=444", "doc_key": "1ee7fb9b9dc6d88b7f3af8efda15c417"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5fcf2ab9bb55d9a09991e6a236c1303ea0ecb1b68c2f065945c78224af673f38'),
  ('cpiuris2025::6d7cea45490e7dd1a6a96c6f52763cba', 'doutrina', 'cp_iuris', 'Direito Civil — Manutenção do Nome de Casado após Divórcio', '## Manutenção do Nome de Casado após Divórcio

A lei exige que o cônjuge culpado perca o nome do outro cônjuge para manter o sobrenome, mas há discussão sobre a opção pela não manutenção ser sempre daquele que o adotou, independentemente de culpa.

### Conceitos
- **Culpa**: Responsabilidade pelo fato que levou à separação
- **Separação Judicial**: Divórcio sem necessidade de processo judicial
- **Dano Grave**: Prejuízo significativo causado pela retirada do sobrenome do ex-cônjuge
- **Direito da Personalidade**: Direitos inalienáveis e fundamentais da pessoa
- **Princípio da Dignidade da Pessoa Humana**: Direito fundamental que protege a dignidade e o valor humano

### Referências legais
- Art. 1.578 do CC
- EC 66/2010

### Jurisprudência
- Tartuce, 2020, pg. 1921; Súmula N STJ

### Dicas de prova
- Entenda a noção de dano grave e sua importância na manutenção do nome de casado
- Conheça o princípio da dignidade da pessoa humana e como ele se aplica à manutenção do nome de casado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.445 (1)", "page_number": 445, "discipline": "Direito Civil", "legal_refs": ["Art. 1.578 do CC", "EC 66/2010"], "jurisprudence": ["Tartuce, 2020, pg. 1921; Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T02:30:32.760244+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=445", "doc_key": "6d7cea45490e7dd1a6a96c6f52763cba"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1fbf223923e45960836c5c440a172c405d7fe10ffc36490b3c9153d50e088431'),
  ('cpiuris2025::50b2ac382b5a2db1c621ed93f136ca37', 'doutrina', 'cp_iuris', 'Direito Civil — Dissolução do casamento por morte presumida', '## Dissolução do casamento por morte presumida

A morte presumida pode ser reconhecida com ou sem decretação de ausência, de acordo com o artigo 6º/CC.

### Conceitos
- **ausência**: situação em que a lei autoriza a abertura de sucessão definitiva
- **morte presumida**: reconhecimento da morte de uma pessoa sem decretação formal

### Referências legais
- Art. 6º/CC

### Jurisprudência
- STJ, REsp 241.200/RJ
- STJ, REsp 241.200/RJ (Rel. Min. Aldir Passarinho Junior)

### Dicas de prova
- Entenda a diferença entre morte presumida e ausência
- Conheça o artigo 6º/CC e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.445 (2)", "page_number": 445, "discipline": "Direito Civil", "legal_refs": ["Art. 6º/CC"], "jurisprudence": ["STJ, REsp 241.200/RJ", "STJ, REsp 241.200/RJ (Rel. Min. Aldir Passarinho Junior)"], "confidence": 0.8, "extracted_at": "2026-05-26T02:30:52.845082+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=445", "doc_key": "50b2ac382b5a2db1c621ed93f136ca37"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '949eb88580c77a3038b1277301a37927769e6cd36436dbccf6d859951652ad9f'),
  ('cpiuris2025::f0208118e7a27b80eb849ed06441969b', 'doutrina', 'cp_iuris', 'Direito Civil — Morte Presumida e Casamento', '## Morte Presumida e Casamento

O artigo 7º do CC estabelece as condições para a declaração da morte presumida, sem decretação de ausência, e suas consequências no casamento. A morte presumida é considerada válida apenas se o ausente retornar, afetando a validade dos casamentos subsequentes.

### Conceitos
- **Morte Presumida**: Declaração de morte sem decretação de ausência
- **Casamento Subsequentemente**: Casamento celebrado após o reconhecimento da morte presumida
- **Consequências no Casamento**: Validade ou invalidade do casamento subsequente
- **Reaparecimento do Ausente**: Retorno do ausente após a declaração de morte presumida

### Referências legais
- Art. 7º do CC
- Art. 1.571, §1º do CC

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Morte Presumida e Casamento

### Dicas de prova
- Entenda a diferença entre morte presumida e decretação de ausência
- Conheça as consequências do reaparecimento do ausente no casamento subsequente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.446 (1)", "page_number": 446, "discipline": "Direito Civil", "legal_refs": ["Art. 7º do CC", "Art. 1.571, §1º do CC"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Morte Presumida e Casamento"], "confidence": 0.8, "extracted_at": "2026-05-26T02:31:26.441650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=446", "doc_key": "f0208118e7a27b80eb849ed06441969b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '90f999683108ee611f3eaf993a867115b75025ccb1e1a441c57e44d83e8b0354'),
  ('cpiuris2025::58af2bed99e212cbf73093b65d06319a', 'doutrina', 'cp_iuris', 'Direito Civil — Tratamento dos Alimentos em Divórcio e Separação Jurídica', '## Tratamento dos Alimentos em Divórcio e Separação Jurídica

Os alimentos devem ser analisados à luz da sociedade moderna, considerando a mudança na participação das mulheres no mercado de trabalho. A regra geral é que os alimentos sejam temporários, sendo fixados por tempo certo.

### Conceitos
- **Alimentos**: Ajuda financeira concedida à ex-spouse após divórcio ou separação jurídica
- **Temporariedade**: A regra geral é que os alimentos sejam concedidos por um período determinado
- **Solidariedade**: A obrigação de pagar alimentos é solidária, mesmo em caso de culpa
- **Separação Jurídica**: O regime jurídico aplicável às relações entre ex-cônjuges após a separação

### Referências legais
- Art. 1.634 do Código Civil de 2002

### Jurisprudência
- Súmula 342 do STF
- ...

### Dicas de prova
- Entenda a mudança social e a participação das mulheres no mercado de trabalho
- Conheça a regra geral de temporariedade dos alimentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.446 (2)", "page_number": 446, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634 do Código Civil de 2002"], "jurisprudence": ["Súmula 342 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:32:05.140939+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=446", "doc_key": "58af2bed99e212cbf73093b65d06319a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '474ee218fffbb630582afa514d9c447249c6ceb4d18fa8e0752d28cb5af8447b'),
  ('cpiuris2025::8d799b3e0a1d9236544a7e0111864276', 'doutrina', 'cp_iuris', 'Direito Civil — Uso do imóvel comum após divórcio e alimentação', '## Uso do imóvel comum após divórcio e alimentação

O uso exclusivo do imóvel comum por um dos ex-cônjuges após o divórcio autoriza a reivindicação de uma renda equivalente à parcela proporcional da quota-parte sobre a renda de um aluguel presumido. No entanto, quando o imóvel é utilizado como moradia da prole comum, a questão ganha contornos diferentes e incumbe a ambos os genitores arcar com os alimentos.

### Conceitos
- **Alimentação**: O direito de receber apoio financeiro para se sustentar
- **Imóvel comum**: Propriedade compartilhada por casais casados ou separados
- **Pecúnia**: Valor monetário de uma coisa ou serviço
- **In natura**: Sem valor monetário
- **STJ**: Superior Tribunal de Justiça

### Referências legais
- Art. 1.319 do Código Civil
- Art. 1.326 do Código Civil
- Art. 1.707 do Código Civil

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Entenda a noção de alimentação e seu valor jurídico
- Conheça as regras sobre o uso do imóvel comum após divórcio
- Aprenda a distinguir entre pecúnia e in natura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.447 (1)", "page_number": 447, "discipline": "Direito Civil", "legal_refs": ["Art. 1.319 do Código Civil", "Art. 1.326 do Código Civil", "Art. 1.707 do Código Civil"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T02:32:45.350735+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=447", "doc_key": "8d799b3e0a1d9236544a7e0111864276"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e660dcedaa8fb76fe4341b6e296399094eb27dde58d1f3a1c21811285d61de54'),
  ('cpiuris2025::a60e831d23c828b726b1482830967cc7', 'doutrina', 'cp_iuris', 'Direito Civil — Dissolução do casamento e destino dos bens comuns', '## Dissolução do casamento e destino dos bens comuns

A extinção da sociedade conjugal exige a partilha dos bens comuns, especialmente em regime de comunhão parcial.

### Conceitos
- **partilha**: divisão dos bens comuns entre as partes
- **regime de bens**: modalidade de propriedade compartilhada
- **sociedade conjugal**: relação conjugal que envolve a unidade patrimonial

### Referências legais
- Art. 1.636 do CC/2019
- ...

### Jurisprudência
- RE 123456
- Súmula 695/STJ

### Dicas de prova
- Entenda o conceito de partilha e regime de bens
- Conheça a sociedade conjugal e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.447 (2)", "page_number": 447, "discipline": "Direito Civil", "legal_refs": ["Art. 1.636 do CC/2019", "..."], "jurisprudence": ["RE 123456", "Súmula 695/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T02:33:06.872230+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=447", "doc_key": "a60e831d23c828b726b1482830967cc7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5e39d386b1d29265b70d37493c007fa3b01cdf384835bc8a2f26d46bb42dfec6'),
  ('cpiuris2025::153749f977f286d99c16106508e27e1c', 'doutrina', 'cp_iuris', 'Direito Civil — Regime de Convivência e Propriedade Comum', '## Regime de Convivência e Propriedade Comum

O regime de convivência é o que prevalece quando não há pacto antenupcial ou declaração de nulidade do regime. Os bens adquiridos durante o casamento podem ser objeto de partilha amigável, resultando em condomínio, que pode ser extinto com a venda do bem comum.

### Conceitos
- **Convivência**: Regime de convivência é o que prevalece quando não há pacto antenupcial ou declaração de nulidade do regime.
- **Propriedade Comum**: Bens adquiridos durante o casamento podem ser objeto de partilha amigável, resultando em condomínio
- **Condomínio**: Condomínio é a situação em que os cônjuges têm direito a um bem comum, que pode ser extinto com a venda do bem comum.
- **Partilha Amigável**: Partilha amigável é o processo de negociação entre as partes para definir a divisão dos bens adquiridos durante o casamento

### Referências legais
- Art. 1.319 do CC
- Art. 1.326 do CC

### Jurisprudência
- RE 123456
- Tema repetitivo da Súmula 234 STJ

### Dicas de prova
- Entenda a diferença entre convivência e propriedade comum
- Conheça as regras de partilha amigável e condomínio
- Aprenda a aplicar o princípio da boa-fé objetiva em casos de indenização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.448 (1)", "page_number": 448, "discipline": "Direito Civil", "legal_refs": ["Art. 1.319 do CC", "Art. 1.326 do CC"], "jurisprudence": ["RE 123456", "Tema repetitivo da Súmula 234 STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T02:33:59.085793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=448", "doc_key": "153749f977f286d99c16106508e27e1c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3b2b30a56300f46ff835dc9b227be2ecc6851c73dc84d9729868e4d82658c939'),
  ('cpiuris2025::51fec8b46ae642046052434295d3c8fa', 'doutrina', 'cp_iuris', 'Direito Civil — Pensão Alimentícia e Incompensabilidade', '## Pensão Alimentícia e Incompensabilidade

A pensão alimentícia é paga em dinheiro ou corresponde a uma obrigação in natura, sendo o devedor obrigado a fornecer bens necessários à sobrevivência do alimentando. O artigo 1.707 do Código Civil estabelece o princípio da incompensabilidade, mas a jurisprudência tem mitigado essa regra para evitar o enriquecimento indevido.

### Conceitos
- **Pensão Alimentícia**: Pagamento de uma obrigação para garantir a subsistência de um alimentando
- **Incompensabilidade**: Princípio que proíbe a compensação entre dívidas de alimentos e outras obrigações
- **Obrigação em Natura**: Obrigação que não é paga em dinheiro, mas sim na forma de um bem ou serviço
- **Bens Necessários**: Bens que são essenciais para a sobrevivência e bem-estar de uma pessoa

### Referências legais
- Art. 1.707 do Código Civil

### Jurisprudência
- Súmula 343 do STJ

### Dicas de prova
- Entenda o conceito de pensão alimentícia e sua relação com a incompensabilidade
- Conheça as hipóteses em que a obrigação de alimentos pode ser compensada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.448 (2)", "page_number": 448, "discipline": "Direito Civil", "legal_refs": ["Art. 1.707 do Código Civil"], "jurisprudence": ["Súmula 343 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T02:34:28.992698+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=448", "doc_key": "51fec8b46ae642046052434295d3c8fa"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b6edfcccf4768c30988e9899c97fef6c289e312ceed45ca508309df939b25e5e'),
  ('cpiuris2025::0827edf9753b2ec02840e446947d0378', 'doutrina', 'cp_iuris', 'Direito Civil — Direito das Famílias', '## Direito das Famílias

O direito do cônjuge sobrevivente à habitação em imóvel comum após a morte do outro cônjuge é regulamentado pelo direito real de habitação, que pode ser reconhecido se o cônjuge sobrevivente for proprietário exclusivo. Caso contrário, não há direito ao recebimento de aluguéis.

### Conceitos
- **Direito Real de Habitação**: O direito do cônjuge sobrevivente à habitação em imóvel comum após a morte do outro cônjuge.
- **Copropriedade**: A situação em que dois ou mais pessoas compartilham a propriedade de um imóvel.
- **Direito Potestativo**: O direito de extinguir uma relação sem que o outro possa se opor, geralmente por meio de alienação do bem comum.
- **Alienação Judicial**: A venda de um imóvel por meio de um processo judicial.
- **Indenização**: O pagamento de uma quantia para compensar uma perda ou dano.

### Referências legais
- Art. 1.634, § 3º, CC/2002

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Direito Real de Habitação''}
- {''RE'': ''RE 789012'', ''Tema'': ''Copropriedade e Direito Potestativo''}

### Dicas de prova
- Entenda a diferença entre direito real de habitação e direito potestativo.
- Conheça as regras de copropriedade e alienação judicial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.449 (1)", "page_number": 449, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634, § 3º, CC/2002"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Direito Real de Habitação''}", "{''RE'': ''RE 789012'', ''Tema'': ''Copropriedade e Direito Potestativo''}"], "confidence": 0.8, "extracted_at": "2026-05-26T02:35:12.333134+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=449", "doc_key": "0827edf9753b2ec02840e446947d0378"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5a7bb9fcbc05fed47c18232faffa08eda19317b9e5eb855617e4670109400e87'),
  ('cpiuris2025::36563010eebd473459316bd62ce25f8b', 'doutrina', 'cp_iuris', 'Direito Civil — Uso exclusivo e gratuito de imóvel comum indiviso', '## Uso exclusivo e gratuito de imóvel comum indiviso

O uso exclusivo e gratuito de um imóvel comum indiviso por um condômino pode ser afetado pela decretação judicial de medida protetiva em ação penal relacionada à violência doméstica e familiar.

### Conceitos
- **imóvel comum indiviso**: Propriedade compartilhada por múltiplos proprietários
- **uso exclusivo**: Uso feito por um proprietário sem interferência de outros
- **medida protetiva**: Ação judicial que visa proteger uma pessoa de violências ou ameaças
- **violência doméstica e familiar**: Tipo de violência que ocorre dentro da família ou relacionamentos
- **condômino**: Proprietário de um imóvel comum indiviso

### Referências legais
- Art. 1.234, CC/2022

### Jurisprudência
- REsp 1699013/DF
- REsp 1.852.807-PR
- EREsp 1.520.294/SP
- REsp 1.830.080-SP

### Dicas de prova
- Entenda a relação entre o uso exclusivo e a medida protetiva em ação penal.
- Conheça as implicações da violência doméstica e familiar no direito de uso do imóvel.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.449 (2)", "page_number": 449, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, CC/2022"], "jurisprudence": ["REsp 1699013/DF", "REsp 1.852.807-PR", "EREsp 1.520.294/SP", "REsp 1.830.080-SP"], "confidence": 0.8, "extracted_at": "2026-05-26T02:35:54.826507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=449", "doc_key": "36563010eebd473459316bd62ce25f8b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd74a3fcb2571c079513cf587c17b267518fd2500e601d3c3e70b041e4d7e8307'),
  ('cpiuris2025::1a5a1f47a793baac2da4cf2e380a42b8', 'doutrina', 'cp_iuris', 'Direito Civil — Uso e gozo do imóvel em casos de violência doméstica', '## Uso e gozo do imóvel em casos de violência doméstica

O uso e gozo exclusivo do imóvel em casos de violência doméstica não justifica a limitação do domínio sobre o imóvel, evitando-se o enriquecimento sem causa. A coproprietária vítima de violência doméstica detém o uso e gozo exclusivo do imóvel de cotitularidade do agressor.

### Conceitos
- **usucapir**: direito à propriedade por usão
- **animus domini**: estabilidade da posse sobre um bem
- **condomínio**: regime jurídico que rege a propriedade de imóveis compartilhados

### Referências legais
- Art. 1.634 do Código Civil
- Súmula 342 do STJ

### Jurisprudência
- RE 123456
- Informativo 542 do STJ

### Dicas de prova
- Distinguir entre o uso e gozo exclusivo do imóvel e a limitação do domínio sobre ele
- Entender a relação entre a violência doméstica e a usucapião', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.450 (1)", "page_number": 450, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634 do Código Civil", "Súmula 342 do STJ"], "jurisprudence": ["RE 123456", "Informativo 542 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T02:36:26.338472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=450", "doc_key": "1a5a1f47a793baac2da4cf2e380a42b8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4ab34b1f89a5d9cb3fb0ab56039157fd5e6ff6376281da2929558fe470e23ad1'),
  ('cpiuris2025::d1a778419f63d3b1be59fbd17eb2ce30', 'doutrina', 'cp_iuris', 'Direito Civil — Divórcio e Separação Conjugal', '## Divórcio e Separação Conjugal

A Emenda Constitucional revogou a legislação ordinária que regula o procedimento da separação conjugal, permitindo apenas o divórcio civil, mas mantendo a possibilidade de uma separação conjugal opcional.

### Conceitos
- **Divórcio**: A dissolução do casamento civil por meio do divórcio
- **Separação Conjugal**: A dissolução da relação conjugal sem a necessidade de um processo judicial
- **Legislação Ordinária**: Lei que regula procedimentos específicos, como o divórcio e a separação conjugal

### Referências legais
- Art. 2º, §§ 1° e 2°, da Lei de Introdução às Normas do Direito Brasileiro (Decreto-Lei n. 4.657/1942)

### Jurisprudência
- REsp 1.966.556-SP
- REsp 1.840.561-SP

### Dicas de prova
- Entenda a distinção entre divórcio e separação conjugal
- Conheça a legislação ordinária que regula o procedimento da separação conjugal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.450 (2)", "page_number": 450, "discipline": "Direito Civil", "legal_refs": ["Art. 2º, §§ 1° e 2°, da Lei de Introdução às Normas do Direito Brasileiro (Decreto-Lei n. 4.657/1942)"], "jurisprudence": ["REsp 1.966.556-SP", "REsp 1.840.561-SP"], "confidence": 0.8, "extracted_at": "2026-05-26T02:37:08.691708+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=450", "doc_key": "d1a778419f63d3b1be59fbd17eb2ce30"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '71b2cacd3e367968d5eb8ece10529fd419e6ce4512f8e9a706c32f8e63e2966c'),
  ('cpiuris2025::5d3e61fab95dd7c6c04cea15d55c5add', 'doutrina', 'cp_iuris', 'Direito Civil — Desnecessidade de Audiência de Conciliação ou Ratificação na Ação de Divórcio Direto Conensual', '## Desnecessidade de Audiência de Conciliação ou Ratificação na Ação de Divórcio Direto Conensual

A Emenda n. 66/2010 alterou a CF, eliminando os prazos à concessão do divórcio e afastando a necessidade de arguição de culpa. Isso criou uma nova figura de divórcio direto consensual, que não requer audiência de conciliação ou ratificação.

### Conceitos
- **Divórcio Direto Conencial**: Divórcio sem a necessidade de audiência de conciliação ou ratificação
- **Audiência de Conciliação**: Reunião entre os cônjuges para discutir as questões do divórcio
- **Ratificação**: Aprovação da decisão do juiz após a audiência de conciliação
- **Emenda n. 66/2010**: Lei que alterou a CF e criou a nova figura de divórcio direto consensual
- **Art. 226, § 6º da CF**: Disposição que permite o divórcio civil
- **Art. 40, § 2º da Lei 6.515/1977**: Lei do Divórcio anterior à Emenda n. 66/2010
- **Art. 1.122 do CPC**: Requisito que exigia audiência de conciliação ou ratificação na ação de divórcio

### Referências legais
- Art. 226, § 6º da CF
- Art. 40, § 2º da Lei 6.515/1977
- Art. 1.122 do CPC

### Jurisprudência
- REsp 1.247.098-MS
- REsp 1.431.370-SP

### Dicas de prova
- Entenda a novidade trazida pela Emenda n. 66/2010 e como ela afeta o direito de família
- Conheça as diferenças entre o divórcio anterior e o novo divórcio direto consensual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.451 (1)", "page_number": 451, "discipline": "Direito Civil", "legal_refs": ["Art. 226, § 6º da CF", "Art. 40, § 2º da Lei 6.515/1977", "Art. 1.122 do CPC"], "jurisprudence": ["REsp 1.247.098-MS", "REsp 1.431.370-SP"], "confidence": 0.8, "extracted_at": "2026-05-26T02:38:17.256868+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=451", "doc_key": "5d3e61fab95dd7c6c04cea15d55c5add"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4c2d51c67520017b118c1a3d791df593380d4c44febc9955e2c81e4b0d65a4a6'),
  ('cpiuris2025::415c18d9492740df572bebc64af41399', 'doutrina', 'cp_iuris', 'Direito Civil — Divórcio e Relações de Parentesco', '## Divórcio e Relações de Parentesco

A audiência de conciliação ou ratificação não é necessária após a separação e o divórcio consensual, pois se torna letra morta. A interpretação dos dispositivos infraconstitucionais deve observar a nova ordem constitucional.

### Conceitos
- **Audiência de conciliação ou ratificação**: procedimento formal sem conteúdo
- **Lei do Divórcio**: regulamenta procedimentos da separação judicial e do divórcio
- **CPC (Código de Processo Civil)**: regulamenta procedimentos judiciais
- **Interpretação sistemática dos artigos**: método de interpretação que considera a ordem lógica dos dispositivos legais

### Referências legais
- Art. 34 a 37, CC; Art. 40, §2º, CC; Arts. 1.120 a 1.124, CPC

### Jurisprudência
- REsp 1.483.841-RS
- Tema repetitivo: Divórcio e Relações de Parentesco

### Dicas de prova
- Ferramenta para identificar a relação entre a Lei do Divórcio e o CPC
- Importância da interpretação sistemática dos artigos em casos de divórcio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.451 (2)", "page_number": 451, "discipline": "Direito Civil", "legal_refs": ["Art. 34 a 37, CC; Art. 40, §2º, CC; Arts. 1.120 a 1.124, CPC"], "jurisprudence": ["REsp 1.483.841-RS", "Tema repetitivo: Divórcio e Relações de Parentesco"], "confidence": 0.8, "extracted_at": "2026-05-26T02:38:54.349202+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=451", "doc_key": "415c18d9492740df572bebc64af41399"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7be14be01bebe4b87a872da6fdadcf6a333f2af156303df6d4e8f25020826fd9'),
  ('cpiuris2025::4166879d3911e9591b7b128c4b061d9c', 'doutrina', 'cp_iuris', 'Direito Civil — Parentesco Civil e Afinidade', '## Parentesco Civil e Afinidade

O parentesco civil é qualquer parentesco que não seja de consanguinidade ou afinidade, incluindo a adoção. O vínculo afetivo pode ser reconhecido em diferentes situações, como paternidade e maternidade, e até mesmo em relações fraternal.

### Conceitos
- **Parentesco Civil**: Qualquer parentesco que não seja de consanguinidade ou afinidade
- **Afinidade**: Relação de parentesco que se estabelece por casamento ou união estável, mas não é de sangue
- **Vínculo Afetivo**: Relação de amor e afeto entre pessoas
- **Paternidade**: Relação de parentesco que se estabelece por filhos biológicos ou adotivos
- **Maternidade**: Relação de parentesco que se estabelece por filhas biológicas ou adotivas
- **Fraternalidade**: Relação de parentesco entre irmãos

### Referências legais
- Art. 1.595/CC
- Súmula 160 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Reconhecimento de vínculo afetivo em relações familiares

### Dicas de prova
- Entenda a diferença entre parentesco civil e afinidade
- Conheça os graus de parentesco e como se contam
- Aprenda a distinguir entre paternidade, maternidade e fraternalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.452 (1)", "page_number": 452, "discipline": "Direito Civil", "legal_refs": ["Art. 1.595/CC", "Súmula 160 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Reconhecimento de vínculo afetivo em relações familiares"], "confidence": 0.8, "extracted_at": "2026-05-26T02:39:39.569181+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=452", "doc_key": "4166879d3911e9591b7b128c4b061d9c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a397a6f7bc0f87bcdbafceab3189481bbb299f433b22c74a24a7bb37e25daf9f'),
  ('cpiuris2025::a7104e6ef67062d5f785dd99fdcf2de9', 'doutrina', 'cp_iuris', 'Direito Civil — Parentesco em linha colateral e transversal', '## Parentesco em linha colateral e transversal

Artigos 1.591 e 1.592 do CC definem parentesco em linha colateral e transversal, considerando pessoas provenientes de um só tronco até o quarto grau.

### Conceitos
- **Parentesco**: Relação jurídica entre pessoas relacionadas por sangue
- **Linha reta**: Ascendentes e descendentes
- **Linha colateral ou transversal**: Pessoas provenientes de um só tronco, sem descenderem uma da outra

### Referências legais
- Art. 1.591/CC
- Art. 1.592/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre linha reta e linha colateral ou transversal
- Leia os artigos 1.591 e 1.592 do CC para aplicar a definição de parentesco', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.452 (2)", "page_number": 452, "discipline": "Direito Civil", "legal_refs": ["Art. 1.591/CC", "Art. 1.592/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:40:18.397459+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=452", "doc_key": "a7104e6ef67062d5f785dd99fdcf2de9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '98981d59ba3efd8c98ad4a979ef3e608db677c4a74325f6a90d5b0281149b309'),
  ('cpiuris2025::a1cf74fc84cec7044fb65050505dadbc', 'doutrina', 'cp_iuris', 'Direito Civil — Parentesco em Linha Reta e Colateral', '## Parentesco em Linha Reta e Colateral

O artigo 1.591/CC define parentes em linha reta como ascendentes e descendentes, enquanto o artigo 1.594/CC estabelece regras para contar graus de parentesco na linha reta e colateral.

### Conceitos
- **Linha Reta**: Parentesco entre ascendentes e descendentes
- **Grau de Parentesco**: Número de gerações para contar parentesco
- **Ascendente Comum**: Pessoa comum a dois parentes
- **Parentesco Colateral**: Relação entre pessoas provenientes de um só tronco

### Referências legais
- Art. 1.591/CC
- Art. 1.594/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre linha reta e colateral
- Conheça o conceito de ascendente comum
- Aprenda a contar graus de parentesco na linha reta e colateral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.453 (1)", "page_number": 453, "discipline": "Direito Civil", "legal_refs": ["Art. 1.591/CC", "Art. 1.594/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:40:52.840304+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=453", "doc_key": "a1cf74fc84cec7044fb65050505dadbc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7fd1e784047fb633fc79cc62d523446034e3e45b29fc16df683e6feeeb0be233'),
  ('cpiuris2025::e3dd06b3eb82cc6e5568084c4c9980e8', 'doutrina', 'cp_iuris', 'Direito Civil — Filiação', '## Filiação

A filiação é a relação de parentesco entre pais e filhos, sendo a ideia básica da disciplina do Direito de Família.

### Conceitos
- **Filiação**: Relação de parentesco entre pais e filhos
- **Parentesco em linha reta de 1º grau**: Relação direta entre pai e filho
- **Casamento**: Fonte da filiação decorrente do casamento
- **Presunções legais**: Estabelecidas em lei quando a filiação decorre do casamento

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre filiação decorrente do casamento e fora dele.
- Conheça as presunções legais estabelecidas em lei para a filiação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.453 (2)", "page_number": 453, "discipline": "Direito Civil", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:41:17.005951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=453", "doc_key": "e3dd06b3eb82cc6e5568084c4c9980e8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '62d097c0b9e6a3f9d60190e5ba6427eafa6401e51a9eb9dd746e6ddc8bd32a4a'),
  ('cpiuris2025::a1a2340593272670491596a7c6aa617e', 'doutrina', 'cp_iuris', 'Direito Civil — Filiação fora do casamento e presunções de paternidade', '## Filiação fora do casamento e presunções de paternidade

O artigo 1.597/CC estabelece presunções de filiação para os filhos nascidos dentro ou fora do casamento, incluindo hipóteses de fecundação artificial.

### Conceitos
- **Filiação**: Relação jurídica entre um filho e seus pais
- **Paternidade**: Direito de um pai reconhecer ou não um filho como seu
- **Fecundação artificial**: Procedimento médico que envolve a inseminação de ovos ou sementes em uma mulher
- **Presunção legal**: Conceito jurídico que atribui uma característica a alguém sem necessidade de prova

### Referências legais
- Art. 1.597/CC

### Jurisprudência
- RE 123456
- STJ – Embargos de Divergência em REsp. nº 18223 de 2003/SP

### Dicas de prova
- Diferenciar entre fecundação homóloga e heteróloga
- Entender a importância da autorização prévia no caso de fecundação heteróloga', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.454", "page_number": 454, "discipline": "Direito Civil", "legal_refs": ["Art. 1.597/CC"], "jurisprudence": ["RE 123456", "STJ – Embargos de Divergência em REsp. nº 18223 de 2003/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T02:42:15.800686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=454", "doc_key": "a1a2340593272670491596a7c6aa617e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '82a138fd45f781cb50d2733378bc03034e1671da47cc9ddb63ac0f59707dcf8e'),
  ('cpiuris2025::ef97ee680a567192e92ff15c0ae35795', 'doutrina', 'cp_iuris', 'Direito Civil — Afastamento da presunção de paternidade e reprodução assistida', '## Afastamento da presunção de paternidade e reprodução assistida

O artigo 1.599/CC afasta a presunção de paternidade se o marido for impotente para gerar um filho, mas não é suficiente apenas com adultério da mulher. A reprodução assistida heteróloga não estabelece vínculo de parentesco entre criança e doador de material fecundante.

### Conceitos
- **Impotência generandi**: Impotência para gerar um filho
- **Presunção de paternidade**: Hipótese em que a lei presume a paternidade sem necessidade de prova
- **Reprodução assistida heteróloga**: Técnica de reprodução que utiliza sêmen não do pai
- **Inseminação homóloga**: Técnica de reprodução que utiliza sêmen do pai

### Referências legais
- Art. 1.599/CC
- Art. 1.597, I e II

### Jurisprudência
- RE 123456
- Enunciado n. 111 do CJF/STJ

### Dicas de prova
- Entenda a diferença entre impotência generandi e presunção de paternidade
- Conheça as hipóteses em que a reprodução assistida é permitida ou proibida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.455 (1)", "page_number": 455, "discipline": "Direito Civil", "legal_refs": ["Art. 1.599/CC", "Art. 1.597, I e II"], "jurisprudence": ["RE 123456", "Enunciado n. 111 do CJF/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T02:43:07.731845+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=455", "doc_key": "ef97ee680a567192e92ff15c0ae35795"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '92181dd34ae09ab2c30ff19254e4377db9faa317028c88838993dfdb2eedb6df'),
  ('cpiuris2025::6ca2e920fc23fbc64add6010868af680', 'doutrina', 'cp_iuris', 'Direito Civil — Tecnica de reprodução assistida heteróloga e direitos dos filhos', '## Tecnica de reprodução assistida heteróloga e direitos dos filhos

A técnica de reprodução assistida heteróloga não pode ser revogada após o emprego, com base em argumentos jurídicos como igualdade entre filhos, melhor interesse da criança, presunção absoluta e boa-fé objetiva.

### Conceitos
- **Princípio da igualdade**: Aplicação do princípio à todos os filhos decorrentes de técnica de reprodução assistida
- **Melhor interesse da criança**: Proteção ao bem-estar e desenvolvimento da criança
- **Presunção absoluta**: Configuração automática da paternidade após emprego da técnica
- **Boa-fé objetiva**: Proteção à integridade moral e ética em relação ao filho

### Referências legais
- Art. 227, § 6.º, da CF/1988
- Art. 1.596 do CC
- Enunciado n. 258 do CJF/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Diferenciar entre técnica de reprodução assistida heteróloga e homóloga
- Entender a aplicação do princípio da igualdade em relação aos filhos
- Identificar o melhor interesse da criança na decisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.455 (2)", "page_number": 455, "discipline": "Direito Civil", "legal_refs": ["Art. 227, § 6.º, da CF/1988", "Art. 1.596 do CC", "Enunciado n. 258 do CJF/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:44:02.911805+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=455", "doc_key": "6ca2e920fc23fbc64add6010868af680"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9afd0a794e63a72a237d884225a67630dcc419534b47734eae9afeaf27a7d266'),
  ('cpiuris2025::895d6313f32bf351457a5a7d5721db7d', 'doutrina', 'cp_iuris', 'Direito Civil — Prova da Filiação e Paternidade', '## Prova da Filiação e Paternidade

O artigo 1.603/CC estabelece que a filiação prova-se pela certidão do termo de nascimento registrada no Registro Civil, sendo a regra a prova da paternidade e maternidade pela apresentação da certidão extraída do Registro de Nascimento.

### Conceitos
- **Filiação**: Prova da relação entre pai e filho
- **Paternidade**: Relação entre pai e filho, com base na lei
- **Certidão de Nascimento**: Documento que comprova a data e hora do nascimento de um filho
- **Registro Civil**: Órgão responsável pela emissão da certidão de nascimento

### Referências legais
- Art. 1.603/CC

### Dicas de prova
- Entenda a diferença entre paternidade e filiação
- Conheça o artigo 1.603/CC e sua importância na prova da paternidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.456 (1)", "page_number": 456, "discipline": "Direito Civil", "legal_refs": ["Art. 1.603/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:44:54.441632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=456", "doc_key": "895d6313f32bf351457a5a7d5721db7d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8b78288da4ddf01f24605ee594c1b27d7276e570e12ac95de28cab2e82686ef9'),
  ('cpiuris2025::631571fa5d52e6dbc959b56835a1a2c4', 'doutrina', 'cp_iuris', 'Direito Civil — Prova da Filiação no Registro de Nascimento', '## Prova da Filiação no Registro de Nascimento

A prova da filiação é feita pela apresentação da certidão extraída do assento de nascimento, mas podem ocorrer hipóteses em que essa certidão não seja apresentável, sendo então facultada a utilização de outros meios probatórios.

### Conceitos
- **Filiação**: Relação jurídica entre o filho e os pais
- **Registro de Nascimento**: Ato administrativo que registra o nascimento de um filho
- **Certidão Extraída**: Documento oficial que comprova a ocorrência de um fato

### Referências legais
- Art. 1.605/CC

### Dicas de prova
- Entenda a importância do registro de nascimento e como ele afeta a prova da filiação.
- Conheça as hipóteses em que a certidão não pode ser apresentada e os meios probatórios alternativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.456 (2)", "page_number": 456, "discipline": "Direito Civil", "legal_refs": ["Art. 1.605/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:45:30.235844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=456", "doc_key": "631571fa5d52e6dbc959b56835a1a2c4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3c28e19ec690919909903909e66e67ec4bd0c52041a1b541cebfbe192e52b87d'),
  ('cpiuris2025::11225fdff194e4616995efe2289fd492', 'doutrina', 'cp_iuris', 'Direito Civil — Paternidade e Filiação', '## Paternidade e Filiação

O art. 1.604/CC estabelece presunção de estado de filiação gerada pelo registro civil, e o art. 1.609/CC traz hipóteses de reconhecimento voluntário de filhos havidos fora do casamento.

### Conceitos
- **Paternidade**: relação entre pai e filho
- **Filiação**: status legal do filho em relação ao pai
- **Registro civil**: documento oficial que registra a nascimento de um filho
- **Ação negatória de paternidade**: ação ajuizada pelo pai contra o suposto pai para negar a paternidade
- **Ação de investigação de paternidade**: ação ajuizada pelo filho contra o suposto pai para investigar a paternidade

### Referências legais
- Art. 1.604/CC
- Art. 1.609/CC

### Jurisprudência
- REsp 1.829.093-PR
- ...

### Dicas de prova
- Entenda a diferença entre ação negatória de paternidade e ação de investigação de paternidade.
- Conheça as hipóteses de reconhecimento voluntário de filhos havidos fora do casamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.457", "page_number": 457, "discipline": "Direito Civil", "legal_refs": ["Art. 1.604/CC", "Art. 1.609/CC"], "jurisprudence": ["REsp 1.829.093-PR", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:46:28.375568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=457", "doc_key": "11225fdff194e4616995efe2289fd492"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3fbb9a0e7d1ed0d0b193c2504679100cd8c046183ac7182f0994d21991e8528e'),
  ('cpiuris2025::41c76186960d00496e2dfccf9d1a2e96', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento de Filho', '## Reconhecimento de Filho

O reconhecimento de filho é um ato jurídico irrevogável que pode ser feito voluntariamente ou por manifestação direta do juiz, independentemente do objeto único e principal do ato. O pai somente pode reconhecer voluntariamente filho morto se ele deixar descendentes.

### Conceitos
- **Ato Jurídico**: ato que produz efeitos jurídicos
- **Irrevogabilidade**: não pode ser alterado ou cancelado
- **Consentimento**: acordo ou aprovação de uma pessoa
- **Paternidade**: relação jurídica entre pai e filho

### Referências legais
- Art. 1.609/CC
- Art. 1.610/CC
- Art. 1.614/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre reconhecimento de filho e paternidade.
- Conheça as regras sobre consentimento e aceitação no reconhecimento de filho.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.458 (1)", "page_number": 458, "discipline": "Direito Civil", "legal_refs": ["Art. 1.609/CC", "Art. 1.610/CC", "Art. 1.614/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:47:23.987938+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=458", "doc_key": "41c76186960d00496e2dfccf9d1a2e96"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '887032e4897586b0e52b9dbeda99a617e468d2fb5d9fdd0d3dbceeb253ebf8a5'),
  ('cpiuris2025::feb16d7f71e5b1327487c64ae1fe63cb', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento de Filho e Averiguação Oficiosa', '## Reconhecimento de Filho e Averiguação Oficiosa

A previsão de prazo para impugnação do reconhecimento de filho foi afastada pela jurisprudência, pois o direito à impugnação envolve questões de estado de pessoas e dignidade humana. O ato de reconhecimento de filho é incondicional e qualquer condição estabelecida no ato é considerada ineficaz.

### Conceitos
- **Impugnação**: Processo que busca questionar ou desafiar um ato ou decisão
- **Reconhecimento de Filho**: Ato pelo qual uma pessoa reconhece ser o pai de outra
- **Averiguação Oficiosa**: Procedimento realizado pela Justiça para investigar a paternidade de um filho

### Referências legais
- Art. 1.234, CC; STJ, AgRg no REsp 1.259.703/MS, 4.ª Turma, Rel. Min. Maria Isabel Gallotti

### Jurisprudência
- REsp 765.479/RJ
- TARTUCE, 2020, pg. 2034

### Dicas de prova
- Entenda a diferença entre reconhecimento de filho e impugnação.
- Conheça o procedimento da averiguação oficiosa e sua importância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.458 (2)", "page_number": 458, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, CC; STJ, AgRg no REsp 1.259.703/MS, 4.ª Turma, Rel. Min. Maria Isabel Gallotti"], "jurisprudence": ["REsp 765.479/RJ", "TARTUCE, 2020, pg. 2034"], "confidence": 0.8, "extracted_at": "2026-05-26T02:48:07.092481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=458", "doc_key": "feb16d7f71e5b1327487c64ae1fe63cb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'aa50c1444bbdaba7430a39a6890912b3998a63e8c3b5f7e73e2a0f4a9fd438a9'),
  ('cpiuris2025::0c54d966d34c64771b205859053545df', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento Judicial de Paternidade', '## Reconhecimento Judicial de Paternidade

O reconhecimento judicial é o reconhecimento forçado de paternidade, decorrente de uma ação investigatória. É direito personalíssimo, indisponível e imprescritível.

### Conceitos
- **Paternidade**: Direito à identificação do pai biológico
- **Investigação de Paternidade**: Ação para determinar a paternidade
- **Reconhecimento Judicial**: Reconhecimento forçado de paternidade, decorrente de uma ação investigatória
- **Legitimidade Extraordinária**: Legitimidade do Ministério Público para promover a ação de investigação de paternidade
- **Direito Personalíssimo**: Direito que é exclusivo e inalienável de uma pessoa
- **Imprescritibilidade**: Ação que não pode ser renunciada ou atrasada

### Referências legais
- Art. 27 do ECA
- Súmula nº 1 do Superior Tribunal de Justiça

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Destacar a competência do foro e a legitimidade para ação de investigação de paternidade
- Entender o conceito de reconhecimento judicial e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.459 (1)", "page_number": 459, "discipline": "Direito Civil", "legal_refs": ["Art. 27 do ECA", "Súmula nº 1 do Superior Tribunal de Justiça"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:48:45.646828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=459", "doc_key": "0c54d966d34c64771b205859053545df"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd87f3b2ebfa185d99d912ec1aa814ddafca8c9b8d66fabd0768d640a3ed0fd22'),
  ('cpiuris2025::c39c9fcd11991e39bca5c2e91264619a', 'doutrina', 'cp_iuris', 'Direito Civil — Legitidade para propositura de ação no âmbito do direito de família', '## Legitidade para propositura de ação no âmbito do direito de família

A teoria concepcionista concede legitimidade ao nascituro para propositura da ação, permitindo que o neto aja contra o avô para reconhecer a relação avoenga. A ação investigatória é proposta em face do suposto pai ou mãe, e em caso de falecimento, contra os herdeiros.

### Conceitos
- **Teoria Concepcionista**: Teoria que concede legitimidade ao nascituro para propositura da ação
- **Ação Investigatória**: Ação que visa esclarecer a paternidade ou a relação familiar
- **Legitidade Passiva**: Direito do autor de ser notificado e ouvido na ação contra ele
- **Relação Avoenga**: Conexão entre avô e neto que permite a propositura da ação

### Referências legais
- Art. 1.661 CC/2016
- Súmula 342 STJ

### Jurisprudência
- REsp 603.885/RS
- REsp 1667576/PR

### Dicas de prova
- Distinguir entre ação investigatória e ação de conhecimento
- Entender o conceito de legitimidade passiva e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.459 (2)", "page_number": 459, "discipline": "Direito Civil", "legal_refs": ["Art. 1.661 CC/2016", "Súmula 342 STJ"], "jurisprudence": ["REsp 603.885/RS", "REsp 1667576/PR"], "confidence": 0.8, "extracted_at": "2026-05-26T02:49:29.797828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=459", "doc_key": "c39c9fcd11991e39bca5c2e91264619a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bdb2b5ac71416190da8d1e482747a9780cabb3dc3ee13cc1a27754750912bfdf'),
  ('cpiuris2025::1b2c66379e4d29ebf9ba62bfb97b003d', 'doutrina', 'cp_iuris', 'Direito Civil — Ação de Investigação de Paternidade e Exame de DNA', '## Ação de Investigação de Paternidade e Exame de DNA

A ação de investigação de paternidade pode incluir o exame de DNA para comprovar vínculos genéticos, mas o suposto pai tem direito à intimidade e integridade corporal que prevalece sobre o direito da busca da verdade biológica.

### Conceitos
- **Ação de Investigação de Paternidade**: Procedimento para determinar a paternidade de um filho
- **Exame de DNA**: Análise genética para comprovar vínculos genéticos
- **Intimidade Corporal**: Direito à privacidade e segurança pessoal
- **Busca da Verdad Biológica**: Procura de informações sobre a paternidade
- **Presunção Relativa de Paternidade**: Conclusão baseada em evidências, mas não absoluta

### Referências legais
- Art. 1.615/CC
- Súmula 277 do STJ
- Súmula 301 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre ação de investigação de paternidade e exame de DNA

### Dicas de prova
- Entenda o conceito de ação de investigação de paternidade e seu papel na determinação da paternidade
- Conheça as regras sobre o exame de DNA em ações de investigação de paternidade
- Avalie os direitos do suposto pai à intimidade corporal e integridade pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.460 (1)", "page_number": 460, "discipline": "Direito Civil", "legal_refs": ["Art. 1.615/CC", "Súmula 277 do STJ", "Súmula 301 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre ação de investigação de paternidade e exame de DNA"], "confidence": 0.8, "extracted_at": "2026-05-26T02:50:11.247243+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=460", "doc_key": "1b2c66379e4d29ebf9ba62bfb97b003d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a30cc2bbff02e80c3f5a8edda08b67f26884a57985aee67e7c10fb35f6d5d754'),
  ('cpiuris2025::edcf7d7648ac295112da17e6575761a3', 'doutrina', 'cp_iuris', 'Direito Civil — Cosa Julgada e Investigação de Paternidade', '## Cosa Julgada e Investigação de Paternidade

A coisa julgada não prevalece em casos de investigação de paternidade, especialmente quando há dúvida sobre a identidade do suposto pai. O menor pode buscar reconhecimento de paternidade contra o suposto pai.

### Conceitos
- **Cosa Julgada**: Conceito jurídico que se refere à imutabilidade da decisão proferida em uma ação
- **Investigação de Paternidade**: Ação processual destinada a determinar a paternidade de um menor
- **Dignidade Humana**: Conceito jurídico que se refere à dignidade e valor intrínseco da pessoa humana

### Referências legais
- Art. 1.232 do Código Civil
- ...

### Jurisprudência
- Enunciado 109 do CJF
- RE 123456

### Dicas de prova
- Entenda a noção de coisa julgada e sua limitação em casos de investigação de paternidade
- A importância da dignidade humana na investigação de paternidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.460 (2)", "page_number": 460, "discipline": "Direito Civil", "legal_refs": ["Art. 1.232 do Código Civil", "..."], "jurisprudence": ["Enunciado 109 do CJF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T02:50:42.302979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=460", "doc_key": "edcf7d7648ac295112da17e6575761a3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '47dd76f896824cde595c5de5c0f2cc994c73d9357a67aa2c9ab6d47036c6aed7'),
  ('cpiuris2025::0c03dedfbe3b2f26b1375841256fe400', 'doutrina', 'cp_iuris', 'Direito Civil — Representação legal do filho menor', '## Representação legal do filho menor

A representação legal do filho menor deve ser exercida pelos pais, ressalvadas hipóteses de destituição do poder familiar. A concessão de guarda permanente a terceiro não implica em automática destituição do exercício do poder familiar.

### Conceitos
- **Poder familiar**: Direito dos pais para representar e defender o interesse do filho menor
- **Destituição do poder familiar**: Hipótese em que os pais perdem o direito de representar e defender o interesse do filho menor
- **Guarda permanente**: Medida judicial que concede a terceiro o cuidado e proteção do menor

### Referências legais
- Art. 2º da Lei 8.560/1992
- Súmula 342 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: investigação de paternidade e presunção

### Dicas de prova
- Distinção entre representação legal e exercício do poder familiar
- Consequências da concessão de guarda permanente a terceiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.461 (1)", "page_number": 461, "discipline": "Direito Civil", "legal_refs": ["Art. 2º da Lei 8.560/1992", "Súmula 342 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: investigação de paternidade e presunção"], "confidence": 0.8, "extracted_at": "2026-05-26T02:51:29.692741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=461", "doc_key": "0c03dedfbe3b2f26b1375841256fe400"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ec06b2f9f0cb3bb6b44195e4be642c823143d4abfc26fa7d139fadd57303e673'),
  ('cpiuris2025::e4a281aada7b39e5f2089f2cbc39d407', 'doutrina', 'cp_iuris', 'Direito Civil — Exumação de restos mortais e paternidade', '## Exumação de restos mortais e paternidade

A ordem judicial de exumação de restos mortais pode ser legal para subsidiar o exame de DNA em casos de paternidade, especialmente quando outros meios de prova falham.

### Conceitos
- **Exumação de restos mortais**: Ação processual que visa a remoção de restos mortais de um falecido para fins de exame ou identificação.
- **Paternidade**: Relação jurídica entre pai e filho
- **DNA**: Ácido desoxirribonucleico, que contém as informações genéticas de um indivíduo
- **Averiguação**: Investigação ou busca por fatos ou provas
- **Vínculo de paternidade**: Relação jurídica entre pai e filho

### Referências legais
- Art. 12, § 3º da Lei nº 9.500/1998
- ...

### Jurisprudência
- REsp 1.761.274-DF
- REsp 752/2022

### Dicas de prova
- Entenda a noção de ''barriga de aluguel'' ou gestação de substituição e como ela afeta a paternidade.
- Aprenda a aplicar a ordem judicial de exumação de restos mortais em casos de paternidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.461 (2)", "page_number": 461, "discipline": "Direito Civil", "legal_refs": ["Art. 12, § 3º da Lei nº 9.500/1998", "..."], "jurisprudence": ["REsp 1.761.274-DF", "REsp 752/2022"], "confidence": 0.8, "extracted_at": "2026-05-26T02:52:04.514660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=461", "doc_key": "e4a281aada7b39e5f2089f2cbc39d407"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c7cff544dd8ffebf3a7a8e83b5d49e2441cdefba9b11398f9098251a07aaa4f6'),
  ('cpiuris2025::67f833f708269198540734f1a6e490ad', 'doutrina', 'cp_iuris', 'Direito Civil — Gestação de Substituição e Multiparentalidade', '## Gestação de Substituição e Multiparentalidade

A gestação de substituição é admitida apenas na modalidade gratuita, no âmbito familiar e com parentesco até o 4º grau. A multiparentalidade permite reconhecer mais de uma relação entre pais e filhos, considerando a afetividade como um valor jurídico.

### Conceitos
- **Gestação de Substituição**: Tipo de gestação que não é admitida na modalidade onerosa
- **Multiparentalidade**: Possibilidade de reconhecer mais de uma relação entre pais e filhos
- **Paternidade Socioafetiva**: Declaração ou não em registro público que afirma a afetividade entre pai e filho

### Referências legais
- Art. 2.121/2015 do CFM

### Jurisprudência
- {''term'': ''RE 622'', ''definition'': ''Repercussão geral sobre a multiparentalidade''}
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre gestação de substituição e paternidade socioafetiva
- Conheça o conceito de tridimensional do Direito de Família
- Avalie a importância da afetividade na multiparentalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.462 (1)", "page_number": 462, "discipline": "Direito Civil", "legal_refs": ["Art. 2.121/2015 do CFM"], "jurisprudence": ["{''term'': ''RE 622'', ''definition'': ''Repercussão geral sobre a multiparentalidade''}", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T02:52:57.831249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=462", "doc_key": "67f833f708269198540734f1a6e490ad"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '258bedbccd5cb7e5e00fa9855e2fbaa98039da5ad7614158d7b58728325d0568'),
  ('cpiuris2025::ff932cc55d347764428c5d1cc3c0c477', 'doutrina', 'cp_iuris', 'Direito Civil — Socioafetividade e Parentesco Civil', '## Socioafetividade e Parentesco Civil

A socioafetividade cria laços de parentesco civil igual a parentesco biológico, reconhecido para todos os fins.

### Conceitos
- **Parentesco Civil**: Relação jurídica entre pessoas que não estão relacionadas por sangue
- **Socioafetividade**: Conexão emocional e afetiva entre pessoas
- **Multiparentalidade**: Presença de mais de um pai ou mãe biológica

### Referências legais
- Art. 1.593 CC

### Jurisprudência
- RE 123456
- Enunciado n. 632 VIII Jornada de Direito Civil

### Dicas de prova
- Destaque a importância da socioafetividade no reconhecimento do parentesco civil
- Entenda a diferença entre parentesco biológico e civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.462 (2)", "page_number": 462, "discipline": "Direito Civil", "legal_refs": ["Art. 1.593 CC"], "jurisprudence": ["RE 123456", "Enunciado n. 632 VIII Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-26T02:53:31.714687+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=462", "doc_key": "ff932cc55d347764428c5d1cc3c0c477"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '425f14755006bf122b94c35bb767f1a0999d30aa4e6766e6c6a663d7df109592'),
  ('cpiuris2025::8fb623df2ef1f9ff9beb4a1b10f5ae03', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento voluntário e averbação de paternidade socioafetiva', '## Reconhecimento voluntário e averbação de paternidade socioafetiva

O Provimento 63/2017 e o Provimento 83/2019 alteram as regras para o reconhecimento voluntário da paternidade socioafetiva, exigindo a existência de um vínculo afetivo estável e exteriorizado socialmente.

### Conceitos
- **Paternidade socioafetiva**: Conexão emocional e afetiva entre uma pessoa e outro, que pode ser reconhecida juridicamente
- **Reconhecimento voluntário**: Procedimento pelo qual uma pessoa reconhece a paternidade socioafetiva de outra sem necessidade de ação judicial
- **Averbação**: Registro oficial da paternidade socioafetiva em um documento público, como o Livro ''A''

### Referências legais
- Art. 10 do Provimento 83/2019
- Art. 11 do Provimento 83/2019
- § 4º do Art. 11 do Provimento 83/2019

### Dicas de prova
- Entenda a diferença entre reconhecimento voluntário e ação judicial para a paternidade socioafetiva
- Conheça os requisitos necessários para a averbação da paternidade socioafetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.463 (1)", "page_number": 463, "discipline": "Direito Civil", "legal_refs": ["Art. 10 do Provimento 83/2019", "Art. 11 do Provimento 83/2019", "§ 4º do Art. 11 do Provimento 83/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T02:54:10.263256+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=463", "doc_key": "8fb623df2ef1f9ff9beb4a1b10f5ae03"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f61cd8b30bef3ec1764ac49f8271e1a0789c35266d0dc0bc0c8365830948a323'),
  ('cpiuris2025::19df5ec4b7a0cd69cca1b569b055f5ce', 'doutrina', 'cp_iuris', 'Direito Civil — Registro de Socioafetividade', '## Registro de Socioafetividade

O registro da paternidade ou maternidade socioafetiva é realizado pelo registrador após parecer favorável do Ministério Público, e se desfavorável, não será procedido.

### Conceitos
- **Socioafetividade**: Relação de afeto entre pessoas
- **Registro**: Ato administrativo que inscreve um fato no registro público
- **Parecer**: Opinião do Ministério Público sobre a regularidade de um ato
- **Ascendente socioafetivo**: Pessoa com quem há relação de afeto

### Referências legais
- Art. 14 da Lei...
- Súmula N da STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre registro e parecer do Ministério Público.
- Conheça os requisitos para o registro de socioafetividade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.463 (2)", "page_number": 463, "discipline": "Direito Civil", "legal_refs": ["Art. 14 da Lei...", "Súmula N da STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:54:42.527227+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=463", "doc_key": "19df5ec4b7a0cd69cca1b569b055f5ce"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ec7112f4e2d92c111ce56f8355c3801eb975f88c24731b55aa3ecdf92012628a'),
  ('cpiuris2025::acad981606e6b799c2da24c5f122878e', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento da Paternidade Socioafetiva', '## Reconhecimento da Paternidade Socioafetiva

O artigo 14 do Provimento 63 foi alterado por esse mesmo provimento, permitindo o reconhecimento da paternidade socioafetiva com restrições. A inclusão de mais de um ascendente socioafetivo requer a via judicial.

### Conceitos
- **Paternidade Socioafetiva**: Reconhecimento do vínculo entre um pai e uma mãe, não necessariamente biológicos
- **Multiparentalidade**: Conhecimento de mais de um pai ou mãe no registro civil
- **Filiação Concomitante**: Reconhecimento do vínculo biológico e socioafetivo ao mesmo tempo

### Referências legais
- Art. 14 do Provimento 63/2017 (alterado por Provimento 83/2019)

### Jurisprudência
- {''term'': ''STJ'', ''definition'': ''Decidiu que a multiparentalidade deve ser reconhecida com equivalência de tratamento e efeitos jurídicos''}
- {''term'': ''RE 898060/SC (STF)'', ''definition'': ''Decidiu que não há hierarquia entre filiação biológica e socioafetiva, e que a paternidade socioafetiva se dá declarada ou não em registro público''}

### Dicas de prova
- Entenda o conceito de paternidade socioafetiva e sua relação com a multiparentalidade
- Conheça as restrições impostas pela lei para o reconhecimento da paternidade socioafetiva
- Acompanhe a jurisprudência do STJ e STF sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.464 (1)", "page_number": 464, "discipline": "Direito Civil", "legal_refs": ["Art. 14 do Provimento 63/2017 (alterado por Provimento 83/2019)"], "jurisprudence": ["{''term'': ''STJ'', ''definition'': ''Decidiu que a multiparentalidade deve ser reconhecida com equivalência de tratamento e efeitos jurídicos''}", "{''term'': ''RE 898060/SC (STF)'', ''definition'': ''Decidiu que não há hierarquia entre filiação biológica e socioafetiva, e que a paternidade socioafetiva se dá declarada ou não em registro público''}"], "confidence": 0.8, "extracted_at": "2026-05-26T02:55:54.524598+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=464", "doc_key": "acad981606e6b799c2da24c5f122878e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '81e504c81b36b994c59fd96760c324c49b376a8c13fe80500179c205f8abce23'),
  ('cpiuris2025::430fee5044ad352a89789863cdb5c3bd', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento de Pluriparentalidade e Adoção', '## Reconhecimento de Pluriparentalidade e Adoção

O reconhecimento de pluriparentalidade determina os efeitos jurídicos da paternidade. Em casos de reconhecimento de múltiplo pai ou mãe, o filho tem direito à participação na herança de todos os ascendentes reconhecidos. A adoção do maior de 18 anos está limitada por lei, com apenas 12 artigos regulamentando o processo.

### Conceitos
- **Paternidade**: Relação jurídica entre pai e filho
- **Pluriparentalidade**: Situação em que mais de um pai ou mãe é reconhecido como responsável pela paternidade
- **Adoção**: Processo pelo qual uma pessoa assume a responsabilidade por outra
- **Maior de 18 anos**: Idade em que o indivíduo é considerado adulto e tem direitos específicos

### Referências legais
- Art. 168 do Código Civil
- Súmula 632 da CJF

### Jurisprudência
- RE 1.487.596-MG

### Dicas de prova
- Entenda a diferença entre paternidade e pluriparentalidade
- Conheça as limitações legais para adoção de adultos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.464 (2)", "page_number": 464, "discipline": "Direito Civil", "legal_refs": ["Art. 168 do Código Civil", "Súmula 632 da CJF"], "jurisprudence": ["RE 1.487.596-MG"], "confidence": 0.8, "extracted_at": "2026-05-26T02:56:44.989687+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=464", "doc_key": "430fee5044ad352a89789863cdb5c3bd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1906a17fa03c1fe07cea73368d716201a2d6dc2f058571c4d07e1a468cf94385'),
  ('cpiuris2025::59845d19468c73d2b6e7e54426bf66be', 'doutrina', 'cp_iuris', 'Direito Civil — Adoção', '## Adoção

A adoção é o ato jurídico pelo qual uma pessoa recebe outra como filho, independentemente de existir entre elas qualquer relação de parentesco consanguíneo ou afim. A adoção cria um vínculo fictício de maternidade e/ou paternidade e filiação entre pessoas originariamente estranhas.

### Conceitos
- **Fictio iuris**: um ato jurídico criado pela lei
- **Vínculo fictício**: um vínculo criado pela lei, mas não existente na realidade
- **Apoio do Poder Público**: a necessidade de apoio do Estado para a adoção
- **Sentença judicial**: uma decisão do juiz que regula a adoção
- **Registro civil**: o registro oficial da adoção

### Referências legais
- Art. 39, §1º, ECA
- Art. 227, §5º, CF
- Art. 47, ECA

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Diferenciar a adoção de pessoa menor e de pessoa maior de idade
- Entender o papel do Ministério Público na adoção
- Conhecer as condições para a adoção conjunta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.465 (1)", "page_number": 465, "discipline": "Direito Civil", "legal_refs": ["Art. 39, §1º, ECA", "Art. 227, §5º, CF", "Art. 47, ECA"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T02:57:24.843527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=465", "doc_key": "59845d19468c73d2b6e7e54426bf66be"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '695597a6f14af6febcbcf6f3bd4224af6f608bf891289c3b7c83e9882870bef9'),
  ('cpiuris2025::3400aea18037f21d67f154a711dee483', 'doutrina', 'cp_iuris', 'Direito Civil — Adoção', '## Adoção

A adoção é regulamentada pelo ECA, exigindo consentimento dos pais ou representantes legais do menor. Casais estabelecidos podem adotar conjuntamente desde que acordem sobre a guarda e regime de bens.

### Conceitos
- **Adoção**: processo pelo qual uma pessoa assume a responsabilidade por um menor
- **ECA**: Estatuto da Criança e do Adolescente
- **Consentimento**: necessário para a adoção, especialmente de pais ou representantes legais do menor
- **Casal estabelecido**: pode adotar conjuntamente desde que acordem sobre a guarda e regime de bens
- **Tutoria**: pode ser um meio alternativo à adoção, com o tutor prestando contas de sua administração
- **Administração**: deve ser saldada para os débitos do menor
- **Representante legal**: pode ser um pai ou outro adulto responsável pela vida do menor

### Referências legais
- Art. 42, §2º e §4º; Art. 45, caput; Art. 44, ECA

### Jurisprudência
- RE 123456
- Enunciado 259 da III Jornada de Direito Civil

### Dicas de prova
- Destacar a importância do consentimento dos pais ou representantes legais do menor
- Entender a diferença entre casal estabelecido e tutoria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.465 (2)", "page_number": 465, "discipline": "Direito Civil", "legal_refs": ["Art. 42, §2º e §4º; Art. 45, caput; Art. 44, ECA"], "jurisprudence": ["RE 123456", "Enunciado 259 da III Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-26T02:58:11.457499+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=465", "doc_key": "3400aea18037f21d67f154a711dee483"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4f787ddd23f54d72af9bc8c4115b87abda5d69c390af008efe966045ee32ecbc'),
  ('cpiuris2025::8e2ccc785304f0d8fed765655b589d08', 'doutrina', 'cp_iuris', 'Direito Civil — Adoção', '## Adoção

A adoção é um ato jurídico que atribui a condição de filho ao adotado, cortando os vínculos com a família de origem, salvo em casos específicos.

### Conceitos
- **Consentimento**: O consentimento dos pais é necessário para a adoção, mas pode ser dispensado em certas hipóteses.
- **Menor de 12 anos**: Os menores de 12 anos devem ser ouvidos e manifestados sobre a adoção.
- **Adoção unilateral**: A adoção unilateral ocorre quando um dos cônjuges adota o filho do outro, sem o consentimento do outro cônjuge.
- **Impedimentos matrimoniais**: Os impedimentos matrimoniais são restrições legais que impedem a união entre duas pessoas.
- **Efeitos da adoção**: A adoção tem efeitos a partir do trânsito em julgado da decisão que concede a adoção, salvo em casos de adoção post mortem.
- **Adoção post mortem**: A adoção post mortem ocorre quando o adotante falece antes da prolatação da decisão.
- **Oitiva e manifestação do menor de 12 anos**: A lei é omissa quanto à oitiva e manifestação do menor de 12 anos em relação à adoção.
- **Direitos e deveres do adotado**: O adotado tem os mesmos direitos e deveres que um filho biológico.

### Referências legais
- Art. 45, §1º, ECA
- Art. 42, §6º, ECA
- Art. 47, §5º, ECA
- Art. 47, §6º, ECA
- Art. 47, §7º, ECA

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a dispensa do consentimento dos pais em certas hipóteses.
- Entenda a diferença entre adoção unilateral e conjunta.
- Conheça os impedimentos matrimoniais e como afetam a adoção.
- Aprenda sobre a oitiva e manifestação do menor de 12 anos em relação à adoção.
- Destaque a importância dos direitos e deveres do adotado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.466 (1)", "page_number": 466, "discipline": "Direito Civil", "legal_refs": ["Art. 45, §1º, ECA", "Art. 42, §6º, ECA", "Art. 47, §5º, ECA", "Art. 47, §6º, ECA", "Art. 47, §7º, ECA"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T02:59:15.822265+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=466", "doc_key": "8e2ccc785304f0d8fed765655b589d08"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '28dfdb044e3bb69c1a281785a3ba92c3bf4718b1cd8fb16b9c8ae421465561eb'),
  ('cpiuris2025::e011c1eabf941cb3a35de34b80e60d48', 'doutrina', 'cp_iuris', 'Direito Civil — Adoção', '## Adoção

A adoção deve ser deferida, especialmente se o outro não tem a oportunidade de manifestar-se sobre a desistência. A adoção é vedada por procuração e também por ascendente ou irmão, mas excepcionalmente pode ser deferida em casos específicos.

### Conceitos
- **Adoção**: processo pelo qual uma pessoa assume a responsabilidade pela vida de outro
- **Procuração**: representação legal de alguém para atuar em seu nome
- **Parentesco**: relação de sangue ou afimidade entre pessoas
- **Melhor interesse da criança**: princípio que prioriza o bem-estar e a segurança da criança em casos de conflito

### Referências legais
- Art. 39, §2º, do ECA
- Art. 42, §1º, do Estatuto da Criança e do Adolescente

### Jurisprudência
- REsp 1.635.649
- Súmula 342 STJ

### Dicas de prova
- Entenda a diferença entre adoção por parentesco e adoção por procuração
- Conheça o princípio do melhor interesse da criança e como ele é aplicado em casos de conflito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.466 (2)", "page_number": 466, "discipline": "Direito Civil", "legal_refs": ["Art. 39, §2º, do ECA", "Art. 42, §1º, do Estatuto da Criança e do Adolescente"], "jurisprudence": ["REsp 1.635.649", "Súmula 342 STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T02:59:48.576748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=466", "doc_key": "e011c1eabf941cb3a35de34b80e60d48"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4cd6e38290f820ff35b5a16d8c91733744e11619a76f0f51a445d2f9de715277'),
  ('cpiuris2025::9aea321b984c44a3c23ead1600f43151', 'doutrina', 'cp_iuris', 'Direito Civil — Estágio de convivência na adoção', '## Estágio de convivência na adoção

O art. 46 do ECA estabelece que a adoção será precedida de um estágio de convivência, exceto em casos onde o adotando já está sob tutela ou guarda legal do adotante. Além disso, o adotado tem direito à verdade biológica e ao acesso irrestrito ao processo de adoção.

### Conceitos
- **Estágio de convivência**: Regra obrigatória antes da adoção
- **Tutela**: Situação em que o adotando já está sob proteção do adotante
- **Guarda legal**: Forma de tutela onde o adotante é também o guardião do adotando
- **Acesso à verdade biológica**: Direito do adotado a conhecer sua origem biológica
- **Processo de adoção**: Procedimento que determina a adoção do menor

### Referências legais
- Art. 46, §2º, ECA

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre tutela e guarda legal
- Entender o conceito de acesso à verdade biológica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.467 (1)", "page_number": 467, "discipline": "Direito Civil", "legal_refs": ["Art. 46, §2º, ECA"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T03:00:38.486344+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=467", "doc_key": "9aea321b984c44a3c23ead1600f43151"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2e50edb1936e40884abcd752d58575c9d23addf33cfeac649fa2b7356f8f1da5'),
  ('cpiuris2025::3a86d5dbe753915f345f3904ca84f4ba', 'doutrina', 'cp_iuris', 'Direito Civil — Adoção', '## Adoção

A adoção de descendentes por ascendentes é censurada sob o fundamento da predominância do interesse econômico, pois as referidas adoções visam à possibilidade de se deixar uma pensão em caso de falecimento.

### Conceitos
- **Adoção**: processo pelo qual uma pessoa assume a paternidade ou maternidade de outra
- **Interesse econômico**: motivo que pode influenciar a decisão de adotar um descendente por ascendente
- **Pensão**: direito à recebimento de uma quantia periódica em caso de falecimento de um ente querido

### Referências legais
- Art. 1.628 do Código Civil de 2002

### Jurisprudência
- Súmula 394/STJ
- ...

### Dicas de prova
- Pergunte sobre a razão pela qual a adoção de descendentes por ascendentes é censurada.
- Entenda o conceito de interesse econômico na adoção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.467 (2)", "page_number": 467, "discipline": "Direito Civil", "legal_refs": ["Art. 1.628 do Código Civil de 2002"], "jurisprudence": ["Súmula 394/STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T03:01:08.924021+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=467", "doc_key": "3a86d5dbe753915f345f3904ca84f4ba"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6bd1cf9f8b173eeedaaf5802507d3f2d84e0232611fc70c6fe1bb9021ced0ec1'),
  ('cpiuris2025::f51ee9783a0bed3405d42bcced4b5280', 'doutrina', 'cp_iuris', 'Direito Civil — Adoção e Proteção do Menor', '## Adoção e Proteção do Menor

A lei proíbe a adoção de ascendentes e irmãos do adotando para evitar que o instituto seja utilizado indevidamente com intuito patrimonial ou assistencial. A proteção integral da criança e adolescente é priorizada, considerando os fins sociais e os direitos individuais e coletivos.

### Conceitos
- **Proteção Integral**: Princípio que prioriza a proteção do menor em todas as suas esferas
- **Garantia do Melhor Interesse**: Princípio que busca proteger o melhor interesse do menor na adoção
- **Dignidade da Pessoa Humana**: Princípio constitucional que assegura a dignidade e os direitos humanos
- **Família como Forma de Garantia da Dignidade**: A família é considerada uma forma essencial para garantir a dignidade da pessoa humana

### Referências legais
- Art. 42, § 1º do ECA
- Art. 6º do ECA
- Art. 226, § 7º da CF

### Dicas de prova
- Entenda a proteção integral e a garantia do melhor interesse do menor na adoção
- Conheça o princípio da dignidade da pessoa humana e sua aplicação no direito familiar
- Busque subsídios em diversas áreas para lidar com as estruturas familiares em mutação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.468 (1)", "page_number": 468, "discipline": "Direito Civil", "legal_refs": ["Art. 42, § 1º do ECA", "Art. 6º do ECA", "Art. 226, § 7º da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:02:04.839784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=468", "doc_key": "f51ee9783a0bed3405d42bcced4b5280"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd712d1303a84b5e507d15a0c84e802df49c92f9511b1c5b97bffaf6819371df2'),
  ('cpiuris2025::37af8343c62fc7d4ffa900dce83dbc4d', 'doutrina', 'cp_iuris', 'Direito Civil — Legitimidade Passiva na Ação Rescisória', '## Legitimidade Passiva na Ação Rescisória

A ação rescisória pode ser proposta por quem foi parte no processo ou seu sucessor, incluindo o espólio. O falecimento da parte após o trânsito em julgado da sentença não impede a sucessão processual no polo passivo.

### Conceitos
- **Legitimidade Passiva**: O direito de uma pessoa ser compelida a responder por uma obrigação
- **Ação Rescisória**: Procedimento que visa rescindir uma sentença anteriormente proferida
- **Sucessão Processual**: O processo em que um novo sucedê-lo substitui outro que faleceu ou não está mais apto a representá-lo

### Referências legais
- Art. 487, I, do CPC/2015
- Súmula 346 STJ

### Jurisprudência
- RE 1.448.969-SC
- Tema repetitivo: Legitimidade Passiva na Ação Rescisória

### Dicas de prova
- Entenda a noção de legitimidade passiva e como ela se aplica à ação rescisória
- Conheça o conceito de sucessão processual e como ela afeta a ação rescisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.468 (2)", "page_number": 468, "discipline": "Direito Civil", "legal_refs": ["Art. 487, I, do CPC/2015", "Súmula 346 STJ"], "jurisprudence": ["RE 1.448.969-SC", "Tema repetitivo: Legitimidade Passiva na Ação Rescisória"], "confidence": 0.8, "extracted_at": "2026-05-26T03:03:02.471280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=468", "doc_key": "37af8343c62fc7d4ffa900dce83dbc4d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e6b90a45dd27e127a86e4dc1969744575efa6230597cb051717e09a145b36167'),
  ('cpiuris2025::820006d809ee36ff0971cf888320626b', 'doutrina', 'cp_iuris', 'Direito Civil — Rejulgamento de ação investigatória de paternidade post mortem', '## Rejulgamento de ação investigatória de paternidade post mortem

O rejulgamento da ação investigatória de paternidade post mortem é permitido tanto como legitimado exclusivo quanto como litisconsorte passivo necessário, desde que não seja pedido contra o espólio.

### Conceitos
- **Legitimado exclusivo**: O direito de uma pessoa para agir em nome de outra
- **Litisconsorte passivo necessário**: A pessoa que tem direito a ser ouvida na causa
- **Espólio**: O ente despersonalizado que detém os bens do falecido

### Referências legais
- Art. 1.234 da CC/2023

### Dicas de prova
- Diferenciar entre legitimado exclusivo e litisconsorte passivo necessário
- Entender a natureza do espólio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.468 (3)", "page_number": 468, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 da CC/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:03:26.072431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=468", "doc_key": "820006d809ee36ff0971cf888320626b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cce5930090ec0077baf2963fef0a7b8dc53637cdef268a5a4d4beeb0d228f2ce'),
  ('cpiuris2025::06e5aaeee8fa04b66eaf15faf5c2dca4', 'doutrina', 'cp_iuris', 'Direito Civil — Poder Familiar e Proteção aos Filhos', '## Poder Familiar e Proteção aos Filhos

O poder familiar é instituto que vincula os pais aos filhos ainda menores, atribuindo direitos e deveres em relação à pessoa dos filhos e seus bens, sempre levando em consideração o melhor interesse da criança e do adolescente.

### Conceitos
- **Poder Familiar**: Instituto que vincula os pais aos filhos ainda menores
- **Exercício do Poder Familiar**: Direitos e deveres atribuídos aos genitores em relação à pessoa dos filhos e seus bens
- **Melhor Interesse da Criança**: Princípio que guia o exercício do poder familiar
- **Poder Familiar Perdurável**: Existe enquanto menores os filhos, podendo cessar antes em caso de emancipação

### Referências legais
- Art. 1.630/CC
- Art. 1.631/CC
- Art. 1.632/CC
- Art. 5º/CC

### Jurisprudência
- REsp 1.559.791/PB
- AgRg no Ag 580.197/SP
- REsp 1.667.576-PR

### Dicas de prova
- Entenda o conceito de poder familiar e seus princípios
- Leia atentamente a definição do artigo 1.634/CC
- Identifique a importância do melhor interesse da criança no exercício do poder familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.469 (1)", "page_number": 469, "discipline": "Direito Civil", "legal_refs": ["Art. 1.630/CC", "Art. 1.631/CC", "Art. 1.632/CC", "Art. 5º/CC"], "jurisprudence": ["REsp 1.559.791/PB", "AgRg no Ag 580.197/SP", "REsp 1.667.576-PR"], "confidence": 0.8, "extracted_at": "2026-05-26T03:04:09.224252+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=469", "doc_key": "06e5aaeee8fa04b66eaf15faf5c2dca4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fc08a4f44a896d537dbd3c60aaadf4702479cb3834fdb8e8a4ac4f6938ce0677'),
  ('cpiuris2025::aa5cecde2a4d681f2c8f6219143532fc', 'doutrina', 'cp_iuris', 'Direito Civil — Atribuições dos Pais', '## Atribuições dos Pais

Rege as atribuições dos pais em relação aos filhos, incluindo direção da criação e educação, exercício de guarda, consentimento para casamento, viagem e mudança de residência.

### Conceitos
- **Atribuição**: Direito que se refere à competência ou autoridade de uma pessoa em relação a outra
- **Pais**: Os pais têm direitos e deveres legais em relação aos filhos
- **Guarda**: O exercício da autoridade parental sobre os filhos, seja unilateral ou compartilhada
- **Consentimento**: A aprovação ou rejeição de uma ação ou decisão que afeta o filho

### Referências legais
- Art. 1.584 CC/2019

### Dicas de prova
- Entenda a distinção entre direito e dever dos pais em relação aos filhos
- Conheça as diferentes formas de exercício da guarda parental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.469 (2)", "page_number": 469, "discipline": "Direito Civil", "legal_refs": ["Art. 1.584 CC/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:04:48.159543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=469", "doc_key": "aa5cecde2a4d681f2c8f6219143532fc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '401277ccb1949d50d08736fbb4ae4b8f78a59c28280cb75b54f2dd33dd0ed483'),
  ('cpiuris2025::5c3b633d06550698df5e275406357bb8', 'doutrina', 'cp_iuris', 'Direito Civil — Poder Familiar e Direitos dos Filhos', '## Poder Familiar e Direitos dos Filhos

O texto discute as atribuições do poder familiar, incluindo a nomeação de tutor, representação judicial e extrajudicial, reclamação de detenção ilegal e exigência de obediência. Além disso, aborda a Lei da Palmada, que estabelece direitos dos filhos contra o uso de castigo físico e tratamento cruel, e proíbe o exploro economico dos filhos.

### Conceitos
- **Poder Familiar**: O poder concedido aos pais para cuidar e proteger os filhos.
- **Tutoria**: A nomeação de um adulto para cuidar e representar um menor de idade.
- **Lei da Palmada**: Lei que estabelece direitos dos filhos contra o uso de castigo físico e tratamento cruel.
- **Exploro Economico**: A exploração econômica dos filhos por parte de seus pais.
- **Dignidade da Pessoa Humana**: O princípio constitucional que protege os direitos humanos e a dignidade das pessoas.
- **Razoabilidade**: O princípio que exige que as ações dos pais sejam razoáveis e justas.
- **Educação e Correção**: A educação e correção dos filhos, incluindo o uso de castigo físico e tratamento cruel.
- **Castigo Físico**: O uso de força ou violência para punir os filhos.

### Referências legais
- Art. 1.635 do Código Civil

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Entenda a diferença entre o poder familiar e a tutoria.
- Conheça a Lei da Palmada e seus principais objetivos.
- Aprenda a aplicar o princípio da razoabilidade em situações de poder familiar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.470 (1)", "page_number": 470, "discipline": "Direito Civil", "legal_refs": ["Art. 1.635 do Código Civil"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T03:05:48.432725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=470", "doc_key": "5c3b633d06550698df5e275406357bb8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ee3cad4c6ed5d72e4a1f645aee2cc5dcb82ab917c5117816185972b766b30070'),
  ('cpiuris2025::7d08dd762e138f72c13a2c0e4e07b1a4', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação dos Genitores de Dar Afeto aos Filhos', '## Obrigação dos Genitores de Dar Afeto aos Filhos

A questão discutida é sobre a possibilidade de condenar um genitor pelo abandono afetivo, com fundamentos no artigo 1.632/CC.

### Conceitos
- **Dever de Companhia**: O dever dos pais de manter a companhia recíproca com os filhos.
- **Abandono Afetivo**: A falta de afeto e cuidado dos pais em relação aos filhos.
- **Responsabilização dos Genitores**: A possibilidade de condenar um genitor pelo abandono afetivo.
- **Direito dos Pais à Companhia**: O direito dos pais de terem os filhos em sua companhia, estabelecido no artigo 1.632/CC.

### Referências legais
- Art. 1.632/CC

### Dicas de prova
- Entenda o conceito de dever de companhia e como ele se relaciona com o abandono afetivo.
- Leia atentamente o artigo 1.632/CC para entender o direito dos pais à companhia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.470 (2)", "page_number": 470, "discipline": "Direito Civil", "legal_refs": ["Art. 1.632/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:06:21.054128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=470", "doc_key": "7d08dd762e138f72c13a2c0e4e07b1a4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f2a2d232a022d1f24ea15fe2e7d1434432ff73e8eedcc7e871d26f21fabe83e7'),
  ('cpiuris2025::7dfb96003328cd81cce583574f61e527', 'doutrina', 'cp_iuris', 'Direito Civil — Abandono Afetivo e Extinção do Poder Familiar', '## Abandono Afetivo e Extinção do Poder Familiar

O autor discute a tese do abandono afetivo, questionando se há direito à indenização em decorrência dessa quebra. Além disso, analisa as hipóteses de extinção do poder familiar, incluindo a destituição do poder familiar.

### Conceitos
- **Abandono Afetivo**: Falta de afeto entre pais e filhos
- **Extinção do Poder Familiar**: Perda da autoridade parental
- **Destituição do Poder Familiar**: Perda do poder familiar por sentença judicial

### Referências legais
- Art. 1.635 e 1.638 do Código Civil

### Jurisprudência
- REsp 1159242/SP
- Súmula N STF

### Dicas de prova
- Entenda a tese do abandono afetivo e suas implicações
- Análise das hipóteses de extinção do poder familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.471", "page_number": 471, "discipline": "Direito Civil", "legal_refs": ["Art. 1.635 e 1.638 do Código Civil"], "jurisprudence": ["REsp 1159242/SP", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T03:07:05.395669+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=471", "doc_key": "7dfb96003328cd81cce583574f61e527"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd8229cb81c33fa2d5ed78e078c069a0d19abe224298117313c05eae1b628ca0b'),
  ('cpiuris2025::43b12043e6f6b255426b33df990dbcc2', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação Parental e Suspensão do Poder Familiar', '## Alienação Parental e Suspensão do Poder Familiar

A alienação parental é uma disfunção que surge em disputas de guarda, caracterizada por campanhas sem justificativa para denegrir um dos pais. A Lei nº 12.318/2010 define a alienação parental e estabelece as hipóteses para a suspensão do poder familiar.

### Conceitos
- **Alienação Parental**: Síndrome de disfunção que surge em disputas de guarda, caracterizada por campanhas sem justificativa para denegrir um dos pais.
- **Suspensão do Poder Familiar**: Medida adotada quando há alienação parental ou outros fatores que colocam em risco a segurança da criança

### Referências legais
- Art. 2º, Lei nº 12.318/2010
- Art. 1.637 do CC/02

### Dicas de prova
- Entenda a definição de alienação parental e suas implicações na suspensão do poder familiar.
- Conheça as hipóteses previstas na Lei nº 12.318/2010 para a alienação parental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.472 (1)", "page_number": 472, "discipline": "Direito Civil", "legal_refs": ["Art. 2º, Lei nº 12.318/2010", "Art. 1.637 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:07:46.240097+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=472", "doc_key": "43b12043e6f6b255426b33df990dbcc2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '69b8abf04b7b26606134a3a20bc4081055b589c7f99ed992072f9a5f80d35240'),
  ('cpiuris2025::6b15824a683f651094cc5110c6a02ae9', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação Parental', '## Alienação Parental

A alienação parental é considerada o ato de interferência na formação psicológica da criança ou adolescente por um dos genitores, avós ou pessoas que tenham autoridade sobre a criança.

### Conceitos
- **Alienação Parental**: Interferência na formação psicológica de uma criança ou adolescente
- **Atuação**: Ação exercida por alguém sobre outra pessoa
- **Formação Psicológica**: Desenvolvimento da personalidade e do caráter de uma criança ou adolescente

### Referências legais
- Art. 2º da Lei X

### Dicas de prova
- Entenda a definição de alienação parental e como ela se caracteriza.
- Identifique as pessoas que podem exercer atuação sobre uma criança ou adolescente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.472 (2)", "page_number": 472, "discipline": "Direito Civil", "legal_refs": ["Art. 2º da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:08:08.717563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=472", "doc_key": "6b15824a683f651094cc5110c6a02ae9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fea4e65db38d537dd1ce7cf802e098336e7e548371946e653f9d915457207cef'),
  ('cpiuris2025::2af0543f4fa79c3b03eaeebe1b016bd6', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação Parental', '## Alienação Parental

A alienação parental é um ato ilícito que viole o direito da criança e do adolescente à convivência familiar saudável, sendo responsabilidade civil do alienador. O juiz pode declarar a ocorrência de alienação parental e tomar medidas para compensar os danos.

### Conceitos
- **Alienação Parental**: Ato ilícito que viole o direito da criança e do adolescente à convivência familiar saudável
- **Autoridade Parental**: Direito dos pais ou tutores sobre a criança ou adolescente
- **Convivência Familiar Saudável**: Relação positiva e saudável entre os membros da família
- **Dano à Criança ou Adolescente**: Interferência psicológica que prejudica o bem-estar da criança ou adolescente

### Referências legais
- Art. 1.628 do Código Civil Brasileiro
- Súmula 342 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo da Súmula 342/STF

### Dicas de prova
- Entenda a diferença entre alienação parental e suspensão da autoridade parental
- Conheça as medidas que podem ser tomadas para compensar os danos causados pela alienação parental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.473 (1)", "page_number": 473, "discipline": "Direito Civil", "legal_refs": ["Art. 1.628 do Código Civil Brasileiro", "Súmula 342 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo da Súmula 342/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T03:08:57.614714+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=473", "doc_key": "2af0543f4fa79c3b03eaeebe1b016bd6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8abac816112bdc8d4ff3b3cfb22d20fefe29e666324bcb34730784384236b182'),
  ('cpiuris2025::bd8b645fe4a177ad921252e229543352', 'doutrina', 'cp_iuris', 'Direito Civil — Guarda de Crianças e Proteção aos Filhos', '## Guarda de Crianças e Proteção aos Filhos

A guarda é uma forma de proteção aos filhos, disciplinada pelo artigo 1.583 do Código Civil, admitindo-se duas espécies: guarda unilateral e compartilhada.

### Conceitos
- **Guarda**: forma de proteção aos filhos
- **Código Civil**: legislação que disciplina o direito civil brasileiro
- **Estatuto da Criança e do Adolescente**: leis que protegem os direitos das crianças e adolescentes
- **Alienação**: atuação psicológica que afeta a relação entre o menor e seus pais ou responsáveis

### Referências legais
- Art. 1.583 do Código Civil
- Estatuto da Criança e do Adolescente

### Dicas de prova
- Diferenciar guarda unilateral e compartilhada
- Entender a conexão entre a alienação e o direito de pleito de medida protetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.473 (2)", "page_number": 473, "discipline": "Direito Civil", "legal_refs": ["Art. 1.583 do Código Civil", "Estatuto da Criança e do Adolescente"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:09:24.605098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=473", "doc_key": "bd8b645fe4a177ad921252e229543352"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'dd2f73b1b5a4dcf120df27c015a0aca22a65069b0f7da43e8677d00200682878'),
  ('cpiuris2025::90a5a7e5fc3eceb57c335c4fb2f8be0f', 'doutrina', 'cp_iuris', 'Direito Civil — Guarda de Menores', '## Guarda de Menores

A legislação civil brasileira disciplina as guardas unilateral e compartilhadas, com a última prevendo a aplicação de guarda compartilhada em situações onde não há acordo entre os genitores. A regra é estabelecer a guarda compartilhada, mesmo sem transigência dos genitores.

### Conceitos
- **Guarda Unilateral**: A guarda de um filho por um dos pais, sem a participação do outro.
- **Guarda Compartilhada**: A guarda de um filho por ambos os pais, com divisão do tempo de convivência equilibrado.
- **Transigência**: O acordo dos genitores para estabelecer a guarda compartilhada.
- **Interesse da Criança**: A consideração principal na decisão sobre a guarda de um menor.

### Referências legais
- Art. 1.584, §2º, do CC

### Jurisprudência
- Súmula 170 do STJ

### Dicas de prova
- Entenda a diferença entre guarda unilateral e compartilhada.
- Conheça o conceito de transigência e seu papel na decisão sobre a guarda compartilhada.
- Aprenda a considerar o interesse da criança e do adolescente na decisão sobre a guarda.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.474 (1)", "page_number": 474, "discipline": "Direito Civil", "legal_refs": ["Art. 1.584, §2º, do CC"], "jurisprudence": ["Súmula 170 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T03:10:00.335354+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=474", "doc_key": "90a5a7e5fc3eceb57c335c4fb2f8be0f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '22166fe0242755cc193ad61b7977682833e5dd849759a42ea737507eced7ea90'),
  ('cpiuris2025::f4d0f636c221bd058476b3fd693197cb', 'doutrina', 'cp_iuris', 'Direito Civil — Guarda e Custódia Física', '## Guarda e Custódia Física

A legislação apresenta contradições sobre guarda alternada e compartilhada, levando a críticas de Tartuce.

### Conceitos
- **Custódia Física**: Fatores que determinam o direito de posse sobre um menor
- **Guarda Alternada**: Divisão equilibrada do tempo de convivência e base de moradia
- **Guarda Compartilhada**: Fatores que determinam o direito de posse sobre um menor

### Referências legais
- Art. 170 da Lei nº 8.069/1990
- REsp 1591161/SE

### Jurisprudência
- Tartuce, 2020, p. 1928

### Dicas de prova
- Entenda a distinção entre guarda alternada e compartilhada.
- Leia atentamente os dispositivos legais mencionados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.474 (2)", "page_number": 474, "discipline": "Direito Civil", "legal_refs": ["Art. 170 da Lei nº 8.069/1990", "REsp 1591161/SE"], "jurisprudence": ["Tartuce, 2020, p. 1928"], "confidence": 0.6, "extracted_at": "2026-05-26T03:10:34.417312+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=474", "doc_key": "f4d0f636c221bd058476b3fd693197cb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'dcc8acbd05df0375e483b84ad23fd486c4d689c5b3b613eddb10751702727cf2'),
  ('cpiuris2025::3efb8c06a004a3577d028ec5604b2c87', 'doutrina', 'cp_iuris', 'Direito Civil — Guarda Compartilhada', '## Guarda Compartilhada

A guarda compartilhada estabelece que a cidade considerada base de moradia dos filhos será aquela que melhor atender aos interesses dos filhos. A divisão do tempo de convívio com a mãe e o pai não deve ser confundida com a imposição do tempo previsto pelo instituto da guarda alternada.

### Conceitos
- **Guarda Compartilhada**: Instituto que estabelece a divisão do tempo de convívio dos filhos com a mãe e o pai
- **Guarda Alternada**: Instituto que impõe a alternância de residências entre os pais
- **Lar de Referência**: Estabelecimento de regime de convivência entre os genitores na guarda compartilhada
- **Regime de Convivência**: Condição estabelecida para a relação entre os genitores na guarda compartilhada

### Referências legais
- § 2.º do art. 1.583 do Código Civil

### Jurisprudência
- RE 123456
- Tema repetitivo ...

