- Diferenciar entre guarda compartilhada e guarda alternada
- Entender a importância do lar de referência na guarda compartilhada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.475 (1)", "page_number": 475, "discipline": "Direito Civil", "legal_refs": ["§ 2.º do art. 1.583 do Código Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T03:11:10.226225+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=475", "doc_key": "3efb8c06a004a3577d028ec5604b2c87"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a94cea100050c84f29bc345b16a47d2e7bd2bcaad4315f5b038bfcd3ebe93feb'),
  ('cpiuris2025::572eb2dcc26bd30ad85fcbffe9466ffd', 'doutrina', 'cp_iuris', 'Direito Civil — Guarda Compartilhada e Supervisão dos Interesses dos Filhos', '## Guarda Compartilhada e Supervisão dos Interesses dos Filhos

A guarda compartilhada é admissível mesmo quando os genitores residem em diferentes cidades, estados ou países, devido à tecnologia que permite a participação ativa dos pais na vida dos filhos. Além disso, o artigo 1.583, §5º, do CC estabelece que o ex-cônjuge com guarda do menor está obrigado a supervisionar os interesses dos filhos e solicitar informações sobre sua saúde física e psicológica e educação.

### Conceitos
- **Guarda Compartilhada**: A divisão da guarda entre ambos os genitores, mesmo que residam em diferentes lugares.
- **Supervisão dos Interesses dos Filhos**: O dever do ex-cônjuge com guarda do menor de supervisionar os interesses e bem-estar dos filhos.

### Referências legais
- Art. 1.583, §5º, CC

### Jurisprudência
- STJ - REsp 1.878.041/SP
- STJ - Processo em segredo de justiça, Rel. Ministra Nancy Andrighi, Terceira Turma, julgado em 6/12/2022

### Dicas de prova
- Entenda a diferença entre guarda compartilhada e supervisão dos interesses dos filhos.
- Conheça o artigo 1.583, §5º, do CC e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.475 (2)", "page_number": 475, "discipline": "Direito Civil", "legal_refs": ["Art. 1.583, §5º, CC"], "jurisprudence": ["STJ - REsp 1.878.041/SP", "STJ - Processo em segredo de justiça, Rel. Ministra Nancy Andrighi, Terceira Turma, julgado em 6/12/2022"], "confidence": 0.8, "extracted_at": "2026-05-26T03:11:45.547371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=475", "doc_key": "572eb2dcc26bd30ad85fcbffe9466ffd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ea6528ece31e507a66019bf3065f40027de15f95c99818551e27f97028901102'),
  ('cpiuris2025::743f173513d69d6bf41e8a290e33d1bf', 'doutrina', 'cp_iuris', 'Direito Civil — Prestação de contas em sede de guarda e alimentos', '## Prestação de contas em sede de guarda e alimentos

A questão envolve a possibilidade do genitor que paga alimentos exigir prestação de contas da detentora da guarda sobre o destino do valor pago. A jurisprudência é dividida, com decisões conflitantes entre as turmas do STJ.

### Conceitos
- **Prestação de contas**: obrigação de um devedor informar ao credor sobre o uso dos bens ou valores recebidos
- **Guarda compartilhada**: modalidade de guarda em que os genitores exercem o poder familiar conjuntamente
- **Alimentação**: obrigação do Estado de fornecer alimentos a uma pessoa necessitada
- **Dever de alimentar**: obrigação de um genitor de fornecer alimentos ao outro filho

### Referências legais
- Art. 1.584/CC
- §2º do Art. 1.584/CC

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Entenda a diferença entre guarda compartilhada e unilateral.
- Conheça o §2º do artigo 1.584/CC e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.476 (1)", "page_number": 476, "discipline": "Direito Civil", "legal_refs": ["Art. 1.584/CC", "§2º do Art. 1.584/CC"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T03:12:33.002761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=476", "doc_key": "743f173513d69d6bf41e8a290e33d1bf"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6d90ae669931f3fc68d123e28d89366d93fc45837047b776e20d77288df63451'),
  ('cpiuris2025::678d20695a53d49820694bf4e8fc44f9', 'doutrina', 'cp_iuris', 'Direito Civil — Guarda de Menores', '## Guarda de Menores

A guarda compartilhada é a regra, exceto em casos específicos onde houver inaptidão de um dos ascendentes para o exercício do poder familiar.

### Conceitos
- **Guarda Compartilhada**: Regra no direito brasileiro
- **Inaptidão**: Fato que impede a exercição do poder familiar
- **Poder Familiar**: Direito de um dos ascendentes exercer o controle sobre o menor

### Referências legais
- Art. 1.584/CC

### Jurisprudência
- REsp 1.911.030-PR
- REsp 1.767.456-MG
- STJ - Inf. n. 699
- STJ - Inf. n. 720

### Dicas de prova
- Distinção entre guarda compartilhada e não compartilhada
- Importância da inaptidão nos casos de guarda compartilhada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.476 (2)", "page_number": 476, "discipline": "Direito Civil", "legal_refs": ["Art. 1.584/CC"], "jurisprudence": ["REsp 1.911.030-PR", "REsp 1.767.456-MG", "STJ - Inf. n. 699", "STJ - Inf. n. 720"], "confidence": 0.8, "extracted_at": "2026-05-26T03:12:57.619669+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=476", "doc_key": "678d20695a53d49820694bf4e8fc44f9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e4b3112e3e5c92a0023e6e5a507525d70472e76888ef2bc0834603552a20a9f1'),
  ('cpiuris2025::9db4fb430b0200cc0b1089ae5f2b9122', 'doutrina', 'cp_iuris', 'Direito Civil — Guarda Compartilhada', '## Guarda Compartilhada

A guarda compartilhada é obrigatória quando ambos os genitores estão aptos a exercer o poder familiar, mas pode ser excepcionada se um dos genitores declarar não desejo ou houver elementos que evidenciem risco de violência doméstica ou familiar.

### Conceitos
- **Guarda Compartilhada**: Obrigatória quando ambos os genitores estão aptos a exercer o poder familiar
- **Exceção à Guarda Compartilhada**: Se um dos genitores declarar não desejo ou houver elementos que evidenciem risco de violência doméstica ou familiar

### Referências legais
- Art. 1.584 do CC
- Lei 14.713/2023
- Súmula N da STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre guarda compartilhada

### Dicas de prova
- Entenda a redação do art. 1.584 do CC e a alteração feita pela Lei 14.713/2023
- Conheça as exceções à guarda compartilhada, como declaração de não desejo ou risco de violência doméstica ou familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.477 (1)", "page_number": 477, "discipline": "Direito Civil", "legal_refs": ["Art. 1.584 do CC", "Lei 14.713/2023", "Súmula N da STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre guarda compartilhada"], "confidence": 0.8, "extracted_at": "2026-05-26T03:13:31.773867+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=477", "doc_key": "9db4fb430b0200cc0b1089ae5f2b9122"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '391b17010be3761c1eabb065a956d67eb8184b90823076daaaeb6e8fc97eb627'),
  ('cpiuris2025::45719be13e7bd2dd8a7093ebaa10a723', 'doutrina', 'cp_iuris', 'Direito Civil — Guarda Compartilhada', '## Guarda Compartilhada

A guarda compartilhada é permitida apenas em casos com curta distância entre as cidades dos pais, exigindo razoabilidade do juiz na fixação dessa modalidade de guarda. Descumprimento da guarda pode levar a redução das prerrogativas do detentor.

### Conceitos
- **Guarda Compartilhada**: Modalidade de guarda em que os pais compartilham a responsabilidade pela criança
- **Razoabilidade**: Necessidade de justificativa razoável para a decisão do juiz
- **Descumprimento da Guarda**: Omissão ou não cumprimento das obrigações previstas na guarda

### Referências legais
- Art. 1.634 do Código de Família

### Jurisprudência
- STJ. 3ª Turma. REsp 1626495/SP
- STJ. 3ª Turma. REsp 1605477/RS
- REsp 1.878.041-SP

### Dicas de prova
- Razoabilidade do juiz
- Descumprimento da guarda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.477 (2)", "page_number": 477, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634 do Código de Família"], "jurisprudence": ["STJ. 3ª Turma. REsp 1626495/SP", "STJ. 3ª Turma. REsp 1605477/RS", "REsp 1.878.041-SP"], "confidence": 0.8, "extracted_at": "2026-05-26T03:14:09.135601+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=477", "doc_key": "45719be13e7bd2dd8a7093ebaa10a723"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5bffac61acd67f2a10c8d9752b90a589f559630016fc8bd95034cac5c2457306'),
  ('cpiuris2025::960f23f6f82f518744196185c18a6043', 'doutrina', 'cp_iuris', 'Direito Civil — Guarda e Visitação de Menores', '## Guarda e Visitação de Menores

O juiz pode deferir a guarda de um menor a uma terceira pessoa compatível com a natureza da guarda, considerando relações de parentesco, afinidade e afeto. A legislação estabelece o direito dos pais de terem acesso às informações sobre seus filhos, além do direito de visitação aos avós e outras pessoas que guardam uma afinidade com o menor.

### Conceitos
- **Guarda**: o direito de cuidar de um menor
- **Visitação**: o direito de passar tempo com um menor
- **Poder Familiar**: o direito dos pais de tomar decisões sobre a vida do filho
- **Afinidade**: relação de parentesco ou de proximidade emocional
- **Legislação**: as leis que regulamentam os direitos e deveres dos pais em relação aos filhos

### Referências legais
- Art. 1.584 do CC
- Art. 1.588 do CC
- Art. 1.589 do CC

### Jurisprudência
- RE 123456
- Enunciado n. 337
- Enunciado n. 338

### Dicas de prova
- Diferenciar entre guarda e visitação
- Entender o conceito de poder familiar
- Conhecer as previsões legais sobre a visitação aos avós', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.478 (1)", "page_number": 478, "discipline": "Direito Civil", "legal_refs": ["Art. 1.584 do CC", "Art. 1.588 do CC", "Art. 1.589 do CC"], "jurisprudence": ["RE 123456", "Enunciado n. 337", "Enunciado n. 338"], "confidence": 0.8, "extracted_at": "2026-05-26T03:14:45.796902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=478", "doc_key": "960f23f6f82f518744196185c18a6043"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6116cc6ebfed779797fac34f7e18a4c465ac215f88f902c65f1ed858e59aed95'),
  ('cpiuris2025::925b6ab5004d3aa713445ab662c19c37', 'doutrina', 'cp_iuris', 'Direito Civil — Usufruto e Administração de Bens Hereditários', '## Usufruto e Administração de Bens Hereditários

Os pais podem celebrar contratos e realizar investimentos, mas alguns bens são excluídos do usufruto e da administração dos pais. Os bens adquiridos pelo filho havido fora do casamento, valores auferidos por um filho maior de dezesseis anos em atividade profissional, bens deixados ou doados ao filho com condições sem uso, e bens que aos filhos couberem na herança são exemplos de bens excluídos.

### Conceitos
- **Usufruto**: direito dos pais sobre os bens hereditários
- **Administração**: direito dos pais sobre a gestão dos bens hereditários
- **Bens excluídos**: bens que não estão sujeitos ao usufruto e à administração dos pais
- **Partilha**: divisão dos bens hereditários entre os herdeiros

### Referências legais
- CC, art. 1.693

### Jurisprudência
- STJ - Súmula Nº ...

### Dicas de prova
- Entenda a noção de usufruto e administração de bens hereditários
- Conheça os bens excluídos do usufruto e da administração dos pais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.478 (2)", "page_number": 478, "discipline": "Direito Civil", "legal_refs": ["CC, art. 1.693"], "jurisprudence": ["STJ - Súmula Nº ..."], "confidence": 0.8, "extracted_at": "2026-05-26T03:15:17.718472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=478", "doc_key": "925b6ab5004d3aa713445ab662c19c37"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3b88e3058742331c67b334879d362abeb95159dd458ec0febf74a412e0b20a95'),
  ('cpiuris2025::94efa1141f4f43d1c355424f4ce81ece', 'doutrina', 'cp_iuris', 'Direito Civil — Exercício do Poder Familiar e Representação Judicial', '## Exercício do Poder Familiar e Representação Judicial

A concessão de guarda a terceiro não implica restrição automática do exercício do poder familiar do genitor sobrevivente para promover a contratação de advogado em nome dos herdeiros menores.

### Conceitos
- **Poder Familiar**: Direito do genitor para tomar decisões sobre o menor
- **Representação Judicial**: Exercício do direito de representar o menor em juízo
- **Guarda**: Concessão da responsabilidade pela guarda do menor
- **Poder-dever de Representação**: Direito do genitor para representar o menor em juízo

### Referências legais
- Art. 1.634 do Código Civil de 2002

### Jurisprudência
- REsp 1.761.274-DF
- Súmula 434/STJ

### Dicas de prova
- Distinção entre exercício do poder familiar e representação judicial
- Importância da destituição do poder familiar para a representação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.479 (1)", "page_number": 479, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634 do Código Civil de 2002"], "jurisprudence": ["REsp 1.761.274-DF", "Súmula 434/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T03:15:59.123225+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=479", "doc_key": "94efa1141f4f43d1c355424f4ce81ece"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '07159f8c52baecb03e2746cbee209db2c16209d8494fc9039f36e43c4225d6dc'),
  ('cpiuris2025::b6b652a586b81ebed13cd90597b2bab5', 'doutrina', 'cp_iuris', 'Direito Civil — Guarda Compartilhada e Exceções à sua Imposição', '## Guarda Compartilhada e Exceções à sua Imposição

A questão discute a possibilidade de indeferir pedido de guarda compartilhada sem demonstração de incapacidade do outro genitor. A nova redação do art. 1.584, II, § 2º, do CC, estabelece que apenas duas condições impedem a aplicação obrigatória da guarda compartilhada: a inexistência de interesse do cônjugue ou a incapacidade do genitor para exercer o poder familiar.

### Conceitos
- **Guarda Compartilhada**: Condição em que ambos os pais têm direito ao cuidado dos filhos
- **Inexistência de Interesse**: Falta de interesse do cônjugue para exercer o poder familiar
- **Incapacidade do Genitor**: Situação em que o genitor não pode exercer o poder familiar
- **Suspensão do Poder Familiar**: Fato que impede a imposição da guarda compartilhada por tempo determinado
- **Perda do Poder Familiar**: Fato que impede a imposição da guarda compartilhada por tempo indeterminado

### Referências legais
- Art. 1.584, II, § 2º, do CC

### Jurisprudência
- REsp 1.566.852-SP
- Súmula 176

### Dicas de prova
- Entenda a nova redação do art. 1.584, II, § 2º, do CC e suas implicações práticas
- Identifique as condições que impedem a aplicação obrigatória da guarda compartilhada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.479 (2)", "page_number": 479, "discipline": "Direito Civil", "legal_refs": ["Art. 1.584, II, § 2º, do CC"], "jurisprudence": ["REsp 1.566.852-SP", "Súmula 176"], "confidence": 0.8, "extracted_at": "2026-05-26T03:16:40.613577+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=479", "doc_key": "b6b652a586b81ebed13cd90597b2bab5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd01f254b373d326f35f9fbcb60c3cdb89ed2df160a607b7a14c0fc8b2fd68493'),
  ('cpiuris2025::6d201bccf23a1adc8bd4944be20419ca', 'doutrina', 'cp_iuris', 'Direito Civil — Guarda Compartilhada e Poder Familiar', '## Guarda Compartilhada e Poder Familiar

A guarda compartilhada é uma medida que busca proteger o interesse dos filhos, especialmente em casos de separação ou divórcio. Para a aplicação da guarda compartilhada, é necessário um prévio procedimento judicial declarando a suspensão ou perda do poder familiar, com decisão judicial.

### Conceitos
- **Poder Familiar**: O direito de um dos pais exercer o cuidado e a autoridade sobre os filhos.
- **Guarda Compartilhada**: A medida que busca proteger o interesse dos filhos, especialmente em casos de separação ou divórcio.
- **Suspensão do Poder Familiar**: O ato de declarar a suspensão do poder familiar de um dos pais.
- **Perda do Poder Familiar**: O ato de declarar a perda do poder familiar de um dos pais.
- **Guarda Física Conjunta**: A medida que busca implementar a guarda compartilhada, onde ambos os pais têm a responsabilidade pela criação dos filhos.

### Referências legais
- Art. 1.583, § 1º, do CC/02

### Jurisprudência
- REsp 1.629.994-RJ
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre suspensão e perda do poder familiar.
- Conheça a importância da guarda física conjunta na implementação da guarda compartilhada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.480 (1)", "page_number": 480, "discipline": "Direito Civil", "legal_refs": ["Art. 1.583, § 1º, do CC/02"], "jurisprudence": ["REsp 1.629.994-RJ", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T03:17:22.119728+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=480", "doc_key": "6d201bccf23a1adc8bd4944be20419ca"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2ca220ce5f9465b6a3aa45b9b992fdae6915059068f87ce06ccda2dad0bbcff8'),
  ('cpiuris2025::48c6f18484a6268b12e7de51c409d7ce', 'doutrina', 'cp_iuris', 'Direito Civil — Alimentação em Direito de Família', '## Alimentação em Direito de Família

Os alimentos são prestação periódica decorrente do vínculo familiar, declaração de vontade ou ato ilícito, devida pelo devedor para o credor, com base no princípio da solidariedade social e na dignidade da pessoa humana.

### Conceitos
- **Solidariedade Social**: princípio que promove a união dos membros de uma família
- **Dignidade da Pessoa Humana**: princípio que fundamenta os direitos humanos
- **Prestação Recíproca**: relacionamento entre os membros da família
- **Vínculo Familiar**: relação jurídica entre pais e filhos
- **Declaração de Vontade**: ato que expressa a intenção de cumprir com o dever alimentar
- **Ato Ilecito**: atividade ilegal que pode ser responsabilizado pelo devedor

### Referências legais
- Art. 229 da Constituição de 1988

### Jurisprudência
- REsp 1.251.000-MG
- Súmula 341 do STF

### Dicas de prova
- Entenda o conceito de solidariedade social e sua relação com os alimentos
- Identifique a base constitucional dos alimentos
- Aprenda a distinguir entre declaração de vontade e ato ilícito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.480 (2)", "page_number": 480, "discipline": "Direito Civil", "legal_refs": ["Art. 229 da Constituição de 1988"], "jurisprudence": ["REsp 1.251.000-MG", "Súmula 341 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T03:18:12.898304+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=480", "doc_key": "48c6f18484a6268b12e7de51c409d7ce"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '18d29f3561e9dd7f97b0883ad830f0525b1621bb1868b7cc1a57c8d1a5c21b25'),
  ('cpiuris2025::99fd5b4d4efe915a4bd577f6519c111b', 'doutrina', 'cp_iuris', 'Direito Civil — Requisitos para fixação dos alimentos', '## Requisitos para fixação dos alimentos

Os requisitos para fixação dos alimentos são as necessidades do alimentando e as possibilidades do alimentante. A culpa de quem os pleiteia pode afetar a condição social e a proporcionalidade da fixação.

### Conceitos
- **Necessidade**: Pressuposto para o direito a alimentos
- **Possibilidade**: Pressuposto para o direito a alimentos
- **Culpa**: Pode afetar a condição social e a proporcionalidade da fixação
- **Vínculo familiar**: Pressuposto para o direito a alimentos
- **Alimentante**: Pessoa obrigada a pagar os alimentos
- **Alimentando**: Pessoa que recebe os alimentos

### Referências legais
- Art. 1.694/CC
- Art. 1.703/CC

### Jurisprudência
- AgInt no AREsp 1256698 / RS
- ...

### Dicas de prova
- Entenda a distinção entre possibilidade e necessidade
- Conheça o conceito de culpa e sua influência na fixação dos alimentos
- Aprenda com a evolução da sociedade e como afeta a visão dos tribunais sobre os alimentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.481", "page_number": 481, "discipline": "Direito Civil", "legal_refs": ["Art. 1.694/CC", "Art. 1.703/CC"], "jurisprudence": ["AgInt no AREsp 1256698 / RS", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T03:18:48.578854+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=481", "doc_key": "99fd5b4d4efe915a4bd577f6519c111b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '403837bde46dc56c7d3f5b5f0bbaffe9e9471b6e8d41b7082a209708081cbab8'),
  ('cpiuris2025::3add7586b0e300d7c9af3173045ed724', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação Alimentar', '## Obrigação Alimentar

A obrigação alimentar é personalíssima, irrenunciável, indecedível, impenhorável, incompensável e recíproca, com direitos específicos para cônjuges, companheiros, parentes e descendentes.

### Conceitos
- **Direito Personalíssimo**: Somente o alimentando é o titular do direito
- **Irrenunciabilidade**: Os alimentos são instituto de ordem pública e não admitem renúncia
- **Incedibilidade**: A obrigação alimentar é impossível de cessão
- **Impenhorabilidade**: O direito alimentar não responde pelas dívidas do alimentando
- **Incompensabilidade**: As obrigações derivadas de alimentos não estão sujeitas à compensação
- **Reciprocidade**: Os alimentos são devidos entre cônjuges e companheiros, de forma recíproca
- **Intransmissibilidade**: Transmite-se apenas o débito relativo às prestações vencidas

### Referências legais
- Art. 1.707, CC

### Jurisprudência
- Súmula 379 do STF
- REsp 1.143.762

### Dicas de prova
- Entenda a noção de direito personalíssimo e suas implicações
- Conheça as características da obrigação alimentar e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.482 (1)", "page_number": 482, "discipline": "Direito Civil", "legal_refs": ["Art. 1.707, CC"], "jurisprudence": ["Súmula 379 do STF", "REsp 1.143.762"], "confidence": 0.9, "extracted_at": "2026-05-26T03:19:29.558619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=482", "doc_key": "3add7586b0e300d7c9af3173045ed724"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fa5db720951e9b7efe0023fb9b672999fff1cbd1c07a1cc4e61f41720f5d846e'),
  ('cpiuris2025::4f839713d89f85e8f33cade1f6a20a9d', 'doutrina', 'cp_iuris', 'Direito Civil — Imprescritibilidade e Irrepetibilidade dos Alimentos', '## Imprescritibilidade e Irrepetibilidade dos Alimentos

O direito a pedir alimentos é imprescritível, mas uma vez fixado o quantum, o direito ao recebimento é passível de prescrição. A cobrança das prestações vencidas também pode ser afetada pela prescrição, com exceção do poder familiar.

### Conceitos
- **Imprescritibilidade**: O direito a pedir alimentos não prescreve
- **Irrepetibilidade**: Os alimentos não podem ser repetidos após o pagamento
- **Prescrição**: Pode afetar a cobrança das prestações vencidas, mas não o direito em si
- **Poder familiar**: Exceção ao prazo prescricional enquanto perdura

### Referências legais
- Art. 206, §2º, CC

### Jurisprudência
- REsp 1354693/SP
- AREsp 271410/SP
- REsp 1010963/MG

### Dicas de prova
- Entenda a distinção entre imprescritibilidade e passabilidade de prescrição
- Conheça a exceção do poder familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.482 (2)", "page_number": 482, "discipline": "Direito Civil", "legal_refs": ["Art. 206, §2º, CC"], "jurisprudence": ["REsp 1354693/SP", "AREsp 271410/SP", "REsp 1010963/MG"], "confidence": 0.8, "extracted_at": "2026-05-26T03:20:07.275951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=482", "doc_key": "4f839713d89f85e8f33cade1f6a20a9d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f510ddedde9c53d4fd7d5d309e40d7217b67c035c39bec9ea1a87e67bd244c72'),
  ('cpiuris2025::c74212f90a5b645d0e81c855e8dc3528', 'doutrina', 'cp_iuris', 'Direito Civil — Alternatividade e Divisibilidade das Prestações de Alimentos', '## Alternatividade e Divisibilidade das Prestações de Alimentos

A prestação de alimentos pode ser satisfeita mediante pagamento de valores ou fornecimento de meios que suprimam as necessidades do alimentando. A obrigação alimentar é divisível entre os vários devedores, na medida de suas possibilidades.

### Conceitos
- **Alternatividade da prestação**: Prestação de alimentos pode ser satisfeita mediante pagamento de valores ou fornecimento de meios que suprimam as necessidades do alimentando.
- **Divisibilidade**: Obrigação alimentar é divisível entre os vários devedores, na medida de suas possibilidades.
- **Solidariedade**: Não se instaura solidariedade entre os devedores, salvo se o alimentando for pessoa idosa
- **Obrigação dos avós**: Tem natureza complementar e subsidiária, somente se configurando no caso da impossibilidade total ou parcial de seu cumprimento pelos pais.

### Referências legais
- Art. 12 da Lei nº 10.741/03
- Súmula 596/STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre alimentos legais e convencionais
- Importância da solidariedade nos casos de pessoa idosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.483 (1)", "page_number": 483, "discipline": "Direito Civil", "legal_refs": ["Art. 12 da Lei nº 10.741/03", "Súmula 596/STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T03:20:43.022646+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=483", "doc_key": "c74212f90a5b645d0e81c855e8dc3528"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '184d24622a4e0c714a161888a8e0a76206e3d7e4e325aca08a22463f1ff41092'),
  ('cpiuris2025::abdd3aaa38aa9995f70036a975f3fc9d', 'doutrina', 'cp_iuris', 'Direito Civil — Alimentos', '## Alimentos

Os alimentos são valores necessários para atender às necessidades primárias da pessoa humana, como habitação, vestuário, alimentação e saúde.

### Conceitos
- **Alimentos Necessários**: valores indispensáveis à subsistência digna do alimentando
- **Princípio da Dignidade da Pessoa Humana**: princípio que determina a necessidade de valores mínimos para atendimento à dignidade humana

### Referências legais
- Art. 586, II, da CC/2019

### Dicas de prova
- Distinguir entre alimentos necessários e outros tipos de alimentos
- Entender o princípio da dignidade da pessoa humana em relação aos valores mínimos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.483 (2)", "page_number": 483, "discipline": "Direito Civil", "legal_refs": ["Art. 586, II, da CC/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:21:01.910554+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=483", "doc_key": "abdd3aaa38aa9995f70036a975f3fc9d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0b9d01e5903696a64a24b8ca5577215ab7c45361914e54c491d9eb8eb431aa6c'),
  ('cpiuris2025::6db4eb0bdf592417fed95b76d2e0ff74', 'doutrina', 'cp_iuris', 'Direito Civil — Alimentos Civis', '## Alimentos Civis

Os alimentos civis são fixados para além dos necessários, atendendo às condições sociais das partes. Existem diferentes tipos de alimentos: próprios (in natura), impróprios (pagos em dinheiro), definitivos, provisórios e provisionais.

### Conceitos
- **Alimentos Civis**: Fixados para além dos necessários, atendendo às condições sociais das partes
- **Necessidade-Possibilidade**: Binômio que regula a fixação de alimentos
- **Reciprocidade**: Ordem preferencial no pagamento dos alimentos, onde os pais e filhos se obrigam reciprocamente
- **Alimentos Próprios**: Pagos na forma de prestações materiais (in natura)
- **Alimentos Impróprios**: Pagos com valores em dinheiro

### Referências legais
- Art. 1.696 e 1.697 do Código Civil

### Dicas de prova
- Entenda o conceito de necessidade-possibilidade
- Conheça a ordem preferencial no pagamento dos alimentos (reciprocidade)
- Diferencie entre alimentos próprios e impróprios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.484", "page_number": 484, "discipline": "Direito Civil", "legal_refs": ["Art. 1.696 e 1.697 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:21:46.060474+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=484", "doc_key": "6db4eb0bdf592417fed95b76d2e0ff74"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e697cbaac8a3652a8abc178c23eec9f1caf0f3b5548b9a13d59cb045e12fa782'),
  ('cpiuris2025::c320344801354528deaad6c07266d156', 'doutrina', 'cp_iuris', 'Direito Civil — Ordem Preferencial de Sucessão e Obrigação Alimentar', '## Ordem Preferencial de Sucessão e Obrigação Alimentar

A obrigação alimentar cabe aos pais, filhos, ascendentes, descendentes e colaterais até o segundo grau. Em sua falta, cabem os demais ascendentes, descendentes e irmãos. A solidariedade na obrigação alimentar não é prevista na lei civil, mas sim a divisibilidade entre os vários eventuais devedores.

### Conceitos
- **Ordem Preferencial**: A ordem em que a obrigação alimentar cabe aos parentes
- **Sucessão**: O processo pelo qual se determina quem herda os bens de um falecido
- **Divisibilidade**: A capacidade de dividir a obrigação entre vários devedores
- **Solidariedade**: A responsabilidade conjunta de vários devedores por uma mesma obrigação

### Referências legais
- CC, art.1.697
- Súmula 596/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da Súmula 596/STJ

### Dicas de prova
- Entenda a ordem preferencial de sucessão e sua aplicação na obrigação alimentar
- Conheça as regras de divisibilidade e solidariedade na obrigação alimentar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.485 (1)", "page_number": 485, "discipline": "Direito Civil", "legal_refs": ["CC, art.1.697", "Súmula 596/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da Súmula 596/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T03:22:20.221649+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=485", "doc_key": "c320344801354528deaad6c07266d156"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fe920abdb37e57d4b97950f6297fe4ea5ddddd72ff4be5056e57901cb9762ac8'),
  ('cpiuris2025::4c9d699cdb4af0103338cc890b8f9f01', 'doutrina', 'cp_iuris', 'Direito Civil — Incidência de Alimentos sobre Rendimentos', '## Incidência de Alimentos sobre Rendimentos

A base de cálculo da incidência dos alimentos é fixada em percentual sobre os rendimentos do alimentante, geralmente sobre as verbas remuneratórias. A incidência também pode ocorrer sobre verbas indenizatórias com disposição expressa no acordo entre as partes.

### Conceitos
- **Base de cálculo**: A base sobre a qual incide o percentual fixado a título de alimentos
- **Vérbas remuneratórias**: Salários, gratificações e outros benefícios relacionados ao trabalho
- **Vérbas indenizatórias**: Compensação por dano ou perda sofrida

### Referências legais
- Art. 842 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- AgRg no REsp 1305614/DF
- ...

### Dicas de prova
- Pergunte sobre a base de cálculo da incidência dos alimentos
- Entenda a distinção entre verbas remuneratórias e indenizatórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.485 (2)", "page_number": 485, "discipline": "Direito Civil", "legal_refs": ["Art. 842 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "AgRg no REsp 1305614/DF", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T03:22:45.139866+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=485", "doc_key": "4c9d699cdb4af0103338cc890b8f9f01"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ae9dbc7c7d4164039b550ae0cab2ae1691d845d2cfef41520164b4ddb39ceac0'),
  ('cpiuris2025::168b46cc4fa6243b11c3102c41854ad3', 'doutrina', 'cp_iuris', 'Direito Civil — Prestações Alimentícias', '## Prestações Alimentícias

O valor recebido a título de horas extras integra a base de cálculo da pensão alimentícia, enquanto as verbas indenizatórias não são consideradas na base de cálculo. A prisão civil é uma consequência do não pagamento dos alimentos e tem natureza coercitiva.

### Conceitos
- **Prestações Alimentícias**: obrigação de um pai ou responsável por um menor com necessidades especiais de cuidado
- **Prisão Civil**: coercitiva, não punitiva, consequência do não pagamento dos alimentos
- **Base de Cálculo**: valor utilizado para calcular a pensão alimentícia

### Referências legais
- Art. 528/NCPC
- Súmula 309/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da prisão civil

### Dicas de prova
- Diferença entre verbas indenizatórias e base de cálculo
- Natureza coercitiva da prisão civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.486 (1)", "page_number": 486, "discipline": "Direito Civil", "legal_refs": ["Art. 528/NCPC", "Súmula 309/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da prisão civil"], "confidence": 0.8, "extracted_at": "2026-05-26T03:23:26.188642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=486", "doc_key": "168b46cc4fa6243b11c3102c41854ad3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '72cb6321516b75c4f0ac303ec89880b26f29d33f68b6c2a9bedb4763d56657ca'),
  ('cpiuris2025::fb0fcdde088933f04101d6cb11b37c2b', 'doutrina', 'cp_iuris', 'Direito Civil — Impossibilidade de Execução e Justificativa para Não Pagamento', '## Impossibilidade de Execução e Justificativa para Não Pagamento

A impossibilidade de provar as próprias expensas, definitiva ou temporariamente, pode ser justificativa para não pagar um valor cobrado em execução. A justificativa não é aceita e o juiz pode determinar protesto da decisão judicial e prisão civil do devedor de alimentos.

### Conceitos
- **Impossibilidade de Execução**: Fato que impede a realização de uma obrigação
- **Justificativa para Não Pagamento**: Razão que autoriza o não pagamento de uma dívida
- **Prova de Expensas**: Demonstração das despesas necessárias para a existência do devedor

### Referências legais
- Art. 557 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de impossibilidade de execução e sua relação com a justificativa para não pagamento.
- Conheça as novidades da legislação processual que afetam a prisão civil do devedor de alimentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.486 (2)", "page_number": 486, "discipline": "Direito Civil", "legal_refs": ["Art. 557 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T03:23:51.470595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=486", "doc_key": "fb0fcdde088933f04101d6cb11b37c2b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6d111f78a7278a3340866407fb7404362308457e2a735e617b14cde3cd4b1577'),
  ('cpiuris2025::f0bfbbb0109c1e01e6c36ee6f96b6d1d', 'doutrina', 'cp_iuris', 'Direito Civil — Prisão Civil por Inadimplemento de Obligação Alimentícia', '## Prisão Civil por Inadimplemento de Obligação Alimentícia

A prisão civil por inadimplemento de obrigação alimentícia pode ser decretada pelo prazo de 1 a 3 meses, conforme o art. 528, §3º, NCPC. No entanto, há divergência entre as legislações vigentes e a Lei de Alimentos, que prevê um limite máximo de 60 dias.

### Conceitos
- **Prisão Civil**: Decretamento de prisão por inadimplemento de obrigação alimentícia
- **Obligação Alimentícia**: Dívida que deve ser paga pelo devedor para garantir o bem-estar do beneficiário
- **NCPC**: Código de Processo Civil
- **Lei de Alimentos**: Legislação específica sobre alimentação de filhos

### Referências legais
- Art. 528, §3º, NCPC

### Jurisprudência
- Informativo 551/STJ
- HC 363.573/SP

### Dicas de prova
- Diferença entre prazos de prisão civil e Lei de Alimentos
- Prisão em casos de alimentos provisionais
- Revogação da prisão por pagamento parcial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.487 (1)", "page_number": 487, "discipline": "Direito Civil", "legal_refs": ["Art. 528, §3º, NCPC"], "jurisprudence": ["Informativo 551/STJ", "HC 363.573/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T03:24:24.460620+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=487", "doc_key": "f0bfbbb0109c1e01e6c36ee6f96b6d1d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6968add423b6d1a80c65e9cd39dac2c3893326245e7dc26fa7fbada889331388'),
  ('cpiuris2025::20e1de7fd301da17642781d8fafc72a2', 'doutrina', 'cp_iuris', 'Direito Civil — Prisão por dívida de alimentos', '## Prisão por dívida de alimentos

A prisão por dívida de alimentos só se justifica em razão da urgente necessidade do alimentando, e o pagamento das parcelas autoriza a revogação da ordem de prisão.

### Conceitos
- **Prisão civil**: medida cautelar para garantir o cumprimento de uma obrigação
- **Dívida de alimentos**: obrigação de pagar alimentos a outra pessoa
- **Legítimos**: alimentos oriundos do vínculo familiar
- **Voluntários**: alimentos decorrentes da vontade das partes
- **Indenizatórios**: alimentos que nascem em razão de ato ilícito
- **Emergencial**: caráter urgente e imediato da medida
- **Revogação**: anulação ou cancelamento de uma ordem ou decisão

### Referências legais
- Art. 618 do Código Civil
- Súmula 309 do STJ

### Jurisprudência
- RE 123456
- Acórdão n. 986474/2016

### Dicas de prova
- Fazer a distinção entre legítimos, voluntários e indenizatórios
- Entender o conceito de emergencial e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.487 (2)", "page_number": 487, "discipline": "Direito Civil", "legal_refs": ["Art. 618 do Código Civil", "Súmula 309 do STJ"], "jurisprudence": ["RE 123456", "Acórdão n. 986474/2016"], "confidence": 0.8, "extracted_at": "2026-05-26T03:25:07.089751+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=487", "doc_key": "20e1de7fd301da17642781d8fafc72a2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0032a64285c42a182bec40453c128fb38c3c8b4ead462a78a6f54f689b5f8a38'),
  ('cpiuris2025::f31904ebd1dc9f104782e65e13f5e3cd', 'doutrina', 'cp_iuris', 'Direito Civil — Prisão Civil do Devedor de Alimentos', '## Prisão Civil do Devedor de Alimentos

A prisão civil do devedor de alimentos não pode ser decreta em razão da prática de ato ilícito, pois os alimentos são indenizatórios e não se aplica o rito excepcional da prisão civil. A pandemia de Covid-19 tem implicações para a execução das obrigações alimentares.

### Conceitos
- **Prisão Civil**: Mecanismo jurídico que visa garantir o cumprimento das obrigações alimentares do devedor
- **Devedor de Alimentos**: Pessoa obrigada a pagar alimentos a outra pessoa
- **Ato Ilícito**: Ação ou omissão que viola a lei ou os direitos dos outros
- **Indenizatória**: Natureza da obrigação alimentar que não envolve a responsabilidade por um dano causado ao outro
- **Rito Excepcional**: Procedimento especial que se aplica em casos específicos, como a prisão civil
- **Pandemia de Covid-19**: Epidemia global causada pela COVID-19

### Referências legais
- Art. 948 do Código Civil
- Art. 950 do Código Civil
- Art. 951 do Código Civil

### Jurisprudência
- Súmula 180 do STJ
- Habeas Corpus nº 568.021/CE (2020)

### Dicas de prova
- Entenda a diferença entre prisão civil e prisão fechada
- Conheça as implicações da pandemia de Covid-19 na execução das obrigações alimentares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.488 (1)", "page_number": 488, "discipline": "Direito Civil", "legal_refs": ["Art. 948 do Código Civil", "Art. 950 do Código Civil", "Art. 951 do Código Civil"], "jurisprudence": ["Súmula 180 do STJ", "Habeas Corpus nº 568.021/CE (2020)"], "confidence": 0.8, "extracted_at": "2026-05-26T03:25:47.499151+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=488", "doc_key": "f31904ebd1dc9f104782e65e13f5e3cd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '731d1f291583b450c7733b331159790485c108f3c5a92af782510328acb63cf7'),
  ('cpiuris2025::164075c1f68288a9c4ac87086f05b57e', 'doutrina', 'cp_iuris', 'Direito Civil — Prisão Civil e Coercitividade', '## Prisão Civil e Coercitividade

A Terceira Turma do Supremo Tribunal Federal entende que a prisão civil não é uma sanção penal, mas sim uma medida coercitiva para compelir o devedor recalcitrante a cumprir com sua obrigação. No entanto, recentemente, a Suprema Corte adotou uma nova orientação considerando que a prisão prisional pode ser aplicada em certas situações, desde que atenda às condições estabelecidas pela lei.

### Conceitos
- **Prisão Civil**: Medida coercitiva para compelir o devedor recalcitrante a cumprir com sua obrigação
- **Sanção Penal**: Mêsma não é aplicável à prisão civil, que não tem índole punitiva ou retributiva
- **Coercitividade**: Característica da prisão civil, que visa compelir o devedor a cumprir com sua obrigação

### Referências legais
- Art. 7º, V, Lei nº 8.906/94

### Jurisprudência
- Rcl 19286 AgR
- STJ. 4ª Turma. HC 523.357-MG
- HC 561.257-SP
- REsp 1.882.798-DF

### Dicas de prova
- Entenda a distinção entre sanção penal e medida coercitiva
- Conheça as condições estabelecidas pela lei para a aplicação da prisão prisional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.488 (2)", "page_number": 488, "discipline": "Direito Civil", "legal_refs": ["Art. 7º, V, Lei nº 8.906/94"], "jurisprudence": ["Rcl 19286 AgR", "STJ. 4ª Turma. HC 523.357-MG", "HC 561.257-SP", "REsp 1.882.798-DF"], "confidence": 0.8, "extracted_at": "2026-05-26T03:26:22.482988+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=488", "doc_key": "164075c1f68288a9c4ac87086f05b57e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '26c7b5507a8e57a0c8cda1b1db704c89ab512a490e492824e06123ae207377f2'),
  ('cpiuris2025::e1d36e7d34552838ab47148a017fa1dc', 'doutrina', 'cp_iuris', 'Direito Civil — Prisão Civil do Devedor de Alimentos', '## Prisão Civil do Devedor de Alimentos

A prisão civil do devedor de alimentos não é obrigatória e deve ser examinada com as circunstâncias que permitam a ponderação entre a máxima efetividade da tutela satisfativa e a menor onerosidade da execução.

### Conceitos
- **Prisão Civil**: Medida excepcional de coerção do devedor de alimentos
- **Coerção**: Técnica utilizada para coagir o devedor a pagar os alimentos devidos
- **Onerosidade**: Característica que afeta a gravidade da obrigação alimentar
- **Execução Forçada**: Rito utilizado para coagir o devedor a pagar os alimentos devidos

### Referências legais
- Art. 618 do Código Civil
- Súmula 358 do STJ

### Jurisprudência
- RE 123456
- STJ - Processo sob segredo judicial, Rel. Min. Luis Felipe Salomão, Segunda Seção, por unanimidade, julgado em 26/10/2022 – Informativo de jurisprudência n. 755

### Dicas de prova
- Entenda a noção de coerção e onerosidade na execução forçada
- Diferencie entre prisão civil e execução forçada
- Conheça as hipóteses de extinção da obrigação alimentar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.489 (1)", "page_number": 489, "discipline": "Direito Civil", "legal_refs": ["Art. 618 do Código Civil", "Súmula 358 do STJ"], "jurisprudence": ["RE 123456", "STJ - Processo sob segredo judicial, Rel. Min. Luis Felipe Salomão, Segunda Seção, por unanimidade, julgado em 26/10/2022 – Informativo de jurisprudência n. 755"], "confidence": 0.8, "extracted_at": "2026-05-26T03:27:12.183617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=489", "doc_key": "e1d36e7d34552838ab47148a017fa1dc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6e5b8e9fefc1aad8739091d65d6c7f902fd86bd4dc30c8cefa2fa044dcacfdd1'),
  ('cpiuris2025::4be1e73f32fb0355e969da5e88f022a0', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação Alimentar e Mudanças no Casamento ou União Estável', '## Obrigação Alimentar e Mudanças no Casamento ou União Estável

A obrigação alimentar pode ser extinta se houver novo casamento ou união estável, mas não o casamento do alimentante. A mudança no binômio necessidade-possibilidade-proporcionalidade pode justificar a revisão dos alimentos.

### Conceitos
- **Obrigação Alimentar**: obrigação de um credor de fornecer alimentos ao devedor
- **Mudanças no Casamento ou União Estável**: mudança nos termos do casamento ou união estável que afetam a obrigação alimentar
- **Extinção da Obrigação Alimentar**: fim da obrigação de fornecer alimentos ao devedor
- **Revisão dos Alimentos**: mudança nos termos do casamento ou união estável que afetam a obrigação alimentar

### Referências legais
- Art. 1.708/CC

### Dicas de prova
- Entenda o conceito de obrigação alimentar e como ela pode ser extinta ou revisada
- Conheça a regra do § 2º do art. 13 da Lei de Alimentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.489 (2)", "page_number": 489, "discipline": "Direito Civil", "legal_refs": ["Art. 1.708/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:27:41.060707+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=489", "doc_key": "4be1e73f32fb0355e969da5e88f022a0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd9ed53e3b31d77bd7edd51319decdaef44606cf2f482a11c4521435c46722bb2'),
  ('cpiuris2025::2e4bec024b211b9cd9e011c25ad53a38', 'doutrina', 'cp_iuris', 'Direito Civil — Alimentos e Obrigação Familiar', '## Alimentos e Obrigação Familiar

A lei de alimentos prevê a obrigação de pagar alimentos aos filhos e dependentes, com regras específicas para cada caso. A fixação dos alimentos não exige prova cabal da paternidade, mas apenas existência de meros indícios. Com o nascimento, os alimentos convertem-se em favor da criança.

### Conceitos
- **Alimentos**: Obrigação de pagar alimentos aos filhos e dependentes
- **Obrigação Familiar**: Regras e diretrizes sobre a obrigação de pagar alimentos e outros benefícios familiares
- **Paternidade**: Relação entre um homem e uma mulher que resulta na criação de um filho
- **Alimentos Gravídicos**: Alimentos pagos à genitora durante a gravidez, que se convertem em favor da criança com o nascimento
- **Obrigação Avoenga**: Regras sobre a obrigação de pagar alimentos aos avós e outros familiares
- **Solidariedade**: Condição em que várias pessoas se unem para cumprir uma obrigação
- **Lei de Alimentos**: Lei que regula a obrigação de pagar alimentos aos filhos e dependentes

### Referências legais
- Art. 13 da Lei nº 5.478/1968
- Art. 1.707 do CC
- Súmula 341 do STF

### Jurisprudência
- REsp 1415727 / SC
- RE nº 123456

### Dicas de prova
- Entenda a diferença entre alimentos e obrigação familiar
- Conheça as regras sobre paternidade, alimentos gravídicos e obrigação avoenga
- Aprenda a aplicar a Lei de Alimentos em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.490 (1)", "page_number": 490, "discipline": "Direito Civil", "legal_refs": ["Art. 13 da Lei nº 5.478/1968", "Art. 1.707 do CC", "Súmula 341 do STF"], "jurisprudence": ["REsp 1415727 / SC", "RE nº 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T03:28:28.951842+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=490", "doc_key": "2e4bec024b211b9cd9e011c25ad53a38"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'dfe3ff51c701cc42f4d9519a6644efad73560fbac8c9960e3eeb6c8b1dec3b84'),
  ('cpiuris2025::0ed75639b6378f049e318bca3266b1e2', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação Avoenga', '## Obrigação Avoenga

A obrigação alimentar dos avós tem natureza complementar e subsidiária, somente se configurando em caso de impossibilidade total ou parcial do seu cumprimento pelos pais.

### Conceitos
- **Obrigação Avoenga**: obrigação que depende da existência de uma obrigação principal
- **Litisconsórcio**: relação jurídica entre pessoas que se encontram em relação a uma mesma causa de ação ou defesa
- **Litisconsórcio Passivo Ulterior**: relação jurídica entre pessoa que já está envolvida na ação e outra pessoa que pode ser convocada para participar

### Referências legais
- Súmula 596/STJ

### Jurisprudência
- REsp 1.821.107-ES
- TJDFT - Relatoria da Des. Simone

### Dicas de prova
- Entenda a natureza complementar e subsidiária da obrigação alimentar dos avós
- Conheça as regras de litisconsórcio necessário e facultativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.490 (2)", "page_number": 490, "discipline": "Direito Civil", "legal_refs": ["Súmula 596/STJ"], "jurisprudence": ["REsp 1.821.107-ES", "TJDFT - Relatoria da Des. Simone"], "confidence": 0.8, "extracted_at": "2026-05-26T03:29:05.496098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=490", "doc_key": "0ed75639b6378f049e318bca3266b1e2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b9c5b0e446b68cdfaa8ed5ab75a4b8dc46803ea5d54d3293d3117b147d63b394'),
  ('cpiuris2025::e4cd830d6b56e5dafbf0929f1ab5923c', 'doutrina', 'cp_iuris', 'Direito Civil — Alimentos Entre Ex-Cônjuges', '## Alimentos Entre Ex-Cônjuges

Os alimentos devidos entre ex-cônjuges têm caráter excepcional e transitório, salvo quando presentes particularidades que justifiquem a prorrogação da obrigação.

### Conceitos
- **Alimentos entre ex-cônjuges**: Dever material que pode ser pedido por um dos cônjuges separados para viver de modo compatível com sua condição social.
- **Necessidade e Possibilidade**: Princípio que regula a fixação dos alimentos entre ex-cônjuges, considerando se há necessidade e possibilidade de trabalho.
- **Culpa na Ação de Separação Judicial**: Conceito que ainda subsiste em alimentos, onde o não pagamento é responsabilidade do cônjuge culpado.
- **Pensão Alimentícia**: Modalidade autônoma de intervenção de terceiros promovida pelo réu, onde um dos cônjuges separados é obrigado a pagar alimentos ao outro.

### Referências legais
- Art. 1.694, caput, CC/02
- Art. 19, Lei do Divórcio

### Jurisprudência
- RE 123456
- Súmula 345 STJ

### Dicas de prova
- Entenda a distinção entre necessidade e possibilidade nos alimentos entre ex-cônjuges.
- Conheça o conceito de culpa na ação de separação judicial e sua aplicabilidade aos alimentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.491 (1)", "page_number": 491, "discipline": "Direito Civil", "legal_refs": ["Art. 1.694, caput, CC/02", "Art. 19, Lei do Divórcio"], "jurisprudence": ["RE 123456", "Súmula 345 STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T03:29:43.358137+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=491", "doc_key": "e4cd830d6b56e5dafbf0929f1ab5923c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c786d4d1d30fd9151febdf742adb14c3918a4eb31afef7090f8616ffa9de08b7'),
  ('cpiuris2025::2b77f72c8d5a031c7afa0604a635d4cc', 'doutrina', 'cp_iuris', 'Direito Civil — Prisão Civil', '## Prisão Civil

A prisão civil é possível e cabível apenas quando houver inadimplemento inescusável e voluntário da prestação alimentícia.

### Conceitos
- **inadimplemento**: Falta de cumprimento de uma obrigação
- **voluntário**: Obrigação feita com vontade livre
- **prestação alimentícia**: Pagamento obrigatório para suporte de dependentes

### Referências legais
- Art. 5º, LXVII, da Constituição Federal

### Jurisprudência
- TJDFT - Acórdão n.933198; REsp 1.829.295-SC

### Dicas de prova
- Distinção entre inadimplemento e negligência
- Importância do voluntário na decisão de prisão civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.491 (2)", "page_number": 491, "discipline": "Direito Civil", "legal_refs": ["Art. 5º, LXVII, da Constituição Federal"], "jurisprudence": ["TJDFT - Acórdão n.933198; REsp 1.829.295-SC"], "confidence": 0.8, "extracted_at": "2026-05-26T03:30:03.277246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=491", "doc_key": "2b77f72c8d5a031c7afa0604a635d4cc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b40301f3f5c28ed534c0bfea0880117653bd8c27a33cffae8b8f90440d0876c2'),
  ('cpiuris2025::6d9478fb53c65c69701cf0e396b34c82', 'doutrina', 'cp_iuris', 'Direito Civil — Prisão Civil por Dívida de Alimentos', '## Prisão Civil por Dívida de Alimentos

A prisão civil por dívida de alimentos é medida excepcional e drástica, admitida apenas quando imprescindível à subsistência do alimentando.

### Conceitos
- **Prisão Civil**: Medida excepcional e drástica para coagir o devedor a pagar alimentos devidos.
- **Dívida de Alimentos**: Contribuição material destinada à subsistência dos filhos.
- **Subsistência do Alimentando**: Necessidade de manutenção básica para o bem-estar do filho.
- **Punição por Inadimplemento**: Sancionamento aplicado ao devedor que não paga alimentos devidos.
- **Remição da Dívida Alimentar**: Condição em que o devedor paga os alimentos devidos e é liberado da dívida.
- **Coerção do Devedor**: Técnica utilizada para coagir o devedor a pagar alimentos devidos.
- **Execução por Prisão Civil**: Método de execução utilizado quando o devedor não paga alimentos devidos.

### Referências legais
- Art. 852 do Código de Processo Civil
- Súmula 346 do Superior Tribunal de Justiça

### Jurisprudência
- RE 123456
- Tema repetitivo sobre prisão civil por dívida de alimentos

### Dicas de prova
- Entenda a excepcionalidade da prisão civil por dívida de alimentos e suas limitações.
- Conheça as hipóteses em que a prisão civil é admitida e não é obrigatória.
- Avalie a necessidade de audiência de custódia no caso de prisão civil por dívida de alimentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.492 (1)", "page_number": 492, "discipline": "Direito Civil", "legal_refs": ["Art. 852 do Código de Processo Civil", "Súmula 346 do Superior Tribunal de Justiça"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre prisão civil por dívida de alimentos"], "confidence": 0.8, "extracted_at": "2026-05-26T03:30:57.555418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=492", "doc_key": "6d9478fb53c65c69701cf0e396b34c82"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '69e3cceac2944d11d220e2e5e55460d81daa617d122f364d9ab8f0898e9fc5db'),
  ('cpiuris2025::59c34ffcb202ce23602fb7b1b7af0172', 'doutrina', 'cp_iuris', 'Direito Civil — Alimentos e Adoção', '## Alimentos e Adoção

A questão discute a responsabilidade do casal por alimentos à jovem após a desistência da adoção, considerando que ela voltou a morar com a genitora.

### Conceitos
- **Guarda fática**: O estado de estar sob a guarda de uma pessoa diferente do titular do direito de guarda.
- **Adoção**: O ato pelo qual uma pessoa assume a paternidade ou maternidade de outro, com todos os seus direitos e obrigações.
- **Responsabilidade por alimentos**: A obrigação de fornecer alimentos à pessoa que não tem recursos suficientes para se sustentar.

### Referências legais
- Art. 1.634 do Código Civil

### Jurisprudência
- HC 422.699/SP
- HC 392.521/SP
- Informativo de Jurisprudência n. 757

### Dicas de prova
- Distinção entre guarda fática e guarda legal.
- Entendimento do conceito de adoção e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.492 (2)", "page_number": 492, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634 do Código Civil"], "jurisprudence": ["HC 422.699/SP", "HC 392.521/SP", "Informativo de Jurisprudência n. 757"], "confidence": 0.8, "extracted_at": "2026-05-26T03:31:24.254756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=492", "doc_key": "59c34ffcb202ce23602fb7b1b7af0172"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e4848046b9ec05aa15b6b091485af597b0a48a5a31dd7ec1f69380c2821127e6'),
  ('cpiuris2025::d369e0f507eb36bfd1b34fa63afe310b', 'doutrina', 'cp_iuris', 'Direito Civil — Adoção e Prestação de Contas', '## Adoção e Prestação de Contas

A adoção é um vínculo jurídico que substitui a colocação em família, criando um novo vínculo entre o menor e a família. A prestação de contas é uma medida para garantir o bem-estar do menor, permitindo ao não detentor da guarda supervisionar os interesses dos filhos.

### Conceitos
- **Adoção**: Vínculo jurídico que substitui a colocação em família
- **Prestação de Contas**: Medida para garantir o bem-estar do menor, permitindo supervisionar os interesses dos filhos ao não detentor da guarda
- **Guarda Unilateral**: Situação em que um dos genitores detém a guarda, obrigando o outro a supervisionar os interesses dos filhos
- **Ação de Prestação de Contas**: Procedimento especial para exigir contas de alguém que detém o direito de alimentação

### Referências legais
- Art. 47, § 7º, do Estatuto da Criança e do Adolescente; Art. 1.583, § 5º
- Código de Processo Civil de 1973 (arts. 914 a 919)

### Jurisprudência
- RE 123456
- Tema repetitivo: Ação de Prestação de Contas em face do outro genitor relativamente aos valores decorrentes de pensão alimentícia

### Dicas de prova
- Entenda o conceito de adoção e sua relação com a prestação de contas
- Conheça as regras para a ação de prestação de contas em face do outro genitor
- Análise da jurisprudência sobre a ação de prestação de contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.493 (1)", "page_number": 493, "discipline": "Direito Civil", "legal_refs": ["Art. 47, § 7º, do Estatuto da Criança e do Adolescente; Art. 1.583, § 5º", "Código de Processo Civil de 1973 (arts. 914 a 919)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ação de Prestação de Contas em face do outro genitor relativamente aos valores decorrentes de pensão alimentícia"], "confidence": 0.8, "extracted_at": "2026-05-26T03:32:07.680740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=493", "doc_key": "d369e0f507eb36bfd1b34fa63afe310b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '44b8106e4760be78c5002872c8788dde8b32fd08dd2e1f54788239c33694a2ae'),
  ('cpiuris2025::e8b33111d80b496f35e45636b08db635', 'doutrina', 'cp_iuris', 'Direito Civil — Contas de terceiro e ação de responsabilidade', '## Contas de terceiro e ação de responsabilidade

Ação proposta por quem deveria receber um balanço da administração de bens alheios, mas não recebeu.

### Conceitos
- **ação de responsabilidade**: ação proposta para exigir contas ou responsabilidade de alguém
- **contas de terceiro**: obrigação de prestar contas sobre a administração de bens alheios

### Referências legais
- Art. 1073 do Código Civil
- ...

### Jurisprudência
- REsp 1.911.030-PR
- REsp 1.767.456-MG

### Dicas de prova
- Entenda a diferença entre ação de responsabilidade e contas de terceiro.
- Conheça o interesse processual do alimentante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.493 (2)", "page_number": 493, "discipline": "Direito Civil", "legal_refs": ["Art. 1073 do Código Civil", "..."], "jurisprudence": ["REsp 1.911.030-PR", "REsp 1.767.456-MG"], "confidence": 0.8, "extracted_at": "2026-05-26T03:32:38.635354+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=493", "doc_key": "e8b33111d80b496f35e45636b08db635"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1c6cc352b7603bd10d95ed64d4366a04e6c32f382ef899a14b846978c40a751f'),
  ('cpiuris2025::17d70b0be41f02ff0f2ff63a1fecce95', 'doutrina', 'cp_iuris', 'Direito Civil — Litisconsórcio facultativo ulterior simples e obrigação alimentar', '## Litisconsórcio facultativo ulterior simples e obrigação alimentar

A obrigação alimentar é considerada divisível e não solidária. O credor de alimentos pode provocar a integração posterior do polo passivo, mas apenas se tem plena capacidade processual.

### Conceitos
- **Litisconsórcio facultativo ulterior simples**: Condição em que os coobrigados podem ser adicionados ao processo sem necessidade de uma ação separada
- **Obrigação alimentar**: Direito do credor de alimentos para receber apoio financeiro do devedor
- **Divisibilidade da obrigação alimentar**: Condição em que a obrigação é distribuída entre os coobrigados, cada um armando apenas sua parte

### Referências legais
- Art. 1.698 do CC/02

### Dicas de prova
- Entenda a distinção entre divisibilidade e solidariedade da obrigação alimentar
- Conheça as regras para a integração posterior do polo passivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.494 (1)", "page_number": 494, "discipline": "Direito Civil", "legal_refs": ["Art. 1.698 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:33:09.116830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=494", "doc_key": "17d70b0be41f02ff0f2ff63a1fecce95"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3b6ff03982053d2743ea6a3953062085d65f6f2534c5c5f2574de861f6762419'),
  ('cpiuris2025::7e8ca6ef247ede6d9b20db29db3a0f60', 'doutrina', 'cp_iuris', 'Direito Civil — Provisão da Provocação do Ministério Público', '## Provisão da Provocação do Ministério Público

A ausência de manifestação dos legitimados pode causar prejuízos ao incapaz, permitindo a provocação do ministério público.

### Conceitos
- **Provocação do Ministério Público**: Ação do ministério público para proteger os interesses de um incapaz
- **Legitimados**: Parties envolvidas no processo que podem chamar ao processo outros coobrigados
- **Obrigação Alimentar**: Dever de prestação de alimentos necessários a uma pessoa incapaz
- **Coobrigado**: Parte que compartilha a obrigação de pagar uma dívida ou realizar um dever com outra parte
- **Contestação**: Resposta do réu ao processo, negando as alegações do autor
- **Réplica**: Resposta do autor à contestação do réu

### Referências legais
- Art. 319 do Código de Processo Civil
- Súmula 242 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Resp 1.715.438-rs

### Dicas de prova
- Distinção entre a provocação do ministério público e a contestação
- Importância da constatação de que os genitores estão absolutamente impossibilitados de prestá-los de forma suficiente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.494 (2)", "page_number": 494, "discipline": "Direito Civil", "legal_refs": ["Art. 319 do Código de Processo Civil", "Súmula 242 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Resp 1.715.438-rs"], "confidence": 0.8, "extracted_at": "2026-05-26T03:33:47.007264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=494", "doc_key": "7e8ca6ef247ede6d9b20db29db3a0f60"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1fc173a1377615d2eca46d963ea0a2318ac9a9d0898268679adc632993aab6bd'),
  ('cpiuris2025::230456744d73bcf5546bcfaba53d1699', 'doutrina', 'cp_iuris', 'Direito Civil — Conversão de alimentos gravídicos em pensão alimentícia', '## Conversão de alimentos gravídicos em pensão alimentícia

A ação de alimentos gravídicos não se extingue com o nascimento da criança, e os alimentos concedidos à gestante são convertidos automaticamente em pensão alimentícia em favor do recém-nascido, sem necessidade de pronunciamento judicial.

### Conceitos
- **Conversão automática**: Ocorre sem necessidade de pronunciamento judicial
- **Pensão alimentícia**: Alimento concedido a uma pessoa, geralmente para sustentar um menor
- **Alimentos gravídicos**: Alimentos concedidos à gestante durante a gravidez
- **Ação de alimentos**: Procedimento judicial que visa garantir o sustento de uma pessoa

### Referências legais
- Art. 805 do CPC/15
- Parágrafo único do Artigo 6º da Lei n 11.804/2008

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre alimentos gravídicos e pensão alimentícia
- Conheça o prazo para solicitar a revisão da pensão alimentícia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.495 (1)", "page_number": 495, "discipline": "Direito Civil", "legal_refs": ["Art. 805 do CPC/15", "Parágrafo único do Artigo 6º da Lei n 11.804/2008"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T03:34:31.265675+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=495", "doc_key": "230456744d73bcf5546bcfaba53d1699"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c6a4ce087a031edeef0473e9d4f3b82db667865a576b1c00fd3abc3402964b39'),
  ('cpiuris2025::8c6e61e509903ec79a44d9dcff3a03c1', 'doutrina', 'cp_iuris', 'Direito Civil — Pensão Alimentícia Provisória e Tutela/ Curatela', '## Pensão Alimentícia Provisória e Tutela/ Curatela

A concessão de pensão alimentícia provisória ao menor durante o trâmite da ação de investigação de paternidade exige indícios mínimos de paternidade. A lei busca garantir o melhor interesse do menor, com a conversão automática da obrigação e transferência da titularidade dos alimentos.

### Conceitos
- **Paternidade**: Relação jurídica entre pai e filho
- **Alimentação**: Direito à subsistência básica
- **Tutela**: Proteção dos interesses de uma pessoa menor não emancipada
- **Curatela**: Proteção do maior em situações excepcionais
- **Estatuto da Pessoa com Deficiência**: Lei que promoveu alterações em matéria de capacidade da pessoa maior de 18 anos
- **Capacidade jurídica**: Habilidade para contrair e cumprir obrigações jurídicas
- **Emancipação**: Ato que confere à pessoa maior a capacidade jurídica plena
- **Obrigação alimentar**: Direito de uma pessoa a receber alimentos de outra

### Referências legais
- Art. 6º, caput, da Lei n. 11.804/2008

### Dicas de prova
- Distinção entre tutela e curatela
- Importância dos indícios de paternidade na concessão de pensão alimentícia provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.495 (2)", "page_number": 495, "discipline": "Direito Civil", "legal_refs": ["Art. 6º, caput, da Lei n. 11.804/2008"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:35:13.114453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=495", "doc_key": "8c6e61e509903ec79a44d9dcff3a03c1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c4062f78fd32b52ae7d27a512c014c3b877e8560b3d86391a6450c405557be88'),
  ('cpiuris2025::dc1cefdbf65416513e5ea381af773396', 'doutrina', 'cp_iuris', 'Direito Civil — Tutela em Direito das Famílias', '## Tutela em Direito das Famílias

A tutela é instituto jurídico que se aplica quando há perda ou suspensão do poder familiar dos pais, sendo exercida por um tutor. A tutela pode ser dividida em três categorias: testamentária, legítima e dativa.

### Conceitos
- **Tutela**: Instituto jurídico que se aplica quando há perda ou suspensão do poder familiar dos pais
- **Poder familiar**: Direito dos pais sobre os filhos
- **Tutoria**: Exercício da tutela pelo tutor
- **Tutela testamentária**: Decorre da manifestação em testamento, nomeando um tutor para a hipótese de falecimento dos pais
- **Tutela legítima**: Decorre da previsão da lei quando não há nomeação testamentária de tutor e a criança ou adolescente está órfão ou não sob o poder familiar dos genitores
- **Tutela dativa**: Nomeado pelo juiz quando não há parentes ou tutela legítima
- **Princípio da unicidade da tutela**: Não podem ser tutores mais de um, caso a legislação prevê a nomeação de apenas um tutor para todos

### Referências legais
- Art. 1.728/CC
- Art. 1.731/CC
- Art. 1.733/CC
- Art. 1.735/CC
- Art. 1.736/CC

### Dicas de prova
- Entenda a diferença entre tutela testamentária, legítima e dativa
- Conheça o princípio da unicidade da tutela
- Identifique as pessoas que não podem ser tutores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.496", "page_number": 496, "discipline": "Direito Civil", "legal_refs": ["Art. 1.728/CC", "Art. 1.731/CC", "Art. 1.733/CC", "Art. 1.735/CC", "Art. 1.736/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:36:00.500738+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=496", "doc_key": "dc1cefdbf65416513e5ea381af773396"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd06b9a5dc9fc4784f7fcb553f5fffa0e3643bc5e10ed0c9408f8ad883b4c88ff'),
  ('cpiuris2025::a08925b75376f581ffff8a5936a54ffd', 'doutrina', 'cp_iuris', 'Direito Civil — Tutela dos Menores', '## Tutela dos Menores

Rege-se a tutela dos menores com base em critérios específicos, como idade, condição física e capacidade de exercer o múnus. O tutor é responsável por atender às necessidades do menor, sendo ele nomeado ou não.

### Conceitos
- **tutela dos menores**: proteção legal do menor
- **nomeado tutor**: pessoa nomeada para exercer a tutela do menor
- **escusa**: recusa da nomeação como tutor
- **prazo decadencial**: período durante o qual deve ser feita a manifestação de escusa
- **incumbências do tutor**: obrigações e responsabilidades do tutor em relação ao menor

### Referências legais
- Art. 1.737/CC
- Art. 1.738/CC
- Art. 1.740/CC
- Art. 1.742/CC
- Art. 1.744/CC
- Art. 1.745/CC
- Art. 1.746/CC
- Art. 1.747/CC
- Art. 1.748/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da idade como critério para nomeação do tutor.
- Conheça as incumbências do tutor e as responsabilidades em relação ao menor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.497", "page_number": 497, "discipline": "Direito Civil", "legal_refs": ["Art. 1.737/CC", "Art. 1.738/CC", "Art. 1.740/CC", "Art. 1.742/CC", "Art. 1.744/CC", "Art. 1.745/CC", "Art. 1.746/CC", "Art. 1.747/CC", "Art. 1.748/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T03:36:48.693459+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=497", "doc_key": "a08925b75376f581ffff8a5936a54ffd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'efaada567f6b8f0e67c4d8842b580aab7ec429b851e560565670feb4504f55b7'),
  ('cpiuris2025::fecf4e3dab4e9c710feb2817ad2029f5', 'doutrina', 'cp_iuris', 'Direito Civil — Tutela de Menores', '## Tutela de Menores

O tutor tem responsabilidade pelos prejuízos causados ao tutelado, seja por culpa ou dolo, e responde objetivamente por atos do tutelado em face de terceiros. O tutor também tem direito a ser pago pelo que gastou com a tutela e tem o direito de reembolso.

### Conceitos
- **Tutela de Menores**: A responsabilidade do tutor em relação ao menor sob sua tutela
- **Responsabilidade Subjetiva**: O dever de responder pelos prejuízos causados ao tutelado por culpa ou dolo
- **Responsabilidade Objetiva**: A responsabilidade do tutor por atos do tutelado em face de terceiros, sem a necessidade de prova da culpa
- **Direito de Reembolso**: O direito do tutor a ser pago pelo que gastou com a tutela
- **Tutela Patrimonial**: A responsabilidade do tutor em relação aos bens do menor sob sua tutela

### Referências legais
- Art. 1.749/CC
- Art. 1.752/CC
- Art. 1.755/CC

### Dicas de prova
- Distinção entre responsabilidade subjetiva e objetiva
- Importância do direito de reembolso para o tutor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.498 (1)", "page_number": 498, "discipline": "Direito Civil", "legal_refs": ["Art. 1.749/CC", "Art. 1.752/CC", "Art. 1.755/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:37:23.775994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=498", "doc_key": "fecf4e3dab4e9c710feb2817ad2029f5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b261d59edaa3f8a24867408719759891c033d4bd31ba0981f75b4325d2a15274'),
  ('cpiuris2025::6a739bc01152ab40d99814af5930f99f', 'doutrina', 'cp_iuris', 'Direito Civil — Tutela e Prestação de Contas', '## Tutela e Prestação de Contas

A legislação prevê a apresentação de contas ao juiz a cada dois anos, após o encerramento da tutela. A competência depende da Lei de Organização Judiciária e é regulada pelo art. 1.763/CC.

### Conceitos
- **Tutela**: proteção jurídica do menor ou incapaz
- **Prestação de Contas**: apresentação das contas ao juiz após o encerramento da tutela
- **Competência**: esfera jurisdicional responsável pela tutela

### Referências legais
- Art. 1.763/CC

### Dicas de prova
- Entenda a competência e o procedimento de prestação de contas
- Conheça as situações que ensejam extinção da tutela', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.498 (2)", "page_number": 498, "discipline": "Direito Civil", "legal_refs": ["Art. 1.763/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:37:45.022203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=498", "doc_key": "6a739bc01152ab40d99814af5930f99f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c74ced991f3f1dc9fba3f200d80e7416f9a087b37c877c48e5b7c808f484a634'),
  ('cpiuris2025::c8850400d75f501a4a0707e2e04a9a82', 'doutrina', 'cp_iuris', 'Direito Civil — Tutela e Curatela', '## Tutela e Curatela

O texto discute as diferenças entre tutela e curatela, destacando que a tutela é para menores de idade e a curatela é para maiores incapazes. Além disso, aborda as hipóteses em que a curatela pode ser concedida.

### Conceitos
- **Tutela**: Instituto que visa proteger menores de idade
- **Curatela**: Instituto que visa defender maiores incapazes
- **Poder familiar**: Direção e autoridade do pai e da mãe sobre os filhos
- **Tutela de órfão**: Concedida aos órfãos após a destituição do poder familiar
- **Curatela em relação a maiores incapazes**: Somente aplicável em situações especificadas em lei

### Referências legais
- Art. 1.764/CC
- Art. 1.761/CC
- Art. 1.766/CC
- Art. 1.765/CC

### Dicas de prova
- Diferenciar entre tutela e curatela
- Entender as hipóteses em que a curatela pode ser concedida
- Conhecer o sistema de proteção assistencial dos maiores incapazes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.499", "page_number": 499, "discipline": "Direito Civil", "legal_refs": ["Art. 1.764/CC", "Art. 1.761/CC", "Art. 1.766/CC", "Art. 1.765/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:38:34.806890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=499", "doc_key": "c8850400d75f501a4a0707e2e04a9a82"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '756aa689e96b8f148c8524663976160898dd1c0f12594edb9fbb3410fd704b73'),
  ('cpiuris2025::a25c20b8b525c7b9d1da2a69dc1f1a56', 'doutrina', 'cp_iuris', 'Direito Civil — Incapacidade e Curatela', '## Incapacidade e Curatela

A incapacidade é matéria de ordem pública e não se presume, exigindo ação própria para sua constatação e tomada de providências. A curatela pode ser promovida por legítimos indicados pelo artigo 747 do CPC, incluindo o Ministério Público, que tem legitimidade subsidiária.

### Conceitos
- **Incapacidade**: Falta de capacidade para se exercer direitos e obrigações
- **Curatela**: Intervenção do juiz no gerenciamento das questões de vida de uma pessoa incapaz
- **Legitimidade**: Direito de alguém para agir em nome de outro
- **Ordem Pública**: Direito que protege a ordem social e a estabilidade do Estado

### Referências legais
- Art. 747 do CPC
- Estatuto do Deficiente
- Art. 1.768 do CC

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre incapacidade e curatela
- Conheça os legítimos indicados para promover ação de curatela
- Avalie a legitimidade do Ministério Público na promoção da ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.500", "page_number": 500, "discipline": "Direito Civil", "legal_refs": ["Art. 747 do CPC", "Estatuto do Deficiente", "Art. 1.768 do CC"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T03:39:12.188399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=500", "doc_key": "a25c20b8b525c7b9d1da2a69dc1f1a56"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '50b5f2590bea714dffb51544a1821cc89892886aaa852eb38a554961c659a873'),
  ('cpiuris2025::e0f4db0415c9f2b2547c2cf774d703d4', 'doutrina', 'cp_iuris', 'Direito Civil — Curatela', '## Curatela

O juiz determinará a produção de prova pericial para avaliar a efetiva situação do curatelando. O laudo pericial indicará para quais atos que o curatelado necessitará da participação do curador.

### Conceitos
- **Curatela**: Exercício de direitos e responsabilidades por uma pessoa incapaz
- **Cura**: Pessoa nomeada para cuidar e representar um incapaz
- **Prova pericial**: Laudo técnico que avalia a situação do curatelando
- **Limites da curatela**: Definição dos direitos e responsabilidades do curador em relação ao curtelado
- **Art. 1.775/CC**: Estabelece a ordem de preferência para a nomeação do curador

### Referências legais
- Art. 1.775/CC
- Art. 754/NCPC
- Art. 757/NCPC

### Dicas de prova
- Entenda a ordem de preferência para a nomeação do curador
- Conheça as limitações e direitos da curatela', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.501 (1)", "page_number": 501, "discipline": "Direito Civil", "legal_refs": ["Art. 1.775/CC", "Art. 754/NCPC", "Art. 757/NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:39:44.013988+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=501", "doc_key": "e0f4db0415c9f2b2547c2cf774d703d4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f2a6d21eb84c2dc461761308822b61eb4bd4f9264b5bdeed4f06c9fc84ef0a56'),
  ('cpiuris2025::3feabb2fa53f26ed9402cc64332c317c', 'doutrina', 'cp_iuris', 'Direito Civil — Curatela e Tutela', '## Curatela e Tutela

Regras sobre curadoria de menores, princípio da unicidade de curatela/tutela e publicidade das sentenças de interdição.

### Conceitos
- **Curatela**: Fatores que determinam a necessidade de tutela
- **Tutela**: Responsabilidade do curador pelo menor
- **Princípio da unicidade de curatela/tutela**: Sob a responsabilidade única do curador
- **Publicidade das sentenças de interdição**: Regulamentação da inscrição e divulgação das decisões

### Referências legais
- Art. 755, §3º do NCPC

### Dicas de prova
- Entenda o princípio da unicidade de curatela/tutela
- Conheça as regras sobre a publicidade das sentenças de interdição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.501 (2)", "page_number": 501, "discipline": "Direito Civil", "legal_refs": ["Art. 755, §3º do NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:40:18.195102+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=501", "doc_key": "3feabb2fa53f26ed9402cc64332c317c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '38bd6a4aa5c9471731d1083c1be619e6b044b4e2f5c17b74bafc3c8e2b696217'),
  ('cpiuris2025::473ccf3c58763f8dc446cd1fbbb5ae45', 'doutrina', 'cp_iuris', 'Direito Civil — Curatela e Tutela das Pessoas com Deficiência', '## Curatela e Tutela das Pessoas com Deficiência

A curatela é instituto que busca auxiliar pessoas com deficiência, com efeitos ex nunc desde a sentença de interdição. A tomada de decisão apoiada é um processo que visa auxiliar essas pessoas, com regras específicas no Código Civil.

### Conceitos
- **Curatela**: Instituto que busca auxiliar pessoas com deficiência
- **Efeitos ex nunc**: Sentença de interdição produz efeitos desde o momento da sentença
- **Tomada de decisão apoiada**: Processo que visa auxiliar pessoas com deficiência

### Referências legais
- Art. 758 do NCPC
- Art. 115 do Estatuto da Pessoa com Deficiência
- Art. 1.783-A do Código Civil

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre curatela e tutela
- Conheça o conceito de efeitos ex nunc
- Aprenda sobre a tomada de decisão apoiada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.502 (1)", "page_number": 502, "discipline": "Direito Civil", "legal_refs": ["Art. 758 do NCPC", "Art. 115 do Estatuto da Pessoa com Deficiência", "Art. 1.783-A do Código Civil"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T03:40:50.842958+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=502", "doc_key": "473ccf3c58763f8dc446cd1fbbb5ae45"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '76882e5c975d9ea7627530fc1b33789776288284c20caedf57a7b900ed27f5cb'),
  ('cpiuris2025::28291114f61dd6883de68b7bc2f69c49', 'doutrina', 'cp_iuris', 'Direito Civil — Tomada de Decisão Apoiada', '## Tomada de Decisão Apoiada

Instituto que permite a pessoa com deficiência ter apoio em decisões sobre atos da vida civil.

### Conceitos
- **Pessoa com deficiência**: Física ou mental
- **Tomada de decisão apoiada**: Processo que permite a pessoa com deficiência ter apoio em decisões
- **Apoiadores**: Pessoas idôneas que gozem da confiança da pessoa com deficiência
- **Vínculos**: Relacionamentos estabelecidos com as pessoas que apoiam a pessoa com deficiência

### Referências legais
- Art. 1.783-A, CC

### Dicas de prova
- Entenda o conceito de tomada de decisão apoiada e seus requisitos.
- Conheça a importância dos vínculos estabelecidos com os apoiores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.502 (2)", "page_number": 502, "discipline": "Direito Civil", "legal_refs": ["Art. 1.783-A, CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:41:14.105136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=502", "doc_key": "28291114f61dd6883de68b7bc2f69c49"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4db78dd282094af0fe5877702417a34dbf0b7bc934117890a28f2b9066016494'),
  ('cpiuris2025::f88bfbb3976b7e2e655160c4929152d4', 'doutrina', 'cp_iuris', 'Direito Civil — Tomada de Decisão Apoiada', '## Tomada de Decisão Apoiada

A tomada de decisão apoiada é um regime jurídico que permite a pessoa com deficiência tomar decisões sobre sua vida, com o apoio de pessoas aptas a prestarem apoio. O pedido de tomada de decisão é feito pela pessoa que deseja ser apoiada e deve ser ouvido pessoalmente pelo juiz antes de se decidir.

### Conceitos
- **Tomada de Decisão Apoiada**: Um regime jurídico que permite a pessoa com deficiência tomar decisões sobre sua vida, com o apoio de pessoas aptas a prestarem apoio.
- **Apoio**: Pessoas aptas a prestar apoio à pessoa com deficiência.
- **Curatela**: Um regime jurídico que permite a intervenção do juiz na vida da pessoa com deficiência, quando considerada incapaz.
- **Vontade**: A escolha livre e consciente de uma pessoa sobre sua vida ou decisões.
- **Obrigação**: Um dever ou responsabilidade que alguém deve cumprir.
- **Divergência**: Uma situação em que as partes têm opiniões diferentes.
- **Intervenção do Juiz**: A ação do juiz para resolver uma disputa ou problema.
- **Denúncia**: O ato de denunciar algo, geralmente a um autoridade.

### Referências legais
- Art. 1.783-A do Código Civil
- Súmula 639 da Jornada de Direito Civil - CJF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre tomada de decisão apoiada e curatela.
- Conheça as regras para o pedido de tomada de decisão apoiada.
- Aprenda a identificar a vontade da pessoa com deficiência em relação ao apoio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.503 (1)", "page_number": 503, "discipline": "Direito Civil", "legal_refs": ["Art. 1.783-A do Código Civil", "Súmula 639 da Jornada de Direito Civil - CJF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T03:42:12.773677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=503", "doc_key": "f88bfbb3976b7e2e655160c4929152d4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0eac8dfd1a33a702d4c906d96880bef83581515a03bf68e2b09780294899df74'),
  ('cpiuris2025::6b72e22985a2986cda614c10ace7db2b', 'doutrina', 'cp_iuris', 'Direito Civil — Legitados para ação de levantamento de curatela', '## Legitados para ação de levantamento de curatela

O art. 756, §1º, do CPC/2015 não é taxativo e ampliou o rol de legitimados para ajuizamento da ação de levantamento da curatela, permitindo que o curador e o Ministério Público sejam legitimados além do interdito.

### Conceitos
- **Legitados**: Pessoas autorizadas a ajuizar uma ação
- **Curatela**: Situação em que alguém é nomeado curador de outrem
- **Interdito**: Pessoa que se vê impedida de exercer seus direitos
- **CPC/2015**: Código de Processo Civil de 2015

### Referências legais
- Art. 756, §1º, do CPC/2015

### Dicas de prova
- Entenda a noção de legitimados e curatela
- Conheça o contexto histórico do artigo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.503 (2)", "page_number": 503, "discipline": "Direito Civil", "legal_refs": ["Art. 756, §1º, do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:42:37.504870+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=503", "doc_key": "6b72e22985a2986cda614c10ace7db2b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '95204e58bd8ed0c08e0f9c4151656a2ed1699eb04cd5993b639451b0fde4c1a8'),
  ('cpiuris2025::5654a6ad873a7abd27617ad007e62e56', 'doutrina', 'cp_iuris', 'Direito Civil — Autonomia em ações de levantamento da curatela', '## Autonomia em ações de levantamento da curatela

A autonomia em ações de levantamento da curatela não se aplica quando houver causa que justifique a interdição, mas não exclui a possibilidade de outras pessoas terem legitimidade para pleitear o levantamento. A ausência de interrogatório e nomeação de curador à lide podem dar ensejo à nulidade do processo de interdição.

### Conceitos
- **Autonomia**: Direito do indivíduo a tomar suas próprias decisões
- **Curatela**: Intervenção judicial para proteger os interesses de uma pessoa incapaz
- **Interrogatório**: Oportunidade do interditando responder às acusações feitas contra ele
- **Nomeação de curador**: Designação de uma pessoa para representar o interditando em um processo

### Referências legais
- Art. 1.105, do CPC/73
- Art. 129, IX, da Constituição

### Jurisprudência
- REsp 1.735.668-MT
- Tema repetitivo

### Dicas de prova
- Diferenciar entre autonomia e intervenção ministerial em ações de levantamento da curatela
- Entender a importância do interrogatório e da nomeação de curador à lide no processo de interdição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.504 (1)", "page_number": 504, "discipline": "Direito Civil", "legal_refs": ["Art. 1.105, do CPC/73", "Art. 129, IX, da Constituição"], "jurisprudence": ["REsp 1.735.668-MT", "Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-26T03:43:19.563156+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=504", "doc_key": "5654a6ad873a7abd27617ad007e62e56"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '88dcd0309c8ea60ff352c93b54daa133887056b734ca776e92edbaaa29d1f27c'),
  ('cpiuris2025::4cdde5edb50404cb6de7eb2219120680', 'doutrina', 'cp_iuris', 'Direito Civil — Curadoria Especial e Defensoria Pública', '## Curadoria Especial e Defensoria Pública

A curadoria especial é função da Defensoria Pública para evitar incompatibilidade de funções entre fiscalização da lei e interesses particulares. A Lei Complementar n. 80/1994 e o Código de Processo Civil de 2015 endossam esse entendimento, retirando a participação do Ministério Público no processo de interdição.

### Conceitos
- **Curadoria Especial**: Função da Defensoria Pública para evitar incompatibilidade de funções
- **Defensoria Pública**: Entidade responsável pela curadoria especial
- **Interdição**: Processo que visa proteger os interesses de uma pessoa incapaz
- **Nulidade Absoluta**: Condição em que o processo de interdição é considerado nulo
- **Interrogatório**: Exame pessoal do interditando pelo juiz para garantir sua defesa

### Referências legais
- Art. 4º, XVI da Lei Complementar n. 80/1994
- Art. 72, parágrafo único do Código de Processo Civil de 2015
- Art. 1.109 do CPC/73

### Jurisprudência
- REsp 1.686.161-SP
- Súmula N da STF

### Dicas de prova
- Distinção entre curadoria especial e defensoria pública
- Importância do interrogatório para garantir a defesa do interditando
- Consequências da nulidade absoluta do processo de interdição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.504 (2)", "page_number": 504, "discipline": "Direito Civil", "legal_refs": ["Art. 4º, XVI da Lei Complementar n. 80/1994", "Art. 72, parágrafo único do Código de Processo Civil de 2015", "Art. 1.109 do CPC/73"], "jurisprudence": ["REsp 1.686.161-SP", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-26T03:44:12.889502+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=504", "doc_key": "4cdde5edb50404cb6de7eb2219120680"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd551b91c66442be9ee41ec4e0b3f314728afba8e42e5e8f0b934e24771358cac'),
  ('cpiuris2025::4f36f13ad27d485884df37a9af95cbac', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento da União Estável como Entidade Familiar', '## Reconhecimento da União Estável como Entidade Familiar

A Constituição Federal de 1988 foi um marco importante no reconhecimento da união estável como entidade familiar, mas ainda houve um longo caminho até a configuração atual que reconhece igualmente a união de pessoas do mesmo sexo.

### Conceitos
- **Entidade Familiar**: Conformidade com o reconhecimento legal da união estável como família
- **Sociedade de Fato**: Relação entre pessoas que não estão casadas, mas mantêm um vínculo econômico e emocional
- **Constituição Federal de 1988**: Lei que reconheceu a união estável como entidade familiar

### Referências legais
- Art. 2260 do Código Civil
- Súmula 373 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 123456
- Tema repetitivo: União Estável

### Dicas de prova
- Entenda a evolução da legislação sobre união estável
- Conheça as diferenças entre sociedade de fato e entidade familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.505 (1)", "page_number": 505, "discipline": "Direito Civil", "legal_refs": ["Art. 2260 do Código Civil", "Súmula 373 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 123456", "Tema repetitivo: União Estável"], "confidence": 0.8, "extracted_at": "2026-05-26T03:44:45.033144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=505", "doc_key": "4f36f13ad27d485884df37a9af95cbac"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '801c5eef4267c5887d46fbdd13ac7b5b326bafe63cb8e9395888bb3a50117a9b'),
  ('cpiuris2025::bf1c78bfcfdfdba878313b2800e3da7d', 'doutrina', 'cp_iuris', 'Direito Civil — Divórcio e Concubinato', '## Divórcio e Concubinato

Descreve a aplicação da Súmula 380 do STF em casos de concubinato não reconhecido pela lei, permitindo a dissolução judicial com partilha do patrimônio.

### Conceitos
- **Concubinato**: Relação de convivência entre duas pessoas casadas ou não casadas
- **Súmula 380 do STF**: Estabelece a possibilidade de dissolução judicial da sociedade de fato em casos de concubinato

### Referências legais
- Art. 1.629 do Código Civil de 1910
- Súmula 380 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Dissolução judicial de sociedades de fato em concubinato

### Dicas de prova
- Entenda a diferença entre divórcio e concubinato
- Conheça a Súmula 380 do STF e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.505 (2)", "page_number": 505, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 do Código Civil de 1910", "Súmula 380 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Dissolução judicial de sociedades de fato em concubinato"], "confidence": 0.8, "extracted_at": "2026-05-26T03:45:10.343826+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=505", "doc_key": "bf1c78bfcfdfdba878313b2800e3da7d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e835b82202be2d30a666b8488db43d9c0808e43df73cba47da57acbb5242fb6e'),
  ('cpiuris2025::6e07341a3eecb6cb90f643127c656bc8', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento das Uniões Estáveis como Entidade Familiar', '## Reconhecimento das Uniões Estáveis como Entidade Familiar

A Constituição Federal de 1988 estabeleceu a união estável como entidade familiar, mas houve discussão sobre sua aplicabilidade imediata. A regulamentação veio com leis posteriores, como a Lei nº 8.971/94 e a Lei nº 9.278/96.

### Conceitos
- **Entidade Familiar**: Conceito jurídico que define a união estável como uma entidade familiar reconhecida pelo Estado.
- **Uniões Estáveis**: Relações de natureza conjugal não casadas, reconhecidas como entidades familiares pela lei.
- **Alimentos**: Direito dos companheiros à subsistência mútua, estabelecido pela Lei nº 8.971/94.
- **Participação na Sucessão**: Direito dos companheiros à participação na sucessão do outro, estabelecido pela Lei nº 8.971/94.
- **Usufruto**: Direito dos companheiros ao usufruto sobre a propriedade conjunta, estabelecido pela Lei nº 8.971/94.

### Referências legais
- Art. 226, §3º, da Constituição Federal de 1988
- Lei nº 8.971/94
- Lei nº 9.278/96

### Dicas de prova
- Entenda a distinção entre uniões estáveis e casamentos.
- Conheça as leis que regulamentaram o reconhecimento das uniões estáveis como entidade familiar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.506 (1)", "page_number": 506, "discipline": "Direito Civil", "legal_refs": ["Art. 226, §3º, da Constituição Federal de 1988", "Lei nº 8.971/94", "Lei nº 9.278/96"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:46:03.133441+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=506", "doc_key": "6e07341a3eecb6cb90f643127c656bc8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e407cc5f2b13afe92618854fb1ee72a2e94226c2cdf50c22bc25a1b3209f60b0'),
  ('cpiuris2025::471d0e7adfb65352c0c0b6e3e853e4dd', 'doutrina', 'cp_iuris', 'Direito Civil — Requisitos para União Estável', '## Requisitos para União Estável

A lei estabelece um requisito temporal de cinco anos de convivência para a configuração da união estável, salvo se houver filhos em comum.

### Conceitos
- **União Estável**: Condição jurídica que caracteriza a estabilidade de uma relação entre um homem e uma mulher
- **Prazo Mínimo**: Requisito temporal de cinco anos de convivência para a configuração da união estável
- **Filhos em Comum**: Exigência que não há necessidade de prazo mínimo quando houver filhos em comum

### Referências legais
- Art. 1º da Lei nº 5.478/1968

### Jurisprudência
- STJ, REsp 855.963/PR
- Súmula 194 STJ

### Dicas de prova
- Entenda o conceito de união estável e seus requisitos.
- Identifique a exceção ao prazo mínimo quando houver filhos em comum.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.506 (2)", "page_number": 506, "discipline": "Direito Civil", "legal_refs": ["Art. 1º da Lei nº 5.478/1968"], "jurisprudence": ["STJ, REsp 855.963/PR", "Súmula 194 STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T03:46:27.759485+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=506", "doc_key": "471d0e7adfb65352c0c0b6e3e853e4dd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '53513a0da2c1a1c883b270bd771c03bf51db3c590e4dd8fe636c6055ce460512'),
  ('cpiuris2025::04628f303b73dd8d3f2de1ef796986e0', 'doutrina', 'cp_iuris', 'Direito das Famílias — Reconhecimento da União Estável', '## Reconhecimento da União Estável

A Lei nº 9.278/96 e o Código Civil de 2002 estabeleceram requisitos para a configuração da união estável, que inclui convivência duradoura, pública e contínua, com objetivo de constituição de família.

### Conceitos
- **União Estável**: Configuração de convivência duradoura, pública e contínua entre um homem e uma mulher, com objetivo de constituição de família
- **Convivência Duradoura**: Prazo mínimo para reconhecimento da união estável excluído
- **Convivência Pública**: Requisito para a configuração da união estável
- **Convivência Contínua**: Requisito para a configuração da união estável
- **Objetivo de Constituição de Família**: Motivo pelo qual a união estável é configurada
- **Presunção Relativa de Condomínio**: Direito que se aplica às partes iguais dos bens adquiridos a título oneroso na constância do relacionamento
- **Impedimentos para Reconhecimento da União Estável**: Art. 1.521 e art. 1.523

### Referências legais
- Art. 1º da Lei nº 9.278/96
- Art. 5º da Lei nº 9.278/96
- Art. 1.723 do Código Civil de 2002

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de união estável e seus requisitos
- Conheça os impedimentos para reconhecimento da união estável
- Aprenda sobre a presunção relativa de condomínio em relação aos bens adquiridos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.507 (1)", "page_number": 507, "discipline": "Direito das Famílias", "legal_refs": ["Art. 1º da Lei nº 9.278/96", "Art. 5º da Lei nº 9.278/96", "Art. 1.723 do Código Civil de 2002"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T03:47:13.541441+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=507", "doc_key": "04628f303b73dd8d3f2de1ef796986e0"}'::jsonb, '{"materia": "Direito das Famílias"}'::jsonb, 'cp_iuris_2025', 'b8381671e5d5ae1fca87de8cabc792496fce3203d8c2e1917a3061fe01bc87fd'),
  ('cpiuris2025::3e86a049e203a02a76a1995357e00fa5', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessão de Bens em Uniões Conjugais e Companheiras', '## Sucessão de Bens em Uniões Conjugais e Companheiras

O Código Civil manteve o direito de participação do(a) companheiro(a) na sucessão do outro, mas não disciplinou de forma igual a cônjuges. A jurisprudência equiparou cônjuges e companheiros para fins de sucessão.

### Conceitos
- **Comunhão Parcial de Bens**: Regime que regerá os bens do casal
- **Sucessão dos Companheiros**: Direito de participação do(a) companheiro(a) na sucessão do outro
- **Sucessão dos Cônjuges**: Direito de participação do cônjugue na sucessão do outro, equiparado aos companheiros
- **Lei nº 9.278/96**: Lei que conferia expressamente o direito real de habitação ao(a) companheiro(a)
- **Código Civil de 2002**: CC/02, que não disciplinou a sucessão dos companheiros
- **Art. 1.725/CC**: Regime que regerá os bens do casal

### Referências legais
- Art. 1.725/CC

### Jurisprudência
- RE 646.721
- RE 878.694

### Dicas de prova
- Distinção entre cônjuges e companheiros para fins de sucessão
- Reconhecimento da inconstitucionalidade do artigo 1.790 pelo STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.507 (2)", "page_number": 507, "discipline": "Direito Civil", "legal_refs": ["Art. 1.725/CC"], "jurisprudence": ["RE 646.721", "RE 878.694"], "confidence": 0.8, "extracted_at": "2026-05-26T03:47:59.462490+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=507", "doc_key": "3e86a049e203a02a76a1995357e00fa5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a35782e2e333dd88bcbcc4ef9153218a1f01716e8d7d7bd833e49410474bb08c'),
  ('cpiuris2025::96e67647b0c5e3beef276007b95f78bc', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento de Uniões Homoafetivas e Uniões Poliafetivas', '## Reconhecimento de Uniões Homoafetivas e Uniões Poliafetivas

O Código Civil de 2002 não dispõe sobre uniões homoafetivas, mas a Constituição Federal garante o reconhecimento dessas uniões como entidades familiares. Além disso, o sistema pátrio não reconhece uniões poliafetivas.

### Conceitos
- **Uniões Homoafetivas**: Relações entre pessoas do mesmo sexo que são consideradas entidades familiares
- **Uniões Poliafetivas**: Relações entre mais de duas pessoas que não são reconhecidas pelo sistema pátrio
- **Conceituação da União Estável**: Requisitos necessários para a constituição de uma união estável, como convivência pública, continuidade e objetivos de formar família

### Referências legais
- Art. 226, §3º, da CF
- Art. 1.723/CC
- Resolução 175 do CNJ

### Jurisprudência
- ADI 4.277 e ADPF 132 (STF)
- Súmula do STJ sobre casamento direto de pessoas do mesmo sexo
- Pedido de Providências (PP 0001459-08.2016.2.00.0000) do CNJ

### Dicas de prova
- Distinção entre uniões homoafetivas e heterossexuais
- Requisitos para a constituição de uma união estável
- Evolução da união estável no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.508 (1)", "page_number": 508, "discipline": "Direito Civil", "legal_refs": ["Art. 226, §3º, da CF", "Art. 1.723/CC", "Resolução 175 do CNJ"], "jurisprudence": ["ADI 4.277 e ADPF 132 (STF)", "Súmula do STJ sobre casamento direto de pessoas do mesmo sexo", "Pedido de Providências (PP 0001459-08.2016.2.00.0000) do CNJ"], "confidence": 0.8, "extracted_at": "2026-05-26T03:48:39.871759+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=508", "doc_key": "96e67647b0c5e3beef276007b95f78bc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '128ab7f064a933ca7480c7c0a6bb123eda8deed829622d68ae5ddddcbab1ca92'),
  ('cpiuris2025::33fb3c9545b3e344c3e3a63741497409', 'doutrina', 'cp_iuris', 'Direito Civil — União Estável', '## União Estável

A união estável é considerada uma entidade familiar pela sociedade, caracterizada por convivência contínua e duradoura, com o objetivo de constituir família. A affectio maritalis é o elemento subjetivo da união estável.

### Conceitos
- **Affectio Maritalis**: O elemento subjetivo da união estável
- **Convivência contínua e duradoura**: Característica necessária para a configuração da união estável

### Referências legais
- Art. 1.521 CC
- Art. 1.723 CC

### Dicas de prova
- Entenda o conceito de Affectio Maritalis e sua importância na configuração da união estável.
- Diferencie a convivência contínua e duradoura de outros tipos de convivência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.508 (2)", "page_number": 508, "discipline": "Direito Civil", "legal_refs": ["Art. 1.521 CC", "Art. 1.723 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T03:49:02.450381+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=508", "doc_key": "33fb3c9545b3e344c3e3a63741497409"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '31aa3aabdab0b0321b777c2f99ac3efa6962f3a713936909e1b8dc2c591f302f'),
  ('cpiuris2025::4b592eaf5a369cdd4531edd26074f33b', 'doutrina', 'cp_iuris', 'Direito Civil — União Estável', '## União Estável

A união estável é uma relação conjugal que pode ser caracterizada judicialmente ou por separação de fato. Os companheiros podem constituir e reconhecer a união, salvo contrato escrito entre eles, aplicando-se ao regime da comunhão parcial de bens.

### Conceitos
- **União Estável**: Relação conjugal caracterizada judicialmente ou por separação de fato
- **Regime de Bens**: Aplicação do regime da comunhão parcial de bens às relações patrimoniais
- **Convivência**: Contrato entre companheiros para regular a relação patrimonial
- **Efeito Ex Nunc**: O regime de bens tem eficácia a partir da data da escritura pública

### Referências legais
- Art. 1.523 CC/2002
- Art. 1.639, § 2º CC/2002
- Art. 1.726 CC/2002
- Art. 1.727 CC/2002

### Jurisprudência
- ADI 4.277 STF
- ADPF 132 STF

### Dicas de prova
- Distinção entre união estável e convivência
- Efeito ex nunc do regime de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.509 (1)", "page_number": 509, "discipline": "Direito Civil", "legal_refs": ["Art. 1.523 CC/2002", "Art. 1.639, § 2º CC/2002", "Art. 1.726 CC/2002", "Art. 1.727 CC/2002"], "jurisprudence": ["ADI 4.277 STF", "ADPF 132 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T03:49:46.382418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=509", "doc_key": "4b592eaf5a369cdd4531edd26074f33b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd4388a47569976538f9fa906edf3b51651260d45ec1093ff2b752194c8d2fc6d'),
  ('cpiuris2025::9eeb7a8e75a0379a66660f5c8e791f45', 'doutrina', 'cp_iuris', 'Direito Civil — União Estável e Concubinato', '## União Estável e Concubinato

A união estável é protegida a título de entidade familiar, enquanto o concubinato ocorre quando há impedimento para casamento e união estável.

### Conceitos
- **União Estável**: Entidade familiar protegida pela lei
- **Concubinato**: Relação íntima que ocorre quando há impedimento para casamento e união estável
- **Sucessão**: Transmissão de bens de um devido ao outro, de acordo com a lei em vigor na data do óbito
- **Partilha**: Divisão dos bens entre os cônjuges ou cônjugas, observando o regime de bens e ordenamento jurídico vigente

### Referências legais
- Art. 1.629 do Código Civil
- Súmula 715/2021 do STJ

### Jurisprudência
- RE 123456
- AREsp 1.631.112-MT

### Dicas de prova
- Diferenciar entre união estável e concubinato
- Entender a importância da tese do STJ sobre a sucessão e a partilha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.509 (2)", "page_number": 509, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 do Código Civil", "Súmula 715/2021 do STJ"], "jurisprudence": ["RE 123456", "AREsp 1.631.112-MT"], "confidence": 0.8, "extracted_at": "2026-05-26T03:50:16.097274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=509", "doc_key": "9eeb7a8e75a0379a66660f5c8e791f45"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cda79f5d9ed9f726954fe0aa58b95464fc267a33e8a25b25ebd9aa8a6a638fe6'),
  ('cpiuris2025::fdeb391267f48f1b6507d6cb857ecf94', 'doutrina', 'cp_iuris', 'Direito Civil — Uniões Estáveis e Casamentos', '## Uniões Estáveis e Casamentos

Resumo objetivo: A legislação aplicada à partilha de bens em união estável deve ser a da data da aquisição do bem, independentemente da dissolução da união. Além disso, a coabitação não é elemento indispensável à caracterização da união estável, e a vara de família é competente para apreciar e julgar pedidos de reconhecimento e dissolução de uniões estáveis homoafetivas.

### Conceitos
- **Uniões Estáveis**: Relacionamento estável entre pessoas do mesmo sexo ou opostas sexos
- **Casamento**: Conjunção civil de duas pessoas, que pode ser válido ou não
- **Partilha de Bens**: Divisão dos bens adquiridos em comum durante o relacionamento
- **Coabitação**: Viver juntos
- **Vara de Família**: Autoridade judiciária competente para apreciar e julgar questões familiares

### Referências legais
- Art. 1.641, II, do CC/02

### Jurisprudência
- RE 123456
- ARE 1309642 - tema 1.236

### Dicas de prova
- Distinguir entre uniões estáveis e casamentos
- Entender a importância da data da aquisição do bem na partilha de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.510 (1)", "page_number": 510, "discipline": "Direito Civil", "legal_refs": ["Art. 1.641, II, do CC/02"], "jurisprudence": ["RE 123456", "ARE 1309642 - tema 1.236"], "confidence": 0.8, "extracted_at": "2026-05-26T03:50:51.555746+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=510", "doc_key": "fdeb391267f48f1b6507d6cb857ecf94"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4e9c0fc3a5839f2411157b5b27fb567c6cc5a0f75f7149a516f8223b361bb48e'),
  ('cpiuris2025::be6f1a1977266b1e918d4cfa3e1c0984', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento de Uniões Estáveis e Direito à Meação', '## Reconhecimento de Uniões Estáveis e Direito à Meação

O direito à meação é garantido às uniões homoafetivas, assim como às uniões estáveis heteroafetivas. Não há possibilidade de se pleitear indenização por serviços domésticos prestados com o fim do casamento ou da união estável.

### Conceitos
- **Meação**: Direito à propriedade conjugal
- **Uniões Estáveis**: Relações de afeto entre pessoas do mesmo sexo
- **Serviços Domésticos**: Trabalho prestado em uma residência

### Referências legais
- Art. 1.629 CC/2002
- Súmula 394 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Uniões Estáveis e Direito à Meação

### Dicas de prova
- Entenda a noção de meação e suas implicações para as uniões homoafetivas.
- Conheça a jurisprudência do STJ sobre a inaplicabilidade da indenização por serviços domésticos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.510 (2)", "page_number": 510, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 CC/2002", "Súmula 394 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Uniões Estáveis e Direito à Meação"], "confidence": 0.8, "extracted_at": "2026-05-26T03:51:27.681663+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=510", "doc_key": "be6f1a1977266b1e918d4cfa3e1c0984"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'df3b5450ade6600ed0e2dc324fd73ca64d7c30d9a8064e2796118b0e6e0e356b'),
  ('cpiuris2025::ef7745370af404f3ea9e74384ab7a26f', 'doutrina', 'cp_iuris', 'Direito Civil — União Estável e Namoro Qualificado', '## União Estável e Namoro Qualificado

A união estável é reconhecida pela convivência pública e duradoura com finalidade de constituir família, enquanto o namoro qualificado não tem como objetivo a constituição de família.

### Conceitos
- **União Estável**: Reconhecimento judicial da convivência pública e duradoura com finalidade de constituir família
- **Namoro Qualificado**: Convivência pública e duradoura sem finalidade de constituição de família
- **Objetivo do Casal**: Ponto central para a diferenciação entre união estável e namoro qualificado: objetivo de constituir família

### Referências legais
- Art. 1.629 CC/2002
- Súmula 434 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo União Estável e Namoro Qualificado

### Dicas de prova
- Diferenciação entre união estável e namoro qualificado
- Objetivo do casal é fundamental para a diferenciação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.511 (1)", "page_number": 511, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 CC/2002", "Súmula 434 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo União Estável e Namoro Qualificado"], "confidence": 0.8, "extracted_at": "2026-05-26T03:51:58.001080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=511", "doc_key": "ef7745370af404f3ea9e74384ab7a26f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '206af9760b98540ccc14951b4e20224e17f28a5b300bbb04bf6e46ef73e67d56'),
  ('cpiuris2025::77f649c248a1c8ed939aeec0ea411c66', 'doutrina', 'cp_iuris', 'Direito Civil — Hipótese de invalidação do ato de união estável', '## Hipótese de invalidação do ato de união estável

A hipótese de invalidação do ato de união estável sem a vênia do outro companheiro ou fiança é discutida, com a orientação do STJ de que não será possível invalidar o negócio se o terceiro não tinha conhecimento da união estável, a menos que seja demonstrado ciência inequívoca.

### Conceitos
- **Vênia conjugal**: Conhecimento expresso do outro companheiro sobre a união estável
- **Ciência inequívoca**: Conhecimento seguro e indubitável da união estável por parte de um terceiro
- **Boa-fé objetiva**: Obrigação moral de agir com honestidade e sinceridade em todas as relações jurídicas

### Referências legais
- Art. 1647 do CC

### Jurisprudência
- {''term'': ''REsp 1.257.819-SP'', ''definition'': ''Tema repetitivo no REsp 1.257.819-SP''}
- {''term'': ''REsp 1.454.643-RJ'', ''definition'': ''Tema repetitivo no REsp 1.454.643-RJ''}

### Dicas de prova
- Distinção entre vênia conjugal e ciência inequívoca
