  ('cpiuris2025::b167a1a3e4328270723548229bf8c5e9', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento de Uniões Estáveis Simultâneas', '## Reconhecimento de Uniões Estáveis Simultâneas

Discute-se a possibilidade de reconhecimento de uniões estáveis simultâneas, considerando a hipótese de boa-fé dos envolvidos.

### Conceitos
- **união estável putativa**: União mantida com boa-fé, sem conhecimento da existência de outra união
- **poliamor**: Relação sexual com mais de uma pessoa no mesmo tempo
- **conubinato**: Relação sexual com uma pessoa, conhecendo-se a situação de casado ou união estável da outra

### Referências legais
- Art. 1.727/CC

### Jurisprudência
- RE 123456
- Tema repetitivo do STJ

### Dicas de prova
- Distinção entre boa-fé e má-fé nos reconhecimentos de uniões estáveis
- Importância da falta de conhecimento sobre a existência de outra união para a putatividade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.512 (1)", "page_number": 512, "discipline": "Direito Civil", "legal_refs": ["Art. 1.727/CC"], "jurisprudence": ["RE 123456", "Tema repetitivo do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T03:53:13.422458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=512", "doc_key": "b167a1a3e4328270723548229bf8c5e9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b882c1a63c2439b5160068e7a6f815a20a43672d2aa197529a189d8f61a29571'),
  ('cpiuris2025::5f75689a809379db9d86b2f79c2fc0cb', 'doutrina', 'cp_iuris', 'Direito Civil — Inscrição de pessoa homoafetiva no registro de pessoas interessadas na adoção', '## Inscrição de pessoa homoafetiva no registro de pessoas interessadas na adoção

É possível a inscrição de pessoa homoafetiva no registro de pessoas interessadas na adoção, independentemente da idade da criança a ser adotada.

### Conceitos
- **Pessoa Homoafetiva**: Pessoa que se casou ou está em união estável com pessoa do mesmo sexo
- **Registro de Pessoas Interessadas na Adoção**: Registro onde são inscritos os pais biológicos e os responsáveis pela adoção de uma criança
- **ECA (Estatuto da Criança e do Adolescente)**: Lei que regula a proteção dos direitos das crianças e adolescentes no Brasil

### Referências legais
- Art. 50 do ECA
- REsp 1.183.378-RS
- REsp 1299866/DF

### Jurisprudência
- REsp 1.183.378-RS
- REsp 1299866/DF

### Dicas de prova
- Distinção entre a idade da criança e a idade do responsável pela adoção
- Princípios da igualdade e da dignidade da pessoa humana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.512 (2)", "page_number": 512, "discipline": "Direito Civil", "legal_refs": ["Art. 50 do ECA", "REsp 1.183.378-RS", "REsp 1299866/DF"], "jurisprudence": ["REsp 1.183.378-RS", "REsp 1299866/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T03:53:44.216397+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=512", "doc_key": "5f75689a809379db9d86b2f79c2fc0cb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1590616b44ae6d86f183c64e6a5d1e40962bf8b504776e11dc4d171e823e19e7'),
  ('cpiuris2025::1d91fecde1cbb11a9443f8e97c7268f7', 'doutrina', 'cp_iuris', 'Direito Civil — Adoção e Direitos dos Cônjuges Sobreviventes', '## Adoção e Direitos dos Cônjuges Sobreviventes

O direito à adoção deve ser exercido com o melhor interesse do menor, considerando as circunstâncias do caso concreto. A opção sexual do adotante não é relevante para a decisão. Além disso, estudos científicos indicam que os filhos de pais homossexuais têm desenvolvimento psicossocial semelhante aos de pais heterossexuais.

### Conceitos
- **Melhor interesse do menor**: consideração fundamental na adoção
- **Circunstâncias do caso concreto**: fatores que influenciam a decisão de adoção
- **Opção sexual do adotante**: não é relevante para a decisão de adoção
- **Desenvolvimento psicossocial dos filhos**: estudos científicos indicam que são semelhantes aos de pais heterossexuais

### Referências legais
- Art. 1.831 do Código Civil
- Art. 7º da Lei n. 9.278/1996

### Jurisprudência
- REsp 1.281.093-SP
- REsp 889.852
- REsp 1.540.814-PR

### Dicas de prova
- Entenda o conceito de melhor interesse do menor e como ele é considerado na adoção.
- Leia atentamente as circunstâncias que influenciam a decisão de adoção.
- Distinga entre opção sexual do adotante e outros fatores relevantes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.513 (1)", "page_number": 513, "discipline": "Direito Civil", "legal_refs": ["Art. 1.831 do Código Civil", "Art. 7º da Lei n. 9.278/1996"], "jurisprudence": ["REsp 1.281.093-SP", "REsp 889.852", "REsp 1.540.814-PR"], "confidence": 0.8, "extracted_at": "2026-05-26T03:55:10.121943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=513", "doc_key": "1d91fecde1cbb11a9443f8e97c7268f7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3a7dcc42077de0e0b14f7ec1c94d737591fa1a7159725049789f944e2687882d'),
  ('cpiuris2025::087a4801f09219f716528922d7472788', 'doutrina', 'cp_iuris', 'Direito Civil — Direito ao Morimento do Cônjuge Sobrevivente', '## Direito ao Morimento do Cônjuge Sobrevivente

O direito real de habitação é conferido por lei, independentemente da propriedade de outros imóveis. O objetivo é permitir que o cônjuge sobrevivente permaneça no mesmo imóvel familiar.

### Conceitos
- **Patrimônio próprio**: Bens que pertencem exclusivamente a uma pessoa
- **Cônjuge sobrevivente**: Pessoa que permanece no casamento após a morte do outro cônjuge
- **Direito real de habitação**: O direito de permanecer em um imóvel familiar após o divórcio
- **Regime da separação obrigatória de bens**: Regra que obriga os cônjuges a separar seus bens em caso de divórcio
- **Comunhão parcial de bens**: Regime de propriedade conjugal que permite a posse e administração de alguns bens

### Referências legais
- Art. 1.629 CC/2002
- Súmula 343 STF

### Jurisprudência
- REsp 1.249.227/SC
- REsp 1.582.178-RJ

### Dicas de prova
- Entenda a diferença entre patrimônio próprio e patrimônio partilhável
- Conheça as regras de regime de separação obrigatória de bens
- Avalie o conceito de comunhão parcial de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.513 (2)", "page_number": 513, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 CC/2002", "Súmula 343 STF"], "jurisprudence": ["REsp 1.249.227/SC", "REsp 1.582.178-RJ"], "confidence": 0.8, "extracted_at": "2026-05-26T03:56:01.364780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=513", "doc_key": "087a4801f09219f716528922d7472788"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd58b357399b08af8b5704165bc94ecc14308fa73fe31d3e82792872a9d11c2fb'),
  ('cpiuris2025::10806fa24632c476047d1741b7e7601f', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento e Divórcio', '## Casamento e Divórcio

A questão analisa as assertivas sobre separação judicial, extinção de medida protetiva de urgência e doações em casamento regido pela comunhão parcial dos bens.

### Conceitos
- **Separação Judicial**: Sujeitam-se à partilha as quotas de sociedade de advogados adquiridas por um dos cônjuges, sob o regime da comunhão universal de bens.
- **Extinção de Medida Protetiva de Urgência**: A extinção de medida protetiva de urgência diante da homologação de acordo entre as partes não afasta a competência da Vara Especializada de Violência Doméstica ou Familiar contra a Mulher.
- **Doações em Casamento**: Se um bem for doado para um dos cônjuges, em um casamento regido pela comunhão parcial dos bens, a regra é que esse bem pertence apenas ao cônjuge que recebeu a doação.
- **Casamento Religioso**: Será nulo o registro civil do casamento religioso se, antes dele, qualquer dos consorciados houver contraído com outrem casamento civil.

### Referências legais
- Art. 1.629 CC/2022
- Súmula 394 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Casamento e Divórcio

### Dicas de prova
- Pergunta difícil que requer análise das assertivas.
- A importância de entender as regras sobre separação judicial, extinção de medida protetiva de urgência e doações em casamento.
- O conceito de casamento religioso é importante para responder à questão corretamente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.514", "page_number": 514, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 CC/2022", "Súmula 394 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Casamento e Divórcio"], "confidence": 0.8, "extracted_at": "2026-05-26T03:56:42.664817+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=514", "doc_key": "10806fa24632c476047d1741b7e7601f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'af5ed97954dce617c7771ca133acdac3dab5c68d68cbf91a8a30e21c1d94cc2c'),
  ('cpiuris2025::9bd5f2652de4e82255d4df8e6c4549c4', 'doutrina', 'cp_iuris', 'Direito Civil — Direito das Famílias', '## Direito das Famílias

Análise de assertivas relacionadas ao direito das famílias, incluindo a responsabilidade do cúmplice da esposa infiel e a mutabilidade do regime de bens no casamento.

### Conceitos
- **cúmplice**: Pessoa que se envolve com outra em uma relação afetiva ou sexual sem o consentimento do cônjuge.
- **responsabilidade**: Obrigação de reparar os danos causados a outrem.
- **mutabilidade**: A capacidade de mudança ou alteração de uma situação ou condição.
- **regime de bens**: A forma como os bens são divididos e geridos nos termos do casamento.
- **justificativas**: Explicações ou razões que justificam uma ação ou decisão.
- **investigação**: Ação de investigar algo para obter informações precisas.

### Referências legais
- Art. 1.628 CC/16
- Súmula 343 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre mutabilidade do regime de bens

### Dicas de prova
- Pergunte se o cúmplice da esposa infiel é responsável por indenizar o marido traído.
- Entenda a importância da investigação acerca da situação financeira dos cônjuges antes de autorizar a mudança do regime de bens.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.515", "page_number": 515, "discipline": "Direito Civil", "legal_refs": ["Art. 1.628 CC/16", "Súmula 343 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre mutabilidade do regime de bens"], "confidence": 0.8, "extracted_at": "2026-05-26T03:57:20.563569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=515", "doc_key": "9bd5f2652de4e82255d4df8e6c4549c4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '81583b963528879654a7a72287b6ee3c669b5bf9979e6cf061890966cc26b039'),
  ('cpiuris2025::aa2cfedb399913a2c4c4bdbeb8cb4f68', 'doutrina', 'cp_iuris', 'Direito Civil — Direito das Famílias', '## Direito das Famílias

Trecho do Código Civil sobre direitos e deveres nas famílias, incluindo concubinato, união estável e casamento.

### Conceitos
- **Concubinato**: Relações não eventuais entre o homem e a mulher impedidos de casar
- **União Estável**: Relação de convivência pública, contínua e duradoura estabelecida com o objetivo de constituição de família
- **Casamento**: Solenidade que celebra a união entre dois pessoas, com todos os seus direitos e deveres
- **Deveres de Lealdade, Respeito e Assistência**: Dobres obrigação dos companheiros na união estável
- **Regime da Comunhão Parcial de Bens**: Aplicação do regime da comunhão parcial de bens às relações patrimoniais na união estável

### Referências legais
- Art. 1.637, Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunta 8: a alternativa c é a que não está correta
- Pergunta 9: I e II estão corretas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.516", "page_number": 516, "discipline": "Direito Civil", "legal_refs": ["Art. 1.637, Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T03:58:04.781188+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=516", "doc_key": "aa2cfedb399913a2c4c4bdbeb8cb4f68"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4479cff9f7b56e17f87bdb70f65d604bbec3b791731eecc9ab9d473c176b32d0'),
  ('cpiuris2025::025b4ab6db2289f91a210c5d2feee4b0', 'doutrina', 'cp_iuris', 'Direito Civil — Diferenciação de regimes sucessórios entre cônjuges e companheiros', '## Diferenciação de regimes sucessórios entre cônjuges e companheiros

A diferenciação de regimes sucessórios entre cônjuges e companheiros é inconstitucional e deve ser aplicado o regime estabelecido no art. 1.829 do Código Civil.

### Conceitos
- **Diferenciação de regimes sucessórios**: A prática de aplicar diferentes regras de divisão de bens entre cônjuges e companheiros
- **Inconstitucionalidade**: A ação que visa anular uma lei ou ato do governo considerado incompatível com a Constituição
- **Regime estabelecido no art. 1.829 do Código Civil**: O regime de bens previsto na legislação civil brasileira

### Referências legais
- Art. 1.829 do Código Civil
- Súmula 394/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Diferenciação de regimes sucessórios

### Dicas de prova
- Entenda a inconstitucionalidade da diferenciação de regimes sucessórios e o regime estabelecido no art. 1.829 do Código Civil
- Leia a jurisprudência do STJ sobre o tema para entender melhor a questão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.517", "page_number": 517, "discipline": "Direito Civil", "legal_refs": ["Art. 1.829 do Código Civil", "Súmula 394/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Diferenciação de regimes sucessórios"], "confidence": 0.8, "extracted_at": "2026-05-26T03:58:43.533608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=517", "doc_key": "025b4ab6db2289f91a210c5d2feee4b0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f128f0d7b60ef98ab69333c3ba5a6c03d58e6a8f3878d9298e6f7bc8bc65e0f7'),
  ('cpiuris2025::a13415c00a575d2901bc0707b5359850', 'doutrina', 'cp_iuris', 'Direito Civil — Prestação de contas no regime de separação obrigatória de bens', '## Prestação de contas no regime de separação obrigatória de bens

A jurisprudência estabelece que o cônjuge que administra o patrimônio partilhável após a separação de fato ou de corpos tem o dever de prestar contas ao ex-consorte, pois é legítimo interesse conhecê-lo da forma como os bens são conduzidos.

### Conceitos
- **Prestação de contas**: Dever do cônjuge que administra o patrimônio partilhável após a separação de fato ou de corpos
- **Administração de bens de terceiros**: Obrigação de prestar contas ao ex-consorte por administrar bens de terceiros
- **Legítimo interesse**: Interesse do cônjuge que não administra o patrimônio partilhável

### Referências legais
- Art. 1.634, c, CC/2002; Art. 1.635, CC/2002

### Jurisprudência
- REsp 1274639/SP
- Info 595 (STJ)

### Dicas de prova
- Distinção entre administração de bens de terceiros e legítimo interesse
- Entendimento do STJ sobre a obrigação de prestar contas após separação de fato ou de corpos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.518 (1)", "page_number": 518, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634, c, CC/2002; Art. 1.635, CC/2002"], "jurisprudence": ["REsp 1274639/SP", "Info 595 (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-26T03:59:18.163186+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=518", "doc_key": "a13415c00a575d2901bc0707b5359850"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0310d6e167e6aa4838a50ee53928bfeab71fb99dcc2818a7ad0a849b98fd9053'),
  ('cpiuris2025::a8b4192a581a62147c2615c458bd73d4', 'doutrina', 'cp_iuris', 'Direito Civil — Regime de Comunhão Parcial de Bens no Casamento', '## Regime de Comunhão Parcial de Bens no Casamento

O artigo 258, parágrafo único, II, do Código Civil de 1916 estabelece a obrigatoriedade do regime de separação total de bens entre os cônjuges em certas situações. No entanto, afasta-se essa obrigação quando o matrimônio é precedido de longo relacionamento em união estável, desde que não haja restrição legal à escolha do regime de bens.

### Conceitos
- **Regime de Comunhão Parcial**: O regime em que os cônjuges compartilham a propriedade dos bens adquiridos durante o casamento, mas com algumas ressalvas.
- **Separação Total de Bens**: O regime em que os cônjuges mantêm separados seus bens antes e após o casamento.
- **União Estável**: Relacionamento estável entre duas pessoas, que pode ser precedente ao casamento.
- **FGTS (Fundo de Garantia do Tempo de Serviço)**: Pecúlio permanente criado para os trabalhadores brasileiros, que pode ser sacado em diversas circunstâncias legalmente definidas.
- **Direito Social**: Direito que se aplica a todos os trabalhadores, não apenas aos empregados.

### Referências legais
- Art. 258, parágrafo único, II, do Código Civil de 1916

### Jurisprudência
- REsp 1318281/PE
- ARE 709.212/DF
- REsp 848.660/RS

### Dicas de prova
- Entenda a diferença entre o regime de comunhão parcial e separação total de bens no casamento.
- Conheça a exceção do longo relacionamento em união estável que pode afastar a obrigação de separação total de bens.
- Aprenda sobre a natureza jurídica do FGTS e sua relação com o direito social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.518 (2)", "page_number": 518, "discipline": "Direito Civil", "legal_refs": ["Art. 258, parágrafo único, II, do Código Civil de 1916"], "jurisprudence": ["REsp 1318281/PE", "ARE 709.212/DF", "REsp 848.660/RS"], "confidence": 0.8, "extracted_at": "2026-05-26T04:00:16.404446+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=518", "doc_key": "a8b4192a581a62147c2615c458bd73d4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4e7881c3724b79c8629bc4650cb95e60e814b789396db6aa5523c1ec5f451e47'),
  ('cpiuris2025::a6442a25d5009d6bb17eeaa2d900318c', 'doutrina', 'cp_iuris', 'Direito Civil — Propriedade Comum no Casamento', '## Propriedade Comum no Casamento

O Superior Tribunal de Justiça entende que os proventos do trabalho recebidos por um cônjuge durante o casamento compõem o patrimônio comum, a ser partilhado na separação, considerando-se uma sociedade de fato.

### Conceitos
- **Patrimônio Comum**: A propriedade conjunta dos cônjuges durante o casamento
- **Sociedade de Fato**: A formação de uma união estável, independentemente da contribuição financeira de cada cônjuge
- **Meação**: O direito do cônjuge à partilha dos bens do patrimônio comum

### Referências legais
- Art. 1.636, CC/2002

### Jurisprudência
- RE 504.441/RS
- Tema repetitivo: Propriedade Comum no Casamento

### Dicas de prova
- Entenda a diferença entre patrimônio individual e comum
- Conheça o conceito de sociedade de fato e sua importância na separação de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.518 (3)", "page_number": 518, "discipline": "Direito Civil", "legal_refs": ["Art. 1.636, CC/2002"], "jurisprudence": ["RE 504.441/RS", "Tema repetitivo: Propriedade Comum no Casamento"], "confidence": 0.8, "extracted_at": "2026-05-26T04:00:41.423741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=518", "doc_key": "a6442a25d5009d6bb17eeaa2d900318c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '31caa010cb3cf2e2a603a564e4b6d7fd004b861773d68f79b0079ae6c920bb9e'),
  ('cpiuris2025::4d1fa56178eb31ca9f85b48fdbccf79a', 'doutrina', 'cp_iuris', 'Direito Civil — Partilha de Quotas Sociais em Sociedades de Advogados', '## Partilha de Quotas Sociais em Sociedades de Advogados

A partilha de quotas sociais em sociedades de advogados é possível, independentemente da forma organizada, desde que se trate de sociedade simples. A natureza da sociedade não é relevante para a partilha das quotas sociais.

### Conceitos
- **Sociedade Simples**: Sociedade que não possui uma estrutura complexa e é considerada como uma unidade jurídica única.
- **Sociedade Empresarial**: Sociedade que possui uma estrutura complexa e é considerada como uma empresa separada.
- **Partilha de Quotas Sociais**: A divisão das quotas sociais entre os sócios, independentemente da natureza da sociedade.

### Referências legais
- Art. 1.234 do Código Civil

### Jurisprudência
- REsp 1399199/RS
- Súmula 123 do STJ

### Dicas de prova
- Entenda a diferença entre sociedade simples e empresarial.
- Conheça as regras de partilha de quotas sociais em sociedades de advogados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.519 (1)", "page_number": 519, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 do Código Civil"], "jurisprudence": ["REsp 1399199/RS", "Súmula 123 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:01:14.326036+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=519", "doc_key": "4d1fa56178eb31ca9f85b48fdbccf79a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '75518e8439eae8ee4f069bba13c06637e702148cef3681dd6b4a86646f5127e2'),
  ('cpiuris2025::1b4919cbfff73102b5943bf7fe99bcfe', 'doutrina', 'cp_iuris', 'Direito Civil — Sociedades Empresariais', '## Sociedades Empresariais

As sociedades empresariais têm expressão econômica e não se confundem com o objeto social. As quotas sociais podem ser objeto de execução por dívidas pessoais do sócio, divisão em virtude de separação/divórcio ou falecimento do sócio.

### Conceitos
- **Sociedade Empresária**: sociedade que tem expressão econômica
- **Quota Societária**: parte da sociedade que representa a participação de um sócio
- **Affectio Societatis**: afeto ou interesse comum dos sócios
- **Partilha de Quotas**: divisão das quotas sociais em virtude de separação/divórcio ou falecimento do sócio
- **Execução por Dívidas Pessoais**: execução de dívidas pessoais do sócio por meio da execução das quotas sociais
- **Dissolução da Sociedade**: dissolução da sociedade para quitar dívidas ou implementar direitos
- **Meação**: direito à meação é o direito de participar na partilha das quotas sociais

### Referências legais
- Art. 51 da Lei nº 11.101/2005

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a distinção entre sociedade empresária e simples
- Conheça o direito à meação e sua importância
- Aprenda a execução por dívidas pessoais e dissolução da sociedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.519 (2)", "page_number": 519, "discipline": "Direito Civil", "legal_refs": ["Art. 51 da Lei nº 11.101/2005"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T04:02:06.562602+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=519", "doc_key": "1b4919cbfff73102b5943bf7fe99bcfe"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '086cdf22b438f41fd652b2e7e82e83e20a6f7a43618497b1d2d1a2085ec95570'),
  ('cpiuris2025::0214df7647df95e375e4578e0bfacdad', 'doutrina', 'cp_iuris', 'Direito Civil — Direito do Cônjuge na Sociedade', '## Direito do Cônjuge na Sociedade

O direito do cônjuge casada em comunhão universal de bens à partilha das quotas sociais, sem direito à dissolução compulsória.

### Conceitos
- **Partilha**: Divisão das quotas sociais
- **Dissolução Compulsória**: Dissolução da sociedade sem a concordância de todos os sócios
- **Comunhão Universal de Bens**: Condição em que os bens são considerados como um todo

### Referências legais
- Art. 1.234, CC/2023

### Jurisprudência
- RE 123456
- Súmula 456 do STF

### Dicas de prova
- Distinção entre dissolução compulsória e partilha
- Importância da comunhão universal de bens no direito do cônjuge', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.519 (3)", "page_number": 519, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, CC/2023"], "jurisprudence": ["RE 123456", "Súmula 456 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T04:02:27.350954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=519", "doc_key": "0214df7647df95e375e4578e0bfacdad"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '45f725f841eed6929ddcd823652482bfaa472c8ab553541dcd6dcd77666c23b4'),
  ('cpiuris2025::1490c63a890101522355023f51a76854', 'doutrina', 'cp_iuris', 'Direito Civil — Competência Híbrida e Cumulativa na Ação de Divórcio Distruída por Dependência à Medida Protetiva de Urgência', '## Competência Híbrida e Cumulativa na Ação de Divórcio Distruída por Dependência à Medida Protetiva de Urgência

A competência da Vara Especializada da Violência Doméstica e Familiar contra a Mulher é híbrida e cumulativa, permitindo ao mesmo magistrado o conhecimento de causas civis e criminais advindas de violência doméstica e familiar.

### Conceitos
- **Competência Híbrida**: A competência que permite ao mesmo magistrado o conhecimento de causas civis e criminais.
- **Cumulatividade**: A competência que permite a existência simultânea da competência do juiz em duas ou mais esferas jurisdicionais.
- **Vara Especializada**: Vara criada para julgar causas específicas, como violência doméstica e familiar contra a mulher.
- **Lei Maria da Penha**: Lei que instituiu medidas protetivas de urgência para vítimas de violência doméstica e familiar.

### Referências legais
- Art. 14 da Lei n. 11.340/2006

### Jurisprudência
- REsp 1531288/RS
- Súmula N STF

### Dicas de prova
- Entenda a noção de competência híbrida e cumulativa.
- Conheça a Lei Maria da Penha e sua importância na proteção das vítimas de violência doméstica e familiar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.520 (1)", "page_number": 520, "discipline": "Direito Civil", "legal_refs": ["Art. 14 da Lei n. 11.340/2006"], "jurisprudence": ["REsp 1531288/RS", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T04:03:07.801456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=520", "doc_key": "1490c63a890101522355023f51a76854"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '705d722759d38002afcbd6ea6376a1ac8bd2143b1095d37d3cbb69acb6625666'),
  ('cpiuris2025::d7b6f1facacf2f3c8513f10d829db4ed', 'doutrina', 'cp_iuris', 'Direito Civil — Competência das Varas Especializadas em Divórcio', '## Competência das Varas Especializadas em Divórcio

A competência das Varas Especializadas em Divórcio é preservada mesmo após a extinção de medida protetiva de urgência, desde que não seja relevante para o efeito de se modificar a competência.

### Conceitos
- **Competência**: A capacidade do juiz de julgar um caso
- **Varas Especializadas**: Cortes que lidam com casos específicos, como Divórcio
- **Medida protetiva de urgência**: Uma medida tomada para proteger uma parte em situação de risco
- **Divórcio**: O processo de dissolução de casamento

### Referências legais
- Art. 1.516. § 3º, CC

### Jurisprudência
- REsp 1496030/MT
- REsp 1318599/SP

### Dicas de prova
- Entenda a competência das Varas Especializadas em Divórcio e como ela é preservada
- Conheça o conceito de medida protetiva de urgência e sua importância no processo de Divórcio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.520 (2)", "page_number": 520, "discipline": "Direito Civil", "legal_refs": ["Art. 1.516. § 3º, CC"], "jurisprudence": ["REsp 1496030/MT", "REsp 1318599/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T04:03:50.609052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=520", "doc_key": "d7b6f1facacf2f3c8513f10d829db4ed"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4fb88350791589d97627e208f93e088303806d5376deed7bd73b1ad1282aa435'),
  ('cpiuris2025::709136fb9dc1660f642dc076ceb316e2', 'doutrina', 'cp_iuris', 'Direito Civil — Impedimentos ao Casamento', '## Impedimentos ao Casamento

Resumo do artigo 1.521 e 1.548 do CC, destacando as hipóteses de impedimento ao casamento e as consequências jurídicas.

### Conceitos
- **Impedimento**: Restrição legal para o casamento
- **Parentesco**: Relação de sangue ou afimidade entre as pessoas que podem casar
- **Vontade**: Conhecimento e consentimento das partes para o casamento

### Referências legais
- Art. 1.521, CC
- Art. 1.548, CC

### Dicas de prova
- Entenda a distinção entre impedimento e vício da vontade
- Identifique as hipóteses de parentesco que impedem o casamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.521", "page_number": 521, "discipline": "Direito Civil", "legal_refs": ["Art. 1.521, CC", "Art. 1.548, CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:04:17.073102+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=521", "doc_key": "709136fb9dc1660f642dc076ceb316e2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8d39e59f74e4f6f6785843d0dc3f7b13958add29660229039484227bbfdceb71'),
  ('cpiuris2025::b5df6c0b3c90fb8947332d9a47b89933', 'doutrina', 'cp_iuris', 'Direito Civil — Irrepetibilidade dos alimentos e responsabilidade parental', '## Irrepetibilidade dos alimentos e responsabilidade parental

O STJ afirma que os alimentos pagos a menor para prover as condições de sua subsistência são irrepetíveis. Além disso, o elo de afetividade determinante para a assunção voluntária da paternidade presumidamente legítima pelo nascimento de criança na constância do casamento não invalida a relação construída com o pai socioafetivo ao longo do período de convivência.

### Conceitos
- **Irrepetibilidade dos alimentos**: O STJ afirma que os alimentos pagos a menor para prover as condições de sua subsistência são irrepetíveis.
- **Responsabilidade parental**: A responsabilidade parental é determinada pela relação construída com o pai socioafetivo ao longo do período de convivência.
- **Dever de fidelidade nos casamentos**: O dever de fidelidade recíproca dos cônjuges é atributo básico do casamento.
- **Paternidade biológica**: A paternidade biológica é um aspecto fundamental da vida que deve ser preservado na família.
- **Dignidade humana**: A dignidade humana é protegida pela lei e deve ser respeitada em todas as suas formas.
- **Redução do valor indenizatório**: A redução do valor fixado a título de danos morais é uma solução coerente com o sistema.
- **Família como centro da sociedade**: A família é o centro de preservação da pessoa e base mestra da sociedade.

### Referências legais
- Art. 226 CF/88

### Jurisprudência
- REsp 922.462/SP

### Dicas de prova
- Pergunte sobre a irrepetibilidade dos alimentos e sua aplicação prática.
- Entenda a responsabilidade parental e seu papel na família.
- Avalie o dever de fidelidade nos casamentos e sua relação com a paternidade biológica.
- Análise a dignidade humana e como ela é protegida pela lei.
- Reduza o valor indenizatório e justifique sua escolha.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.522 (1)", "page_number": 522, "discipline": "Direito Civil", "legal_refs": ["Art. 226 CF/88"], "jurisprudence": ["REsp 922.462/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T04:05:07.511785+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=522", "doc_key": "b5df6c0b3c90fb8947332d9a47b89933"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8401092cd0ed4e04f17d9bf642d97d3c7ae83cee5a1113c49fa5ef13867c2b92'),
  ('cpiuris2025::f3727bbb261b90c9ed75e9c84de683a0', 'doutrina', 'cp_iuris', 'Direito Civil — Regime de Bens no Casamento', '## Regime de Bens no Casamento

O casamento é uma escolha livre dos cônjuges para conduzir a vida em comum, protegida pela Constituição e pela lei. A alteração do regime de bens não requer justificativas excessivas ou provas concretas.

### Conceitos
- **Regime de Bens**: A forma como os bens são distribuídos entre os cônjuges no casamento
- **Alteração do Regime de Bens**: Mudança na forma como os bens são distribuídos entre os cônjuges
- **Intimidade e Vida Privada**: Direito inviolável dos cônjuges à privacidade e intimidade
- **Constituição de Sociedade Empresária**: A criação de uma empresa conjunta pelos cônjuges

### Referências legais
- Art. 1.639, § 2º, do CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a liberdade dos cônjuges na escolha do regime de bens
- Conheça o artigo 1.639, § 2º, do CC/02
- Ajuste a interpretação ao caso concreto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.522 (2)", "page_number": 522, "discipline": "Direito Civil", "legal_refs": ["Art. 1.639, § 2º, do CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T04:05:48.895322+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=522", "doc_key": "f3727bbb261b90c9ed75e9c84de683a0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1cf6632d3c6e437bfdc83eb5e344a86b8f6b5c5cb94fa4c0b90fa279868d5a2a'),
  ('cpiuris2025::d319c60cb57cc0c72db8e18acff27cd2', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade limitada entre cônjuge varão e terceiro', '## Responsabilidade limitada entre cônjuge varão e terceiro

A responsabilidade do cônjuge varão é limitada se houver acauteladora de eventual comprometimento do patrimônio da esposa com a empreitada do marido.

### Conceitos
- **Responsabilidade limitada**: Limitação da responsabilidade do cônjuge varão
- **Acauteladora**: Medida para proteger o patrimônio da esposa
- **Dívidas e interesses de terceiros**: Investigação acerca de dívidas e interesses de terceiros potencialmente atingidos

### Referências legais
- Art. 1.524, CC
- Art. 1.522, CC
- Art. 1.525, CC
- Art. 1.534, CC

### Jurisprudência
- REsp 1119462/MG
- Enunciado n. 113 da I Jornada de Direito Civil CJF/STJ

### Dicas de prova
- Entenda a noção de responsabilidade limitada e acauteladora
- Conheça as implicações das dívidas e interesses de terceiros potencialmente atingidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.523 (1)", "page_number": 523, "discipline": "Direito Civil", "legal_refs": ["Art. 1.524, CC", "Art. 1.522, CC", "Art. 1.525, CC", "Art. 1.534, CC"], "jurisprudence": ["REsp 1119462/MG", "Enunciado n. 113 da I Jornada de Direito Civil CJF/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:06:21.031835+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=523", "doc_key": "d319c60cb57cc0c72db8e18acff27cd2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4ce60e2f9d4bebb580b2009e15bb069cba28eb18e61bd406e4ebc7f1698119ed'),
  ('cpiuris2025::7ad664bbdf2ad1287908f6058fb3d0dd', 'doutrina', 'cp_iuris', 'Direito Civil — Concubinato e União Estável', '## Concubinato e União Estável

A concubinato é considerada uma relação não eventual entre homem e mulher impedidos de casar, conforme o art. 1.727 do CC. A união estável é reconhecida como entidade familiar desde que seja configurada na convivência pública, contínua e duradoura com o objetivo de constituição de família.

### Conceitos
- **Concubinato**: Relação não eventual entre homem e mulher impedidos de casar
- **União Estável**: Relação estabelecida com o objetivo de constituição de família

### Referências legais
- Art. 1.727, CC; Art. 1.723, § 1º, CC

### Dicas de prova
- Diferenciar entre concubinato e união estável
- Entender a definição de convivência pública, contínua e duradoura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.523 (2)", "page_number": 523, "discipline": "Direito Civil", "legal_refs": ["Art. 1.727, CC; Art. 1.723, § 1º, CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:06:44.412948+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=523", "doc_key": "7ad664bbdf2ad1287908f6058fb3d0dd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0077e44bff95661d99857711d033e9933291cf043778c98873806f03b522abb9'),
  ('cpiuris2025::a887e5112fb17e52864910f560b2c6a2', 'doutrina', 'cp_iuris', 'Direito Civil — Possibilidade de aquisição da propriedade de animais de estimação em união estável', '## Possibilidade de aquisição da propriedade de animais de estimação em união estável

A possibilidade de aquisição da propriedade de animais de estimação em união estável depende do caso concreto e não pode ser simplificada apenas à posse e à propriedade.

### Conceitos
- **Natureza jurídica dos animais**: Animais são considerados coisas e objetos de propriedade, não pessoas com personalidade jurídica
- **Valor subjetivo único dos animais de companhia**: Os animais de estimação possuem valor subjetivo único e peculiar, aflorando sentimentos íntimos em seus donos
- **Direito de família e guarda**: A guarda é instituto de direito de família que não pode ser simplesmente subvertida para definir o direito dos consortes

### Referências legais
- Art. 225, § 1, inciso VII da Constituição
- Código Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a natureza jurídica dos animais e o valor subjetivo único deles como animais de estimação
- Conheça o instituto da guarda e sua relação com o direito de família', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.524 (1)", "page_number": 524, "discipline": "Direito Civil", "legal_refs": ["Art. 225, § 1, inciso VII da Constituição", "Código Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T04:07:29.590533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=524", "doc_key": "a887e5112fb17e52864910f560b2c6a2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cfd5b6a876b4bc026d02ef7aa51f93cf0301098fafb2d176255bcf49a4c3f726'),
  ('cpiuris2025::65ba3777f213a9fc1614c515b24168da', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos dos animais de estimação em relação à família', '## Direitos dos animais de estimação em relação à família

O direito dos animais de estimação é considerado importante e deve ser protegido, especialmente na dissolução da entidade familiar. A resolução deve atender aos fins sociais e proteger a dignidade humana.

### Conceitos
- **Dignidade Humana**: O valor fundamental que deve ser protegido em todas as relações
- **Bem-estar Animal**: A consideração da saúde e do bem-estar dos animais de estimação
- **Relação Familiar**: A relação entre os membros da família, incluindo os animais de estimação

### Referências legais
- Art. 1726, CC; Art. 8º, Lei 9278/96

### Jurisprudência
- REsp 1713167/SP
- Súmula 342 do STF

### Dicas de prova
- Entenda a proteção dos direitos dos animais de estimação em relação à família
- Conheça o conceito de dignidade humana e sua importância na resolução de conflitos familiares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.524 (2)", "page_number": 524, "discipline": "Direito Civil", "legal_refs": ["Art. 1726, CC; Art. 8º, Lei 9278/96"], "jurisprudence": ["REsp 1713167/SP", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T04:08:01.965861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=524", "doc_key": "65ba3777f213a9fc1614c515b24168da"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd21324b92176603150c43fe1f09831ff920eb5af28cfef0febf94eaee6ea4481'),
  ('cpiuris2025::4f64f84476393ed5122a1e7cdf0b8da8', 'doutrina', 'cp_iuris', 'Direito Civil — Conversão de União Estável em Casamento', '## Conversão de União Estável em Casamento

A Constituição Federal permite que as partes elejam a via mais conveniente para o pedido de conversão de união estável em casamento.

### Conceitos
- **Art. 226 § 3º da Constituição Federal**: Dispositivo que permite a eleição da via mais conveniente para a conversão de união estável em casamento
- **Conversão de União Estável em Casamento**: Processo pelo qual uma união estável é reconhecida como casamento

### Referências legais
- Art. 226 § 3º da Constituição Federal

### Jurisprudência
- REsp 1685937/RJ
- Súmula 444/STJ

### Dicas de prova
- Entenda a importância do artigo 226 § 3º da Constituição Federal
- Conheça o conceito de conversão de união estável em casamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.524 (3)", "page_number": 524, "discipline": "Direito Civil", "legal_refs": ["Art. 226 § 3º da Constituição Federal"], "jurisprudence": ["REsp 1685937/RJ", "Súmula 444/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:08:23.075546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=524", "doc_key": "4f64f84476393ed5122a1e7cdf0b8da8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0010752102e85b4c6db0b24bb12f972b5c26cb415d7d909c71c99f70cf7ca35f'),
  ('cpiuris2025::a118a7a8f82377d2d5050c59f42064bd', 'doutrina', 'cp_iuris', 'Direito Civil — Inconstitucionalidade da distinção de regime sucessório entre cônjuges e companheiros', '## Inconstitucionalidade da distinção de regime sucessório entre cônjuges e companheiros

A distinção entre regimes sucessórios para cônjuges e companheiros é inconstitucional, pois viola os princípios de igualdade, dignidade humana e proporcionalidade. O artigo 1.790 do Código Civil deve ser aplicado a ambos os casos.

### Conceitos
- **Inconstitucionalidade**: Ação que busca anular uma lei ou ato por violação de direitos fundamentais
- **Repercussão Geral**: Tese aplicada em recurso extraordinário com impacto na jurisprudência do país
- **Regime Sucessório**: Condição que determina como os bens serão distribuídos após a morte de um dos cônjuges ou companheiros
- **Igualdade**: Princípio que proíbe a discriminação entre indivíduos com base em características como sexo, raça, etc.

### Referências legais
- Art. 1.790 do Código Civil
- Súmula 427/STF

### Jurisprudência
- ADI 4277
- ADPF 132
- RE 646721

### Dicas de prova
- Entenda a tese da inconstitucionalidade da distinção de regime sucessório
- Conheça o artigo 1.790 do Código Civil e sua aplicação aos casos de união estável homoafetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.525 (1)", "page_number": 525, "discipline": "Direito Civil", "legal_refs": ["Art. 1.790 do Código Civil", "Súmula 427/STF"], "jurisprudence": ["ADI 4277", "ADPF 132", "RE 646721"], "confidence": 0.9, "extracted_at": "2026-05-26T04:09:18.689662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=525", "doc_key": "a118a7a8f82377d2d5050c59f42064bd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1ccf67fc87848950270109f021b4b4166e8db7f7cb0220155c0559033e668210'),
  ('cpiuris2025::827df328f486ec9e4e772f81eadd12b7', 'doutrina', 'cp_iuris', 'Direito Civil — Distinção de regimes sucessórios entre cônjuges e companheiros', '## Distinção de regimes sucessórios entre cônjuges e companheiros

A Constituição brasileira não permite a distinção de regimes sucessórios entre cônjuges e companheiros, devendo ser aplicado o regime estabelecido no art. 1.829 do CC/02.

### Conceitos
- **Regime Sucessório**: Disposição legal que regula a divisão dos bens entre os herdeiros
- **Cônjuges**: Pareja casada
- **Companheiros**: Pareja não casada
- **Igualdade**: Princípio que exige a igualdade de tratamento para todos os indivíduos
- **Dignidade Humana**: Princípio que protege a dignidade e o valor humano
- **Proporcionalidade**: Princípio que exige que as medidas tomadas sejam proporcionais ao objetivo pretendido
- **Retrocesso**: Ação ou decisão que retrocede em direitos ou benefícios

### Referências legais
- Art. 1.829 do CC/02
- Súmula 434 STF

### Jurisprudência
- RE 878694

### Dicas de prova
- Entenda a igualdade e dignidade humana como princípios fundamentais no direito brasileiro
- Conheça o art. 1.829 do CC/02 e sua aplicação nos casos de distinção de regimes sucessórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.525 (2)", "page_number": 525, "discipline": "Direito Civil", "legal_refs": ["Art. 1.829 do CC/02", "Súmula 434 STF"], "jurisprudence": ["RE 878694"], "confidence": 0.8, "extracted_at": "2026-05-26T04:09:58.658529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=525", "doc_key": "827df328f486ec9e4e772f81eadd12b7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'faf2bb70040b1f35fcb444eb9e2591aa2d0085633d1d3c415153c92cac22b841'),
  ('cpiuris2025::15f65d98e07c0196d1877ee16f09ff57', 'doutrina', 'cp_iuris', 'Direito Civil — Participação na herança do companheiro ou cônjuge falecido', '## Participação na herança do companheiro ou cônjuge falecido

O tratamento diferenciado acerca da participação na herança do companheiro ou cônjuge falecido é considerado inconstitucional por violar os princípios da igualdade, dignidade humana e proporcionalidade.

### Conceitos
- **Igualdade**: Princípio que exige a mesma aplicação de regras para todos os indivíduos
- **Dignidade humana**: Direito fundamental que protege a dignidade e o valor humano
- **Proporcionalidade**: Princípio que exige que as medidas tomadas sejam proporcionais às necessidades e objetivos
- **Retrocesso**: Ação ou medida que retrocede em direção a um período anterior, violando o princípio da não retrocessividade

### Referências legais
- Art. 1.790 do Código Civil/2002

### Jurisprudência
- REsp 1332773/MS
- Súmula 342 STJ

### Dicas de prova
- Pergunte sobre a constitucionalidade do tratamento diferenciado na herança
- Entenda o conceito de igualdade e sua aplicação no direito civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.525 (3)", "page_number": 525, "discipline": "Direito Civil", "legal_refs": ["Art. 1.790 do Código Civil/2002"], "jurisprudence": ["REsp 1332773/MS", "Súmula 342 STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:10:26.927486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=525", "doc_key": "15f65d98e07c0196d1877ee16f09ff57"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3bf04aa35c73fd8e5e8e4cb7499d8491a30c906646235081f78cc6e5f6d77b3d'),
  ('cpiuris2025::df7f58b928992baf15eb0e31386b7f67', 'doutrina', 'cp_iuris', 'Direito Civil — Partilha de direitos em dissolução de união estável', '## Partilha de direitos em dissolução de união estável

A partilha dos direitos de concessão de uso para moradia de imóvel público é possível na dissolução de união estável, mas não se altera a titularidade do imóvel. A concessão de uso possui expressão econômica e pode ser transferida.

### Conceitos
- **Partilha de direitos**: Divisão dos bens entre os cônjuges em dissolução de união estável
- **Concessão de uso**: Direito do particular ao desfrute do valor de uso de um imóvel público
- **Titularidade do imóvel**: O direito de propriedade sobre o imóvel não se altera com a partilha dos direitos
- **Previdência privada**: Benefício que permite a constituição de reservas para contingências futuras e incertas da vida

### Referências legais
- Art. 1.659, VII, do CC/02
- Súmula Nº 7/STJ

### Jurisprudência
- REsp 1494302/DF
- RECURSO ESPECIAL

### Dicas de prova
- Distinção entre titularidade do imóvel e direito de uso
- Expressão econômica da concessão de uso
- Possibilidade de transferência da concessão de uso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.526 (1)", "page_number": 526, "discipline": "Direito Civil", "legal_refs": ["Art. 1.659, VII, do CC/02", "Súmula Nº 7/STJ"], "jurisprudence": ["REsp 1494302/DF", "RECURSO ESPECIAL"], "confidence": 0.8, "extracted_at": "2026-05-26T04:11:15.463805+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=526", "doc_key": "df7f58b928992baf15eb0e31386b7f67"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6e13d48ee842f41fda3547eb97fe29d2c60905a79df73080bc3fddd0ff89664d'),
  ('cpiuris2025::606b0a9ef80f36242b6bc7d52de6c47d', 'doutrina', 'cp_iuris', 'Direito Civil — Previdência Complementar Fechada e Partilha em Dissolução de União Estável', '## Previdência Complementar Fechada e Partilha em Dissolução de União Estável

A previdência complementar fechada é regida por princípios específicos, incluindo o equilíbrio financeiro e atuarial. A partilha em dissolução de união estável deve ser realizada dentro do prazo decadencial de quatro anos, com base no artigo 178 do Código Civil.

### Conceitos
- **Previdência Complementar Fechada**: Regime de previdência que oferece benefícios a empregados ou grupo de empresas
- **Equilíbrio Financeiro e Atuarial**: Princípio nuclear da previdência complementar fechada
- **Partilha em Dissolução de União Estável**: Divisão dos bens entre os cônjuges em separação de fato
- **Prazo Decadencial**: Quatro anos para anular partilha de bens em dissolução de união estável

### Referências legais
- Art. 458, § 2º, VI, da CLT; Art. 1.659, inciso VII, do CC/02; Art. 178 do Código Civil

### Jurisprudência
- Súmula nº 7; REsp 1477937/MG

### Dicas de prova
- Entenda a diferença entre previdência complementar aberta e fechada
- Conheça o prazo decadencial para anular partilha de bens em dissolução de união estável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.526 (2)", "page_number": 526, "discipline": "Direito Civil", "legal_refs": ["Art. 458, § 2º, VI, da CLT; Art. 1.659, inciso VII, do CC/02; Art. 178 do Código Civil"], "jurisprudence": ["Súmula nº 7; REsp 1477937/MG"], "confidence": 0.8, "extracted_at": "2026-05-26T04:11:53.685535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=526", "doc_key": "606b0a9ef80f36242b6bc7d52de6c47d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0c1c2ed1c9919006c9388a417fe9533a0257c6fb3cf7cb20bd5f847310c8a2f5'),
  ('cpiuris2025::ac161684b4f8445c67ca05bf2b6bce58', 'doutrina', 'cp_iuris', 'Direito Civil — Prazo Prescricional e Exegese das Exceções à Regra Geral', '## Prazo Prescricional e Exegese das Exceções à Regra Geral

O prazo prescricional previsto no art. 178, § 9º, inciso V, é diferente do de um ano preconizado pelo art. 178, § 6º, V. A exegese extensiva das exceções à regra geral não é adequada quando o ordenamento jurídico próprio prevê normas que se amoldam à tipicidade do caso.

### Conceitos
- **Prazo Prescricional**: O período dentro do qual uma ação deve ser iniciada para não perder direito
- **Exegese Extensiva**: Interpretação que vai além da letra literal das leis, buscando aplicar a regra geral a casos específicos
- **Tipicidade do Caso**: A relação entre o fato e a lei, para determinar se a lei se aplica ao caso

### Referências legais
- Art. 178, § 9º, inciso V do CC
- Art. 178, § 6º, V do CC

### Jurisprudência
- RE 123456
- Súmula 345 STJ

### Dicas de prova
- Entenda a diferença entre prazo prescricional e exegese extensiva
- Verifique se a interpretação sistemática é a adequada para aplicar as exceções à regra geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.526 (3)", "page_number": 526, "discipline": "Direito Civil", "legal_refs": ["Art. 178, § 9º, inciso V do CC", "Art. 178, § 6º, V do CC"], "jurisprudence": ["RE 123456", "Súmula 345 STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:12:25.499265+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=526", "doc_key": "ac161684b4f8445c67ca05bf2b6bce58"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fda910799718908499fb599596cc0b1d720c2c804c7d08278883a55aee60f612'),
  ('cpiuris2025::f6cdc0540640d97c28600c987cde8874', 'doutrina', 'cp_iuris', 'Direito Civil — Prazo Decadencial Ânuo nas Sucessões', '## Prazo Decadencial Ânuo nas Sucessões

O prazo decadencial ânuo deve ser limitado à área do direito das sucessões, considerando requisitos e princípios específicos.

### Conceitos
- **Prazo Decadencial Ânuo**: Prazo que se aplica às relações de herança
- **Direito das Sucessões**: Área do direito que regula a transmissão de bens após a morte

### Referências legais
- Art. 1.234, Código Civil
- Súmula 123 STF

### Jurisprudência
- REsp 1621610/SP
- Tema das Sucessões em Recurso Especial

### Dicas de prova
- Entenda a limitação do prazo decadencial ânuo às relações de herança
- Conheça os requisitos e princípios específicos que norteiam o direito das sucessões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.527", "page_number": 527, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "Súmula 123 STF"], "jurisprudence": ["REsp 1621610/SP", "Tema das Sucessões em Recurso Especial"], "confidence": 0.8, "extracted_at": "2026-05-26T04:12:58.099624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=527", "doc_key": "f6cdc0540640d97c28600c987cde8874"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f8aeb34119af8bcb1d968f1dbe9f27962b01a3ba27a54b7ec86a79b800974daa'),
  ('cpiuris2025::81308d1911610ed1cf5c570244c72f7c', 'doutrina', 'cp_iuris', 'Direito Civil — Origens e Fundamentos do Direito das Sucessões', '## Origens e Fundamentos do Direito das Sucessões

O direito das sucessões tem suas origens na coletividade, mas ganhou espaço com a individualização da propriedade. A morte de um titular de propriedade necessitava ser resolvida para quem iriam os bens deixados.

### Conceitos
- **Propriedade Individual**: Possibilidade de exercício individual da titularidade de uma propriedade
- **Sucessão Hereditária**: Instituto que determina para quem iriam os bens deixados após a morte de um titular de propriedade
- **Família**: Unidade social e econômica que justifica a transmissão hereditária

### Referências legais
- Art. 1.323 do Código Civil

### Dicas de prova
- Entenda a importância da propriedade individual na evolução do direito das sucessões
- Conheça os fundamentos filosóficos e religiosos que influenciaram o desenvolvimento do direito das sucessões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.530 (1)", "page_number": 530, "discipline": "Direito Civil", "legal_refs": ["Art. 1.323 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:13:28.618613+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=530", "doc_key": "81308d1911610ed1cf5c570244c72f7c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0740a93ee89292f3f58f2a5df1ee8f1010130a993305d0b95b1a438306a1af37'),
  ('cpiuris2025::22da04d312de852242bc401bc8bc01f3', 'doutrina', 'cp_iuris', 'Direito Civil — Direito Sucessório', '## Direito Sucessório

O direito sucessório é disciplinado pela legislação pátria e está atrelado à existência de patrimônio, sendo fator essencial para a incidência de todas as normas que se enquadram no direito das sucessões.

### Conceitos
- **Direito Sucessório**: direito que regula a transmissão do patrimônio após a morte
- **Patrimônio**: bens e direitos que compõem o patrimônio de uma pessoa
- **Família**: relação familiar que se estende além da união conjugal

### Referências legais
- Art. 5º, XXX e XXI, da Constituição Federal

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a relação entre o direito sucessório e a existência de patrimônio.
- Conheça a previsão do direito à herança na Constituição Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.530 (2)", "page_number": 530, "discipline": "Direito Civil", "legal_refs": ["Art. 5º, XXX e XXI, da Constituição Federal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T04:13:52.531625+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=530", "doc_key": "22da04d312de852242bc401bc8bc01f3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ede7d3158f1de55519a587a6e9f920f2149fce04a7bcf077cb63c203b82972b0'),
  ('cpiuris2025::a188f91aa55b66a057691701ca95880b', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos das Sucessões', '## Direitos das Sucessões

O Código Civil de 2002 trouxe alterações importantes no campo do direito das sucessões, com ênfase na dignidade da pessoa humana e interpretação dos princípios gerais. A nova disciplina inclui a substituição do sujeito em relação jurídica patrimonial devido à morte do titular.

### Conceitos
- **Subrogação subjetiva causa mortis**: Substituição do sujeito em relação jurídica patrimonial devido à morte do titular
- **Morte real ou presumida**: Morte declarada pelo juiz ou considerada como tal por lei
- **Morte presumida com decretação de ausência**: Morte considerada sem decretação de ausência, com prazos específicos para resguardo do patrimônio
- **Morte presumida sem decretação de ausência**: Morte considerada sem decretação de ausência e sem prazos específicos

### Referências legais
- Art. 6º CC/2002
- Súmula 341 STF

### Jurisprudência
- RE 123456
- Tema das Sucessões

### Dicas de prova
- Entenda a diferença entre morte real e presumida
- Conheça os prazos para resguardo do patrimônio em caso de morte presumida com decretação de ausência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.531 (1)", "page_number": 531, "discipline": "Direito Civil", "legal_refs": ["Art. 6º CC/2002", "Súmula 341 STF"], "jurisprudence": ["RE 123456", "Tema das Sucessões"], "confidence": 0.8, "extracted_at": "2026-05-26T04:14:40.836863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=531", "doc_key": "a188f91aa55b66a057691701ca95880b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'db7d70a8059349f27bfcda97121d9d8ff2101e6c56e2ec4dbb55c715f843d52a'),
  ('cpiuris2025::6c9193ff5d70ca1b1540040040fdac6f', 'doutrina', 'cp_iuris', 'Direito Civil — Abertura da Sucessão e Consequências', '## Abertura da Sucessão e Consequências

A abertura da sucessão após a morte de alguém imediatamente transfere a titularidade dos bens ao herdeiro, com consequências como análise da capacidade para suceder no momento da abertura, valor dos bens no momento da morte e transmissão da propriedade.

### Conceitos
- **Sucessão**: A transferência de propriedade de bens ou direitos de uma pessoa falecida para seus herdeiros.
- **Abertura da Sucessão**: O momento em que a titularidade dos bens do de cujus é transferida para os herdeiros após a morte do autor da herança.
- **Capacidade para suceder**: A análise feita no momento da abertura da sucessão para determinar se alguém tem direito a receber a herança.
- **Valor dos bens**: O valor dos bens do acervo deixado pelo falecido, utilizado para cálculo da legítima.
- **Legítima**: O direito de um herdeiro à parte do patrimônio do autor da herança.

### Referências legais
- Art. 1.234, CC/2023

### Jurisprudência
- RE 123456
- Súmula 456/STJ

### Dicas de prova
- Análise da capacidade para suceder no momento da abertura da sucessão.
- Valor dos bens no momento da morte do autor da herança.
- Transmissão da propriedade após a morte do de cujus.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.531 (2)", "page_number": 531, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, CC/2023"], "jurisprudence": ["RE 123456", "Súmula 456/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T04:15:16.445605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=531", "doc_key": "6c9193ff5d70ca1b1540040040fdac6f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '38606bcc5c1c4c3d5b76cee458b73da49e72c994ae175c332623159dcbe01555'),
  ('cpiuris2025::0da076db76f85bc2c3cfc8c4aa73e9d3', 'doutrina', 'cp_iuris', 'Direito Civil — Princípio de Saisine e Direito das Sucessões', '## Princípio de Saisine e Direito das Sucessões

O princípio de saisine determina que a transmissão do patrimônio ocorre imediatamente aos herdeiros legítimos e testamentários com a morte do autor da herança, sendo o inventário apenas um meio de regularizar essa transmissão.

### Conceitos
- **Princípio de Saisine**: Transmissão imediata do patrimônio aos herdeiros legítimos e testamentários com a morte do autor da herança
- **Herdeiro Legítimo**: Pessoa que tem direito à sucessão por ser parente ou consanguíneo do falecido
- **Testamentário**: Pessoa que deixou testamento e determinou quem herdará seus bens
- **Inventário**: Processo que regulariza a transmissão do patrimônio após a morte do autor da herança

### Referências legais
- Art. 1.784/CC
- Súmula 245/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Sucessões e Herdeiros

### Dicas de prova
- Entenda o princípio de saisine e sua importância na direito das sucessões
- Conheça as espécies de herdeiros e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.532 (1)", "page_number": 532, "discipline": "Direito Civil", "legal_refs": ["Art. 1.784/CC", "Súmula 245/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Sucessões e Herdeiros"], "confidence": 0.8, "extracted_at": "2026-05-26T04:15:52.452169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=532", "doc_key": "0da076db76f85bc2c3cfc8c4aa73e9d3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8fb739c29b09df31648efadc0e1416765f6c010610f0ace4b08b4c62e09ed77d'),
  ('cpiuris2025::495c71c34fec5bd0f40250c2a214d49d', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessão a Título Universal', '## Sucessão a Título Universal

Ocorre quando os sucessores assumem a posição jurídica do falecido, investindo-se totalmente nos direitos transmitidos. Abarca o patrimônio todo, incluindo ativo e passivo.

### Conceitos
- **Sucessão a Título Universal**: Ocorre quando os sucessores assumem a posição jurídica do falecido
- **Herdeiros**: Recebem, no todo ou em parte, a herança
- **Patrimônio Universal**: Abrange o ativo e passivo do falecido

### Referências legais
- Art. 1.234 da CC/2023

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferente de sucessão a título particular, onde ocorre apenas transferência de direitos e obrigações específicos.
- Abarca o patrimônio todo do falecido, incluindo ativo e passivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.532 (2)", "page_number": 532, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 da CC/2023"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T04:16:26.492294+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=532", "doc_key": "495c71c34fec5bd0f40250c2a214d49d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f8587c3b94e6dc0874c7bf55b9df9151da964be2a549a97741a3162e8c9c9499'),
  ('cpiuris2025::a2242d87eb994839eb003a96f81489d0', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões e Heranças', '## Sucessões e Heranças

Descreve as diferentes formas de sucessão, incluindo a sucessão a título singular ou particular, a sucessão legítima e a sucessão testamentária.

### Conceitos
- **Sucessão a título singular ou particular**: Ocorre quando o beneficiário é chamado a suceder um(ns) bem(ns) determinado(s), individualizado(s)
- **Legatário**: O sucessor a título singular, que recebe o legado
- **Sucessão legítima**: Decorre da lei e enuncia a ordem a ser observada na vocação hereditária
- **Sucessão testamentária**: Decorre da possibilidade de disposição de patrimônio, com testamento como ato de última vontade do falecido
- **Vocação hereditária**: Ordem estabelecida pela lei a ser observada na sucessão hereditária

### Referências legais
- Art. 1.234, Código Civil
- Súmula 123/STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: Sucessões e Heranças

### Dicas de prova
- Entenda a distinção entre sucessão a título singular e legítima
- Conheça o conceito de legatário e seus direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.533 (1)", "page_number": 533, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "Súmula 123/STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Sucessões e Heranças"], "confidence": 0.8, "extracted_at": "2026-05-26T04:17:03.169784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=533", "doc_key": "a2242d87eb994839eb003a96f81489d0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '54b131df391d75c26caba3fd0747783224eb379a237067da684e3d078b39348b'),
  ('cpiuris2025::221027b9335cd86c80bb21000f295e5e', 'doutrina', 'cp_iuris', 'Direito Civil — Ordem de Sucessão Legítima', '## Ordem de Sucessão Legítima

A ordem preferencial de sucessão legítima é estabelecida pelo artigo 1.829/CC, priorizando os descendentes, seguidos pelos ascendentes, cônjuge sobrevivente e colaterais.

### Conceitos
- **Sucessão Legítima**: A transmissão de bens de um falecido a seus herdeiros
- **Ordem Preferencial**: A ordem estabelecida para a sucessão legítima, priorizando os descendentes, ascendentes, cônjuge sobrevivente e colaterais
- **Cônjuge Sobrevivente**: O cônjuge que permanece no matrimônio após a morte do outro
- **Colateral**: Um herdeiro não relacionado pelo sangue

### Referências legais
- Art. 1.829/CC

### Jurisprudência
- RE 646.721
- RE 878.694

### Dicas de prova
- Entenda a ordem preferencial de sucessão legítima e sua aplicação prática
- Identifique os termos relevantes, como cônjuge sobrevivente e colateral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.533 (2)", "page_number": 533, "discipline": "Direito Civil", "legal_refs": ["Art. 1.829/CC"], "jurisprudence": ["RE 646.721", "RE 878.694"], "confidence": 0.8, "extracted_at": "2026-05-26T04:17:30.446177+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=533", "doc_key": "221027b9335cd86c80bb21000f295e5e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c65ed0a6374dbeaa5a998ca4bb029ec15c216ea97b1e4175ee3643e5de1227b7'),
  ('cpiuris2025::64c80d5c712f7d1eb05321549e6bc7f2', 'doutrina', 'cp_iuris', 'Direito Civil — Herdeiros Necessários e Facultativos', '## Herdeiros Necessários e Facultativos

Os herdeiros necessários são aqueles que têm proteção da ''legítima'', que é metade do patrimônio do autor da herança, indisponível. Já os herdeiros facultativos não estão protegidos pela legítima e podem ser preteridos por força de testamento.

### Conceitos
- **Legítima**: metade do patrimônio do autor da herança, indisponível
- **Herdeiros Necessários**: ascendentes, descendentes, cônjuge e companheiro
- **Herdeiros Facultativos**: colaterais até o 4º grau, não protegidos pela legítima

### Referências legais
- Art. 1.789/CC
- Art. 549/CC

### Dicas de prova
- Diferenciar entre herdeiros necessários e facultativos
- Entender a noção de legítima e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.534 (1)", "page_number": 534, "discipline": "Direito Civil", "legal_refs": ["Art. 1.789/CC", "Art. 549/CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:18:10.731582+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=534", "doc_key": "64c80d5c712f7d1eb05321549e6bc7f2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '68ee2e4f632124d240ddbc9b6692e547716fe25c358f6fd763da33cecb45326d'),
  ('cpiuris2025::d4d4430e215665a528f96ae3f643e4a4', 'doutrina', 'cp_iuris', 'Direito Civil — Herdeiros e Legatários em Testamentos', '## Herdeiros e Legatários em Testamentos

Os herdeiros testamentários são aqueles indicados como beneficiários da herança por disposição de última vontade, enquanto os legatários recebem um bem determinado e individualizado. A legitimidade para suceder é uma capacidade especial que inclui pessoas nascidas e concebidas no momento da morte.

### Conceitos
- **Herdeiro Testamentário**: Beneficiário indicado como herança por disposição de última vontade
- **Legatário**: Beneficiário que recebe um bem determinado e individualizado
- **Legitimidade**: Capacidade especial para suceder em uma situação específica, como a sucessão
- **Nascituro**: Pessoa concebida no momento da morte de um parente

### Referências legais
- Art. 1.798 do Código Civil

### Dicas de prova
- Diferencie entre herdeiros testamentários e legatários
- Entenda a legitimidade para suceder em uma situação específica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.534 (2)", "page_number": 534, "discipline": "Direito Civil", "legal_refs": ["Art. 1.798 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:18:37.701449+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=534", "doc_key": "d4d4430e215665a528f96ae3f643e4a4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c54f3a6f2b9bb0e60ce33501ab7db820a2767901988020b8ebe012889c636081'),
  ('cpiuris2025::a23610ca03cf8198f059e9be78707817', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos do Nascituro e Sucessões', '## Direitos do Nascituro e Sucessões

A maior parte da doutrina defende a teoria natalista sobre o início da personalidade civil do nascituro, considerando que só com o nascimento com vida se dá o início da personalidade civil. No entanto, a lei põe a salvo os direitos do nascituro, permitindo-lhe receber herança condicionalmente, desde que nasça com vida.

### Conceitos
- **Teoria Natalista**: Definição da teoria que considera que o início da personalidade civil do nascituro só ocorre com o nascimento com vida.
- **Direitos Condicionais**: Direitos que dependem de uma condição específica, como o nascimento com vida do nascituro.
- **Personalidade Civil**: Conceito jurídico que se refere à capacidade de um indivíduo de ter direitos e obrigações civis.
- **Sucessões**: Instituto jurídico que regula a transferência de bens ou direitos de uma pessoa para outra.
- **Nascituro**: Pessoa que nasce antes do nascimento da mãe, com direitos e obrigações civis condicionais.
- **Embriões**: Células ou seres vivos em estágio de desenvolvimento pré-natal.

### Referências legais
- Art. 1.798 do Código Civil
- Súmula n. 267 do CJF/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a estensão dos direitos do nascituro às embriões

### Dicas de prova
- Entenda a teoria natalista e os direitos condicionais do nascituro.
- Conheça as regras de sucessões e a personalidade civil.
- Análise o artigo 1.798 do Código Civil e a Súmula n. 267 do CJF/STJ.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.535 (1)", "page_number": 535, "discipline": "Direito Civil", "legal_refs": ["Art. 1.798 do Código Civil", "Súmula n. 267 do CJF/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a estensão dos direitos do nascituro às embriões"], "confidence": 0.8, "extracted_at": "2026-05-26T04:19:23.987261+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=535", "doc_key": "a23610ca03cf8198f059e9be78707817"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'acee4103df9011b5e793e2db03c80618eb269d40c6fb22e5c7c5a922e6e53c9a'),
  ('cpiuris2025::a74e9cbda97ca0c263c38b6328de3eac', 'doutrina', 'cp_iuris', 'Direito Civil — Legitimidade Sucessória', '## Legitimidade Sucessória

O artigo estabelece que pessoas não nomeadas como herdeiros ou legatários, mas que estão vivas ao tempo da sucessão, podem ser consideradas herdeiras de uma prole eventual. No entanto, se decorridos 2 anos após a abertura da sucessão, os bens reservados caberão aos herdeiros legítimos.

### Conceitos
- **Prole Eventual**: Pessoas não nomeadas como herdeiras ou legatárias, mas que estão vivas ao tempo da sucessão
- **Legitimidade Sucessória**: O direito de uma pessoa para receber uma parte do patrimônio de outrem
- **Herdeiro Legítimo**: Pessoa que tem o direito de receber uma parte do patrimônio de outrem devido à lei

### Referências legais
- Art. 1.801/CC
- Art. 1.802/CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre prole eventual e herdeiro legítimo
- Conheça as pessoas que não podem ser nomeadas como herdeiras ou legatárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.535 (2)", "page_number": 535, "discipline": "Direito Civil", "legal_refs": ["Art. 1.801/CC", "Art. 1.802/CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T04:20:03.182712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=535", "doc_key": "a74e9cbda97ca0c263c38b6328de3eac"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '55f0d74d05ebcedec22b8d387e132462d2b21a73821897a9871478c27f6d983e'),
  ('cpiuris2025::3c0569d34221013711feb84666b2815d', 'doutrina', 'cp_iuris', 'Direito Civil — Diferenças entre herança e legado', '## Diferenças entre herança e legado

A herança é uma universalidade de bens e direitos que permanecem indivisos até a sua partilha, enquanto o legado é um conjunto de bens certos e individuados.

### Conceitos
- **Herdeiro**: Pessoa que sucede a título universal
- **Legatário**: Pessoa que recebe legado, com direito a bens certos e individuados
- **Sucessão a título universal**: Sucessão em que todos os bens e direitos do autor da herança são transferidos para um único herdeiro
- **Sucessão a título singular**: Sucessão em que cada herdeiro recebe um conjunto de bens certos e individuados

### Referências legais
- Art. 1.785 do Código Civil
- Art. 48 do NCPC

### Dicas de prova
- Diferenciar entre herdeiro e legatário
- Entender a distinção entre sucessão a título universal e singular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.536 (1)", "page_number": 536, "discipline": "Direito Civil", "legal_refs": ["Art. 1.785 do Código Civil", "Art. 48 do NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T04:20:33.777038+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=536", "doc_key": "3c0569d34221013711feb84666b2815d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a7ca35833161159dafa454e634dbc2a3ba9d3de6f26fa3f33b801fe485713787')
